INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('17ed560a-a26e-5cf2-a0ac-50f085202870', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 5, 13, 'አሁንም እርሱ እግዚአብሔር ይመረምራል፤ እናንተ ግን እግዚአብሔር ሁልጊዜ የሚያደርገውን አታውቁም።'),
  ('f2e60b66-e190-552b-adf0-8f101f2cb03c', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 6, 14, 'በሰው ልቡና ያለ ረቂቅ ምሥጢርን የማታውቁ፥ የልቡናውንም አሳብ የማታስተውሉ ይህን ሁሉ ያደረገ እግዚአብሔርን እንዴት ትመረምራላችሁ? ልቡናውንስ መርምራችሁ ታውቁ ዘንድ እንዴት ትወዳላችሁ? ምክሩንስ መርምራችሁ ታገኙ ዘንድ እንዴት ትመረምራላችሁ? ወንድሞች ሆይ፥ ለእናንተ አግባባችሁ አይደለም፤ አምላካችን እግዚአብሔርንም አታሳዝኑት።'),
  ('d1caebf6-7905-57a3-a6c3-7399d115c043', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 7, 15, 'በእነዚህ በአምስቱ ቀኖች ይረዳን ዘንድ ባይፈቅድ በማንኛውም ቀን ቢሆን በፈቀደ ጊዜ ሊያድነን፥ ወይም በጠላቶቻችን ፊት ሊያጠፋን ሥልጣን አለው።'),
  ('56ff3763-b635-58d9-a66b-8f98bd5d31e2', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 8, 16, 'እግዚአብሔር እንደ ሰው የሚጨክን አይደለምና እንደ ሰውም የሚቀየም አይደለምና፥ እናንተ አምላካችን እግዚአብሔርን አትፈታተኑት።'),
  ('71eff6c2-5e10-555d-ae03-569d9ebc1e03', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 9, 17, 'ነገር ግን ከእርሱ የምትገኝ ድኅነትን ደጅ ጥኑ፤ ቃላችንንም ሰምቶ ይረዳን ዘንድ ይፈቅድ እንደ ሆነ ለምኑት።'),
  ('9ca4ee9a-67d5-5935-a732-904c660c4f67', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 10, 18, '“በዘመናችን ወይም ዛሬ በቀድሞ ዘመን እንደ ተደረገ ከእኛ መካከል ወገንም ቢሆን፥ ነገድም ቢሆን፥ ከተማም ቢሆን፥ መንደርም ቢሆን በሰው እጅ ለተሠሩ ጣዖታት ለመስገድ የተነሣ የለምና።'),
  ('8b7f9fe0-9bac-5ce2-a574-6279e4448a1b', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 11, 19, 'ስለዚህም ነገር አባቶቻችን ለመበርበርና ለጦር ሆኑ፤ በጠላቶቻቸውም ፊት ጽኑ አወዳደቅን ወደቁ።'),
  ('8c8f01aa-f2eb-5f2f-aa52-747a3d5fca6c', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 12, 20, 'እኛ ግን ያለእርሱ ሌላ አምላክ አናውቅም፤ ስለዚህ እኛን ወይም ወገኖቻችንን ቸል እንደማይለን በእርሱ እናምናለን።'),
  ('fa438492-2040-5fc7-a074-8dbdefb8d7e3', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 13, 21, 'እኛ በተያዝን ጊዜ ይሁዳ ሁሉ ይያዛል፤ ንዋየ ቅድሳታችንም ይዘረፋል፤ በመቅደሱም መርከስ ከአንደበታችን ይመረመራል።'),
  ('f5a6af3d-6309-56de-ade0-a3091a25a964', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 14, 22, 'የወንድሞቻችን መገደል፥ የሀገራችንም መዘረፍ፥ የርስታችንም ምድረ በዳ መሆን በሚገዙን አሕዛብ ዘንድ በእኛ ላይ ይመለሳል፤ ገንዘብ በሚያደርጉን ፊትም በዚያ የተሰነካከልንና መገዳደሪያ እንሆናለን።'),
  ('fef5f613-bd4b-5f91-a092-42ee5be74f2e', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 15, 23, 'መገዛታችንም ያለ ምስጋና ይሆናልና፥ አምላካችን እግዚአብሔር መዋረዳችንን አላየምና።'),
  ('9fe48764-9164-58b6-aa3d-479b5dfcf189', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 16, 24, '“አሁንም ወንድሞቻችን ሆይ፥ ለባልንጀሮቻችን ንገሩአቸው፤ እኛን ያዳምጣሉና፥ ልቡናቸውም ወደ እኛ ተሰቅሏልና፥ መሠዊያዉና ቤተ መቅደሱም በእኛ ጸንቶ ይኖራልና።'),
  ('2b5b6463-2559-5500-aa1a-f8d592548a7c', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 17, 25, 'አባቶቻችንን እንደ ፈተናቸው የሚፈትነን አምላካችን እግዚአብሔርን በዚህ ሁሉ እናመስግነው።'),
  ('6b68e4ae-fb6c-5dff-a482-b000f79d68ee', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 18, 26, 'ለአባቶቻችን ያደረገውን ሁሉ አብርሃምን እንደ ፈተነው፥ ይስሐቅንም እንደ ፈተነው፥ ያዕቆብንም የእናቱን ወንድም የላባን በጎች ሲጠብቅ በሶርያ መስጴጦምያ እንደ ፈተነው አስቡ።'),
  ('5943afb1-b160-5be7-acdb-5609045c31bc', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 19, 27, 'እነርሱንም በፈተናቸውና ልቡናቸውን በመረመረ ጊዜ እኛን የበደለን አይደለም፤ እግዚአብሔር የሚቀርቡትን ሰዎች ይቅር ይላቸው ዘንድ ነው እንጂ፥ ሊያጠፋቸው አይደለምና።”'),
  ('0cb96465-e0cd-5256-adef-a4a3eff4fad7', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 20, 28, 'ዖዝያንም አላት፥ “የተናገርሽውን ሁሉ በበጎ ልቡና ተናገርሽ፤ ቃልሽንም የሚቃወመው የለም።'),
  ('583fcad7-5e38-5e2c-a946-b1bb71577041', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 21, 29, 'ጥበብሽ የተሰማው ከዛሬ ጀምሮ አይደለምና፥ ከመጀመሪያው ዘመንሽ ጀምሮ ሰው ሁሉ በጥበብሽ ዐወቀሽ እንጂ፥ የልቡናሽ ተፈጥሮ ደግ ነውና።'),
  ('54c4336d-3ac8-57cb-a3a4-35c82c436d16', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 22, 30, 'ነገር ግን ሕዝቡ ፈጽመው ተጠምተዋልና እንዳሉን እናደርግ ዘንድ ዘበዘቡን፤ ልንለውጠው የማይቻለንን መሐላ አመጡብን።'),
  ('41d527d9-91a0-59f2-abf9-45ee69818617', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 23, 31, 'አሁንም አንቺ እግዚአብሔርን የምትፈሪ ሴት ነሽና እግዚአብሔር ዝናምን ያዘንምልን ዘንድ፥ ኵሬያችንም ይመላ ዘንድ፥ እንግዲህ ወዲህም እንዳንጠማ ለምኝልን።”'),
  ('42bb9451-750c-588a-acf1-94be01f377e1', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 24, 32, 'ዮዲትም አለቻቸው፥ “ስሙኝ ለልጅ ልጅ የሚነገር ሥራን እሠራለሁ።'),
  ('11bff66a-232d-5ea7-ad45-c430cc655edd', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 25, 33, 'እናንተ ግን በዚች ሌሊት በበሩ ቁሙ፤ እኔም ከብላቴናዬ ጋር እወጣለሁ፤ ሀገራችንን አሳልፈን ለጠላቶቻችን እንሰጣለን በምትሉበት በእነዚያም ወራቶች የእስራኤል አምላክ እግዚአብሔር በእጄ ይረዳል።'),
  ('d9490629-1fcc-513a-a472-3f88ad7e6c34', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 26, 34, 'እናንተ ግን የምሠራውን ሥራ አትመርምሩኝ፤ እኔ የምሠራው ሥራ እስኪፈጸም ድረስ አልነግራችሁምና።”'),
  ('dfdf7e00-adee-5e14-a889-998af8ec5df0', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 27, 35, 'ዖዝያንና አለቆቻቸውም፥ “በሰላም ሂጂ፤ እግዚአብሔርም በፊትሽ ይሁን፤ ጠላቶቻችንንም ይበቀል” አሏት።'),
  ('2f8cd7bc-b598-51f9-aa6a-40c80e13ca9e', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 28, 36, 'ተመልሰውም ወደ ባልንጀሮቻቸው ሄዱ።'),
  ('c232d7f4-8f82-523b-a371-8fb857b56776', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 1, 1, 'ዮዲት ግን በግንባሯ ተደፍታ በምድር ላይ ወደቀች፤ በራሷም ላይ ትቢያ ነሰነሰች፤ የምትለብሰውንም ማቅ አሳየች፤ በኢየሩሳሌምም ባለው በእግዚአብሔር ቤተ መቅደስ የሠርክ ዕጣን በሚቀርብበት ጊዜ ዮዲት በታላቅ ቃል ወደ እግዚአብሔር ጮኸች፤ እንዲህም አለች፦'),
  ('d20a4612-ccdc-5475-a9ce-2f40d70b6af0', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 2, 2, '“በማኅፀን ያለ ጽንስን ያጠፉ፥ ድንግልንም ያጐሰቈሉ፥ ልብሷንም የገፈፉ፥ በከተማም በአራቱ ማዕዘን ለመገዳደር ማኅፀንን ያሳደፉ ጠላቶችን ይበቀል ዘንድ በእጁ ሰይፍን የሰጠኸው የአባቴ የስምዖን አምላክ ሆይ፥ አንተ እንዲህ አይደለም አልህ፤ እነርሱ ግን አደረጉት።'),
  ('290c3d22-f9d9-5032-a22b-f0d7fd752f45', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 3, 3, 'ስለዚህም አለቆቻቸውን ለመገደል አሳልፈህ ሰጠሃቸው፤ መኝታቸውም በተገደሉት ባሮች ደም ተነከረ፤ ባሮችን ከጌቶቻቸው ጋር፥ ጌቶችንም በዙፋኖቻቸው ላይ ገደልሃቸው።'),
  ('a399b64a-2b39-5ee9-a94e-45d60d9bd8d9', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 4, 4, 'ሚስቶቻቸውና ልጆቻቸው ተማረኩ፤ በአንተ ዘንድ የተወደዱ፥ ለአምላክነትህም የቀኑ፥ የረከሰ ደማቸውንም የተጸየፉ፥ ትረዳቸውም ዘንድ የለመኑ የልጆችን ምርኮ ሁሉ ተካፈሉ፤ አምላኬ እግዚአብሔር ሆይ፥ እኔን መበለቲቱን ስማኝ።'),
  ('6646473e-42ca-543b-a689-270de3286c88', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 5, 5, 'ከዚህ አስቀድሞና ከዚያም በኋላ የሆነውን አንተ አድርገሃልና የዛሬውንና የሚመጣውንም ታውቀዋለህ፤ አንተም በምታውቀው ሆነ።'),
  ('d33b30cf-a78d-53c8-a451-4c1e51162a63', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 6, 6, 'ምክርህ የቀና ነው፤ ሥርዐትህ የተዘጋጀ ነውና፥ ፍርድህንም አስቀድመህ ባወቅህ ፈርደሃልና እነሆ፥ መጣን ይሉሃል፤'),
  ('a71c40cc-8684-5c38-a73c-478adc843f48', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 7, 7, '“እነሆ፥ የአሦር ሰዎች ከሠራዊታቸው ጋር በዝተዋልና፥ በፈረሶቻቸውም ላይ ከፍ ከፍ ብለዋልና፥ በፈረስም የተቀመጡ ሰዎች በኀይላቸው ታምነዋልና፥ አርበኞችም በጽናታቸው፥ በቀስታቸውና በጦራቸው፥ በምድር ነጎዳቸውም ታምነዋልና አንተ አርበኞችን የምታጠፋ አምላክ እንደ ሆንህ አላወቁህምና ስምህም አሸናፊ እንደ ሆነ አልተገነዘቡም።'),
  ('5a8079e9-9871-587e-aeb8-9b3c72d59895', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 8, 8, 'አንተ ከሠራዊታቸው ጋር በከሃሊነትህ አጥፋቸው፤ ቤተ መቅደስን ያጐሰቍሉ ዘንድ፥ የስምህ ጌትነት ማደሪያ የሆነች ደብተራ ኦሪትንም ያሳድፉ ዘንድ መክረዋልና፥ በብረትም የመሠዊያህን ቀንዶች አፍርሰዋልና በቍጣህ ኀይላቸውን አጥፋ።'),
  ('bbf39b71-b30e-558b-a335-903c39152265', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 9, 9, 'ትዕቢታቸውን ተመልከት፤ በራሳቸውም ላይ ቍጣህን አምጣ። እንደ አሰብሁት እፈጽም ዘንድ በእኔ በመበለቲቱ እጅ ኀይልን አድርግ።'),
  ('8ef5caa6-e2cb-5ee0-ad3f-8394bb6101c1', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 10, 10, 'በአንደበቴ ጥበብ ሎሌውን ከጌታው፥ ጌታውንም ከሎሌው ጋር ግደል። ግርማቸውን በእኔ በሴቲቱ እጅ አጥፋ።'),
  ('07382ced-626c-5426-a1bd-8b4834cd291f', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 11, 11, 'ብርታትህ በብዙዎች አይደለምና፥ ኀይልህም በኀያላን ሰዎች አይደለምና፤ ነገር ግን አንተ የትሑታን አምላክ ነህ፤ የጥቂቶች ረዳት ነህ፤ የበሽተኞችም ፈዋሽ አንተ ነህ፤ ለጠፉትም ጠባቂያቸው አንተ ነህ፤ ተስፋ የቈረጡ ሰዎችንም የምታድናቸው አንተ ነህ።'),
  ('2b27ea18-e580-5c45-a328-e2f289447ffb', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 12, 12, 'አወን አቤቱ የአባቴ አምላክ፥ የእስራኤልም የርስታቸው አምላክ፥ የሰማይና የምድር አምላክ፥ ውኃውን የፈጠርህ፥ የፍጥረታት ሁሉ ንጉሥ አንተ ጸሎቴን ስማ።'),
  ('50387444-163f-5f88-ab4d-bde4cd3a3e09', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 13, 13, 'የቃሌንም ጥበብ በሕግህና በቤተ መቅደስህ በደብረ ጽዮንና በልጆችህ ንብረት ቤት ላይ ክፉ ነገርን የመከሩ ጠላቶችን እንዲያቈስላቸውና እንዲያጠፋቸው አድርግ።'),
  ('52dece8e-f4dc-570f-a7e0-1ee20b7705b7', '8655bb6f-2ecb-5c91-a516-fc88fb498ae0', 'c2f7094f-373b-5e63-a997-2736ee8d5aaf', 14, 14, 'የብርታትና የኀይል ሁሉ አምላክ አንተ እግዚአብሔር እንደ ሆንህ፥ የእስራኤልንም ወገን ከአንተ በቀር ሌላ የሚያጸናቸው እንደ ሌለ ለሕዝቡና ለአሕዛቡ ሁሉ እንዲያውቁት አድርግ።”'),
  ('294790fc-eadf-594f-a315-a6cb9e8a0ece', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 1, 1, 'ከዚህም በኋላ ወደ እስራኤል አምላክ መለመኗን ከጨረሰችና ይህንም ነገር ሁሉ ከፈጸመች በኋላ፥'),
  ('a52b0feb-fcf8-51ce-ac53-ace7d344a10c', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 2, 2, 'ከወደቀችበት ቦታ ተነሣች፤ ብላቴናዋንም ጠርታ በሰንበታትና በበዓላት ቀኖች ወደምትቀመጥበት ቤትዋ ወረደች።'),
  ('4e811ab1-7cb4-565e-a0dc-656341c8abcd', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 3, 3, 'የለበሰችውንም ማቅ አወለቀች፤ የመበለትነትዋንም ልብስ ለበሰች፥ ሰውነትዋንም በውኃ ታጠበች፤ ጠጕርዋንም ያማረ ሽቱ ተቀባች፤ ጠጕርዋንም ተሠራች፤ አጌጠችም፤ ከዚህም በኋላ ባሏ ምናሴ በሕይወት በነበረ ጊዜ የምትለብሰውን የደስታ ልብሷን ለበሰች።'),
  ('0cf3bda5-1e23-582b-aeee-acde976dca0d', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 4, 4, 'ጫማዋንም ተጫማች፤ አልቦዋንና ቀለበትዋን፥ አምባርዋንና ጉትቻዋንም አደረገች፤ ጌጡንም ሁሉ አጌጠች፤ የሚያዩአትንም ወንዶች ሁሉ ዐይን እስክታስት ድረስ ፈጽማ አጌጠች።'),
  ('936b6e40-9c3e-5f3f-a437-5567c2642f3f', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 5, 5, 'የወይኑን ገንቦና የዘይቱን ማሰሮ ትሸከም ዘንድ ለብላቴናዋ ሰጠቻት፤ ስልቅ በሶውን፥ የስንዴ አምባሻውንና በለሱን በስልቻዋ መላች፤ ገንዘብዋንም ሁሉ አንግታ አሸከመቻት።'),
  ('9e32e6de-2179-5a8e-a2b3-9f42ef47f824', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 6, 6, 'ወደ ቤጤልዋ ከተማ በርም ሄደች፤ ዖዝያንን፥ ያገር ሽማግሌዎችን ከርሚንና ከብሪምንም በዚያ ቆመው አገኘቻቸው።'),
  ('356da4fc-1690-507f-a9a8-0e5a57f827f3', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 7, 7, 'ፊትዋ ተለውጦ፥ በሚያስደንቅ ሁኔታ ልብሷን ለብሳ ባዩአት ጊዜ ከደም ግባቷ ማማር የተነሣ እጅግ ተደነቁ፤ እንዲህም አሏት፦'),
  ('816c0dfa-3c06-5efb-a8f2-9463757a22fc', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 8, 8, '“ለኢየሩሳሌም ልዕልናና ለእስራኤል ልጆች ክብር በልብሽ ያሰብሽውን ታደርጊ ዘንድ የአባቶቻችን አምላክ ሞገስን ይስጥሽ።” እርሷም ለእግዚአብሔር ሰገደች።'),
  ('e04b4d1c-e391-5738-a37f-f8831a0e31e5', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 9, 9, 'እንዲህም አለቻቸው፥ “አሁንም ከእናንተ ጋራ የተናገርሁትንነገር ወጥቼ አደርግ ዘንድ የከተማውን በር የሚከፍትልኝ ሰው እዘዙልኝ፤” እንደ ጠየቀችም ይከፍቱላት ዘንድ ጐልማሶችን አዘዙአቸው።'),
  ('e0a6a5c3-09fb-59ab-a800-1b5a67a5ee81', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 10, 10, 'ይህንም በአደረጉ ጊዜ ዮዲት ወጣች፤ ብላቴናዋም ከእርሷ ጋር ወጣች፤ የከተማው ሰዎችም ካንባው ወርዳ ከሸለቆው እስክታልፍ ድረስ ያዩአት ነበር፤ ከዚህ በኋላ ግን አላዩአትም።'),
  ('6eb3ed6a-e113-52f1-a9ea-533aa8a572e3', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 11, 11, 'በቀጥታም በሸለቆው ሄደች፤ የአሦራውያንም ዘበኞች አገኙአት።'),
  ('0c11593a-1479-5e43-a078-bbf10419df25', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 12, 12, 'ይዘውም መረመሩአት፤ እንዲህም አሏት፥ “አንቺ ማን ነሽ? ከየት መጣሽ? ወዴትስ ትሄጃለሽ?” እርስዋም አለቻቸው፥ “እኔ ከዕብራውያን የተወለድሁ ነኝ፤ ሀገራቸውን ለእናንተ አሳልፈው ሊሰጡ በወደዱ ጊዜ ከእነርሱ ኰብልዬ መጣሁ።'),
  ('f6898d5c-63b2-50bf-a0b5-3f32f94a7233', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 13, 13, 'እኔ እውነተኛ ነገርን እነግረው ዘንድ፥ የምትሄዱበትንም ጎዳና አሳየው ዘንድ ወደ ቢትወደዳችሁ ወደ ሆሎፎርኒስ አስቀድሜ መጣሁ፤ አውራጃቸውንም ሁሉ ገንዘብ ታደርጋላችሁ፤ ከሰዎቻችሁ አንድ ሰው ስንኳ የሚቈስል የለም።”'),
  ('e71f4a0b-17ca-5023-a57c-700fd87dd60f', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 14, 14, 'እነዚያም ሰዎች ቃልዋን በሰሙ ጊዜ፥ ፊትዋንም ባዩ ጊዜ፥ ደም ግባትዋም ፈጽሞ የተደነቀ እንደ ሆነ ባዩ ጊዜ እንዲህ አሏት፦'),
  ('2b3805d0-0745-5e49-a546-dec0d36015c0', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 15, 15, '“ወደ ጌታችን ፈጥነሽ የወረድሽ አንቺ ሕይወትሽን አዳንሽ። አሁንም ወደ ድንኳኑ ሂጂ፤ ወደ እርሱ የሚያደርስሽን ሰው ከእኛ እንልካለን።'),
  ('7fde5033-d678-5c14-a2c4-d2cef693c927', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 16, 16, 'በፊቱም በቆምሽ ጊዜ ይህን ነገርሽን ንገሪው እንጂ ልቡናሽ አይፍራ፤ በጎ ነገርን ያደርግልሻል።”'),
  ('9cd97a84-51be-5d27-af2e-f547b99e14b7', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 17, 17, 'ከእርስዋና ከብላቴናዋ ጋር የሚሄዱ አንድ መቶ ሰዎችን መረጡ፤ ወደ ሆሎፎርኒስ ድንኳንም አደረሷት።'),
  ('a3b8de8b-1818-5fef-aedb-806e9e6b2622', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 18, 18, 'ሕዝቡም ሁሉ ተሰበሰቡ፤ በድንኳኑ ፊት እንዳለች ዜናዋ በሰፈሩ ተሰምቶ ነበርና መጥተው ስለ እርሷ እስኪነግሩት ድረስ ከሆሎፎርኒስ ድንኳን ውጭ ከብበዋት ቆሙ።'),
  ('6307b316-6d43-563e-a78e-e5fd4c144629', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 19, 19, 'ደም ግባትዋንም አደነቁ፤ ስለ እርስዋም የእስራኤልን ልጆች አደነቁ፤ እርስ በርሳቸውም፥ “እንደ እነዚህ ያሉ ሴቶች ያሉትን ሕዝብ የሚንቅ ማን ነው? ዓለሙን ሁሉ ሊተነኰሉ ስለሚችሉ ከእነዚህ ሰዎች አንድ ሰውስ እንኳ ይቀር ዘንድ መልካም አይደለም” ተባባሉ።'),
  ('08945652-203b-5ae5-ae75-7920f25a14ca', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 20, 20, 'በሆሎፎርኒስ አጠገብ የተቀመጡ አሽከሮቹም ሁሉ መጥተው ወደ ድንኳኑ አገቧት።'),
  ('56c7bf26-1581-5208-a771-54a9d43e4cbf', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 21, 21, 'ሆሎፎርኒስም በወርቅ፥ በመረግድና ዋጋው ብዙ በሆነ ዕንቍ የተሠራ ነጭ ሐር በተነጠፈበት በዙፋኑ ላይ በድንኳኑ ውስጥ ተኝቶ ነበር።'),
  ('5b5fe161-0d61-56fe-aa32-f015ad76d41f', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 22, 22, 'የእርሷንም ነገር ነገሩት፤ ወደ አደባባይም ወጣ፤ በፊቱም የብር መቅረዝ ፋና ይበራ ነበር።'),
  ('b4b92c56-cd86-5b5a-a76e-d9ec258b609d', 'f271fa62-22c6-5c14-a491-d94558d843f3', '0ea9b0f4-c44d-5ac5-a07e-b2e21fd97237', 23, 23, 'ዮዲትም ወደ እርሱ በቀረበች ጊዜ አሽከሮቹ ቆመው ነበር፤ ከመልኳ ደም ግባት የተነሣ ሁሉም ተደነቁ፤ እርሷም በግንባሯ በምድር ላይ ወድቃ ሰገደችለት፤ አሽከሮቹም አነሡአት።'),
  ('0e382f0b-44e5-5534-abec-8990d46c00a7', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 1, 1, 'ሆሎፎርኒስም አላት፥ “አንቺ ሴት እመኝ፤ ለዓለሙ ሁሉ ንጉሥ ለናቡከደነፆር ይገዛ ዘንድ ራሱን ወደ እርሱ በመለሰ ሰው እኔ ክፉ ነገርን አላደርግምና ልቡናሽ አይፍራብሽ።'),
  ('97a80322-fa59-5291-aea2-8191439c5b96', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 2, 2, 'አሁንም በአንባ የሚኖሩ እነዚህ ወገኖችሽ የወነጀሉን ባይሆኑ ኖሮ በእነርሱ ላይ ጦሬን ባላነሣሁም ነበር፤ ነገር ግን ይህን ነገር እነርሱ አደረጉት።'),
  ('92b83daa-5980-5123-a7d2-db916b595de9', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 3, 3, 'አሁንም ንገሪኝ፤ ከእነርሱ ዘንድ ስለምን ነገር ኰብልለሽ ወደ እኛ መጣሽ? ነገር ግን ለሕይወትሽ መጥተሻልና በዚህ ሌሊት ለሁልጊዜም እንድትድኚ እመኝ።'),
  ('7f163bdc-3520-5cdb-aebf-97761d261dad', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 4, 4, 'ለንጉሡ ለጌታችን ለናቡከደነፆር አሽከሮች እንደምናደርግ ላንቺ ከምናደርገው በጎ ነገር በቀር በአንቺ ክፉ ነገር የሚያደርግ የለም።”'),
  ('5097cf3c-6458-5801-ac53-e0f5b6b1b291', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 5, 5, 'ዮዲትም አለችው፥ “የእኔን የባሪያህን ቃል ተቀበል፤ እኔ ባሪያህ በፊትህ እነግርሃለሁ፤ በዚች ሌሊት እኔ ለጌታዬ ሐሰት ነገርን አልነግርህም።'),
  ('0f39b104-55b2-5269-a499-d40efe4ee597', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 6, 6, 'የእኔን የአገልጋይህን ቃል ከተከተልህ እግዚአብሔር ለአንተ ፍጹም ሥራ ይሠራልሃል፤ አንተ ጌታዬ ካሰብኸው ነገር የሚወድቅ የለም።'),
  ('c7dd5d2e-7936-555e-a5ff-6e168dfe0c91', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 7, 7, 'የምድር ሁሉ ንጉሥ ናቡከደነፆር በሕይወት ይኑር! ፍጥረቱን ሁሉ ታቀና ዘንድ አንተን የላከ ኀይሉ ይኑር። በምድረ በዳ የሚኖሩ አውሬዎችና እንስሳ፥ በሰማይ የሚበሩ ወፎችም በኀይልህ ከናቡከደነፆርና ከቤቱ በታች ይኖራሉ እንጂ በዘመንህ ሰዎች ብቻ የሚገዙለት አይደለም።'),
  ('2a31f984-ac55-5e0c-a2fc-46ca33171e40', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 8, 8, 'ሥራህንና የልቡናህን ጥበብ ሰምተናልና በመንግሥቱ ሁሉ አንተ ብቻ ቸር እንደ ሆንህ፥ በአገሩ ሁሉ ተሰምትዋልና፥ በሥራህም ሁሉ አንተ ብርቱ ነህና፥ በሰልፍህም ሁሉ አንተ የተደነቅህ ነህና።'),
  ('254cf6a6-f68a-5306-aaf5-7956f95e5ce1', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 9, 9, '“አሁንም አክዮር በጉባኤያችሁ የአላችሁን ነገር ሰማን፤ ለአዳኑት የቤጤልዋ ሰዎችም ለአንተ የነገረህን ነገር ሁሉ ነገራቸው።'),
  ('1dbedc63-7d3a-53d7-aaa6-20b5d8fd649d', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 10, 10, 'አቤቱ ጌታዬ፥ ነገሩን አትናቅ፤ ነገር ግን እውነት ስለሆነ በልብህ አኑረው፤ ፈጣሪያቸውን ካልበደሉ ሕዝባችን ሊጠፉ አይችሉም፤ ሰይፍም ሊያጠፋቸው አይችልም።'),
  ('b3341e0b-e8b7-533e-a442-f94cdc48d393', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 11, 11, 'አሁንም ጌታዬ የተናቀና የማይረባ እንዳይሆን በፊትህ ሞታቸው ይደርስባቸው ዘንድ በበደላቸው ሥራ አምላካቸውን ያሳዘኑባት ኀጢአታቸው በዚህ ታገኛቸዋለች።'),
  ('63782791-df3d-5261-ab78-dfa6bbdf938e', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 12, 12, 'እህላቸውና ውኃቸው አልቋልና፥ ከብታቸውንም ይበሉ ዘንድ ተመልሰዋልና፥ እንዳይበሉ አምላካቸው በኦሪታቸው የከለከላቸውን ያን ይበሉ ዘንድ ደርሰዋልና።'),
  ('e05129b3-b4ed-5853-aeed-01730df01e98', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 13, 13, 'የእህላቸውን መጀመሪያና የወይናቸውን ዐሥራት በፈጣሪያችን ፊት በኢየሩሳሌም ለሚቆሙ ለካህናት የለዩትን፥ ከሕዝቡም ላንድ ሰው ስንኳ በእጃቸው መዳሰስ የማይገባቸውን ይህን ዘይቱንም ሊበሉ አስበዋልና፥'),
  ('d409dfdf-eb44-5111-a241-d59e0280507f', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 14, 14, 'ከአለቆችም ፈቃድ ያመጡላቸው ዘንድ ወደ ኢየሩሳሌም ላኩ፤ በዚያ የሚኖሩ ሰዎች እንዲህ አድርገዋልና።'),
  ('8742e2a7-c518-5da5-af34-c4a5265e0396', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 15, 15, 'ፈቃዱን ከነገሩአቸውና እንዲህ ከአደረጉ በኋላ እንዲህ አድርገዋልና በዚያ ጊዜ እግዚአብሔር በእጅህ ይጥላቸዋል።'),
  ('209721ef-eac5-58d2-a9a5-816c3b454aaa', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 16, 16, '“እኔ ባርያህ ይህን ሁሉ በዐወቅሁ ጊዜ ከእነርሱ ኰበለልሁ፤ የሰማውን ሰውንና ምድርን ሁሉ የሚያስደነግጥ ይህን ሥራ ከአንተ ጋር እሠራ ዘንድ እግዚአብሔር ላከኝ።'),
  ('6709c409-e45e-5691-a8d6-c49f9fc16ec4', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 17, 17, 'እኔ አገልጋይህ እግዚአብሔርን የምፈራ ነኝና የሰማይ አምላክ እግዚአብሔርንም በመዓልትና በሌሊት አገለግለዋለሁ። አቤቱ፥ አሁንም ከአንተ ጋር እኖራለሁ፤ ነገር ግን እኔ አገልጋይህ ወደ እግዚአብሔር እለምን ዘንድ ሌሊት ወደ ምድረ በዳ እወጣለሁ፤ መቼም የሠሩትን ኀጢአታቸውን ይነግረኛል።'),
  ('f58da39c-c669-5a21-af62-9568e326b65c', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 18, 18, 'መጥቼም ይህን እነግርሃለሁ፤ ከሠራዊትህ ሁሉ ጋር ትወጣለህ፤ የሚቃወምህም አይኖርም።'),
  ('a583692e-4cf7-5553-a9f5-150979947ab1', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 19, 19, 'ወደ ኢየሩሳሌም እስክትደርስም ድረስ በይሁዳ መካከል እወስድሃለሁ፤ በመካከሏም ዙፋንህን ትዘረጋለህ እረኛቸውም እንደ በተናቸው በጎች ፈጽመህ ትከብባቸዋለህ፤ ውሻም በፊትህ አይጮህብህም። ለእኔ እንዲህ ተነግሮኛልና። ይህንም ዐውቄ እነግርህ ዘንድ ተላክሁ።”'),
  ('c50424a2-924c-59fe-aca8-ba168e0cfb82', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 20, 20, 'ነገሯም ሆሎፎርኒስንና ሰዎቹን ሁሉ ደስ አሰኛቸው። እነርሱም ጥበቧን አደነቁ።'),
  ('1f322b86-e104-5e92-a3c7-c4cf1f526dd2', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 21, 21, 'እንዲህም አሉ፥ “ከምድር ዳርቻ እስከ ምድር ዳርቻ ድረስ በፊቷ ደም ግባትና በቃልዋ ጥበብ እንደዚች ሴት ያለ የለም።”'),
  ('bf8c571e-30f1-59fc-a726-f34bce0e0cbc', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 22, 22, 'ሆሎፎርኒስም አላት፥ “ኀይል በእጃችን፥ ጥፋትም ጌታዬን በካዱት ላይ ይሆን ዘንድ ከሕዝብሽ አስቀድሞ የላከሽ እግዚአብሔር በጎ ነገርን አደረገ።'),
  ('c5ba07e0-0f85-561d-ab38-e028d488f8e5', '340b9e73-97ac-56b4-a126-9ba12f6cb8df', '2087141e-3eee-5e35-ad8f-337c200aa339', 23, 23, 'አሁንም አንቺ በመልክሽ ውብ ነሽ፤ በቃልሽም የተባረክሽ ነሽ፤ እንዳልሽውም ከአደረግሽ አምላክሽ አምላኬ ይሆነኛል፤ አንቺም በንጉሡ በናቡከደነፆር ቤተ መንግሥት ትኖሪያለሽ፤ ስምሽም በሀገሩ ሁሉ ከፍ ከፍ ይላል።”'),
  ('8dd3319e-1ecd-54ff-a143-9287dad5b29b', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 1, 1, 'የብር ዕቃ ወደሚቀመጥበት ድንኳን ያገቧት ዘንድ አዘዘ፤ ለእርሱም ከሚያዘጋጁት ምግብ ይመግቧት ዘንድ፥ እርሱ ከሚጠጣው መጠጥም ያጠጧት ዘንድ አዘዘ።'),
  ('de530972-e671-5bec-a1f5-d5e9e49b3843', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 2, 2, 'ዮዲትም፥ “ካመጣሁት እህል እመገባለሁ እንጂ በደል እንዳይሆንብኝ ከእርሱ አልመገብም” አለች።'),
  ('5beb0437-ffd4-5a57-a8aa-8dd5d3ec7244', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 3, 3, 'ሆሎፎርኒስም፥ “ያመጣሽውስ ቢያልቅብሽ እንደ እርሱ ያለ ከየት አምጥተን እንሰጥሻለን? ከወገኖችሽ ስንኳ ካንቺ ጋር ያለ ሰው የለም” አላት።'),
  ('7efef8eb-47f0-5cc6-a9a6-222aa4ede47a', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 4, 4, 'ዮዲትም፥ “እግዚአብሔር በእኔ ቃል የመከረውን እስኪያደርግ ድረስ እኔ አገልጋይህ የያዝሁትን እንዳልጨርስ ጌታዬ ሕያው ነፍስህን” አለችው።'),
  ('2afcec3d-8df2-5ac4-a4f0-5fd150b41a0b', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 5, 5, 'የሆሎፎርኒስም አሽከሮች ወደ ድንኳኑ አገቧት፤ እስከ እኩለ ሌሊትም ድረስ ተኛች። ሌሊቱም ከመንጋቱ በፊት በእኩለ ሌሊት ተነሣች፤'),
  ('88056698-b887-5a04-ad21-e7b3a68b7831', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 6, 6, '“እኔ አገልጋይህ ለጸሎት እንድወጣ ይፈቅዱልኝ ዘንድ እዘዝልኝ” ብላ ወደ ሆሎፎርኒስ ላከች።'),
  ('09ed2d00-e7db-56e1-a91f-be06e2bdc5fc', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 7, 7, 'ሆሎፎርኒስም እንዳይከለክሏት የሚጠብቁትን ሰዎች አዘዛቸው፤ ከዚህ በኋላም በሰፈር ሦስት ቀን አደረች፤ በየሌሊቱም እየወጣች ወደ ቤጤሌዋ ሸለቆ ትወርድ ነበር፤ ሌሊትም በሰፈሩ ምንጭ ውኃ ትታጠብ ነበር፤ ሌሊትም ወጥታ በምንጩ ውኃ ትጠመቅ ነበር።'),
  ('3ce67517-f7fd-588b-afe5-a58d4659cf61', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 8, 8, 'ከውኃውም በወጣች ጊዜ ስለ ወገኖችዋ ልጆች መነሣት መንገድዋን ያቃናላት ዘንድ ወደ እስራኤል አምላክ ወደ እግዚአብሔር ትጸልይ ነበር።'),
  ('e60c9f2c-93ea-51f7-a376-9a8b249d7e61', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 9, 9, 'ከዚህም በኋላ ትመለስ ነበር፤ በሰፈርም በንጽሕና ትቀመጥ ነበር፤ ማታ ማታም ትመገብ ነበር።'),
  ('7f3d77b9-ca5e-5ab0-a817-481c53a976f8', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 10, 10, 'ከዚህም በኋላ በአራተኛዪቱ ቀን ሆሎፎርኒስ ለአሽከሮቹ ለብቻቸው ምሳ አደረገ፤ ሌላ ሰው ማንንም ወደ ምሳው አልጠራም።'),
  ('3c5422df-0a98-57aa-a15d-ec8945eb39e3', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 11, 11, 'የገንዘቡ ሁሉ መጋቢ የሆነውን ጃንደረባ ባግዋን፥ “በአንተ ዘንድ ያለች ያችን ዕብራዊት ሴት ወደ እኛ ትመጣ ዘንድ አባብልልኝ፤ ከእኛ ጋር ትብላ፤ ትጠጣም፤ ሄደህም ንገራት።'),
  ('05c0c874-8d44-50f2-a869-aa5b09d3559e', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 12, 12, 'እንዲህ ያለች ሴት አግኝተን ባናነጋግራት ለእኛ ዕፍረታችን ነውና፥ ባንገናኛትም ይስቁብናልና” አለው።'),
  ('b4690c60-12ed-5b4c-af0f-b831a245fcd5', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 13, 13, 'ባግዋም ከሆሎፎርኒስ ዘንድ ወጥቶ ወደ እርሷ ገባ፥ “መልከ መልካም የሆንሽ አንቺ ልጄ ሆይ! ወደ ጌታዬ መምጣትን እንቢ አትበዪ፤ በእርሱ ዘንድ ትከብሪያለሽ፤ ከእርሱም ጋራ ወይንን ጠጥተሽ ደስ ይልሻል፤ በናቡከደነፆር ቤት ከሚያገለግሉት ከአሦር ልጆችም እንደ አንዲቱ ትሆኛለሽ” አላት።'),
  ('81371f9e-0625-50ee-af6a-61f08fab551b', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 14, 14, 'ዮዲትም አለችው፥ “ጌታዬን እንቢ እለው ዘንድ እኔ ማን ነኝ? ወገኔስ ማን ነው? የወደድኸውን ሁሉ በፊትህ ፈጥኜ አደርጋለሁ፤ እስክሞትም ድረስ ለእኔ ደስታ ይሆንልኛል፤”'),
  ('965fb5d2-152a-5345-ad50-6b12a8ee4fd3', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 15, 15, 'ተነሥታም ልብሷን ለበሰች፤ የሴቶችንም ጌጥ ሁሉ ፈጽማ አጌጠች፤ ብላቴናዋም ከእርሷ ጋራ ሄደች፤ ከባግዋ የተቀበለችውን፥ በማደሪያዋ ያነጠፈላትን፥ ምሳም ስትበላ የምትቀመጥበትን ምንጣፏን በሆሎፎርኒስ ፊት በምድር ላይ አነጠፈችላት።'),
  ('2ad20dfe-05ed-5a92-aa03-0dc4a6b3d2f3', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 16, 16, 'ዮዲትም ወደ እርሱ ገብታ ተቀመጠች፤ የሆሎፎርኒስም ልቡናው በእርሷ ታወከ፤ ከእርሷም ጋር ይተኛ ዘንድ ሰውነቱ ፈጽማ ጐመጀች፤ ከአያትም ጀምሮ እርሷን እስከሚያባብልበት ጊዜ ይጠብቃት ነበር።'),
  ('6a4d15c2-1c70-5f10-a8ac-d7ded6ed5ad9', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 17, 17, 'ሆሎፎርኒስም ዮዲትን፥ “ጠጥተሽ ከእኛ ጋር ደስ ይበልሽ” አላት።'),
  ('e96ce165-1d6c-599c-abfe-4ee4c322f00b', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 18, 18, 'ዮዲትም፥ “ከተወለድሁ ጀምሮ ከዘመኔ ሁሉ ይልቅ ሕይወቴ ዛሬ ከብራለችና ጌታዬ እጠጣለሁ” አለችው።'),
  ('f94eb283-2e68-5a29-a35e-1a97b20c36f1', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 19, 19, 'አገልጋይዋም ያዘጋጀችላትን ተቀብላ በፊቱ በላች፤ ጠጣችም።'),
  ('18fad2fa-d357-5ba1-a453-7470de1f21b8', '59e5b7d6-7174-5f26-a1a8-50adc6e6b5db', 'bbba6564-effd-5b33-a67f-5ae42d9d32cc', 20, 20, 'ሆሎፎርኒስም ስለ እርሷ ደስ አለው፤ ከተወለደም ጀምሮ አንዲት ቀን ስንኳ እንደዚያ ያልጠጣውን ብዙ ወይን አብዝቶ ጠጣ።'),
  ('b7b7daff-3088-5027-a435-5f24db13cf77', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 1, 1, 'በመሸም ጊዜ አሽከሮቹ ፈጥነው ሰውን አስወጡ፤ ባግዋም ከወደ ውጭ በላያቸው ድንኳኑን ዘጋ፤ በጌታውም ፊት የቆሙ አሽከሮቹን አስወጥቶ ሰደዳቸው፤ ፈጽመው ስለጠጡ ሁሉም ደክመዋልና ወደ ማደሪያቸው ገቡ።'),
  ('e90bd18d-dc65-5d26-ab6c-089e3db81f99', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 2, 2, 'ዮዲትም ብቻዋን በድንኳን ውስጥ ከሆሎፎርኒስ ጋር ቀረች፤ እርሱ ግን አብዝቶ ወይን ስለጠጣ ሰክሮ በአልጋው ላይ ተኝቶ ነበር።'),
  ('51ab62fd-2a40-53d0-aef5-0d2298dfd5e4', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 3, 3, 'ዮዲትም አገልጋይዋን ወደ ውጭ ወጥታ በማደሪያዋ ትቆም ዘንድ አዘዘቻት፤ “ወደምጸልይበት እወጣለሁ” ብላታለችና እንደ ወትሮው በምትመጣበት ጊዜ ትጠብቃት ዘንድ አዘዘቻት፤ ለባግዋም እንደዚሁ ነገረችው።'),
  ('1c65d3bf-5445-54d6-a035-e90cc2c9125c', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 4, 4, 'ሁሉም ከእርስዋ ዘንድ ወጡ፤ ታናሽም፥ ታላቅም ቢሆን በእልፍኙ የቀረ አልነበረም። ዮዲትም ተነሥታ በመኝታው አጠገብ ቆመች። በልቧም፥ “የኀይል ሁሉ አምላክ አቤቱ፥ ይህን ነገር እይ፤ ኢየሩሳሌም ከፍ ከፍ ትል ዘንድ በዚች ሰዓት በእኔ እጅ ኀይልህን አድርግ።'),
  ('b5f45990-a336-5038-a425-d9d1bc7804d3', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 5, 5, 'ርስትህን ታነሣ ዘንድ ጊዜው ደርሷልና በእኛ የተነሡ ጠላቶች ይጠፉ ዘንድ አሳቤን ሁሉ ፈጽምልኝ” አለች።'),
  ('f8d04af9-af56-56cb-a2c1-75462513fe76', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 6, 6, 'ወደ ሆሎፎርኒስም መኝታ ወደ ትራሱ ሄደች፤ የራስጌ ሰይፉንም መዘዘች።'),
  ('034c9e35-3e9b-59c4-a7f5-5f3ee4942cbc', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 7, 7, 'በራስጌውም ቆመች፤ የራሱንም ጠጕር ይዛ “የእስራኤል አምላክ አቤቱ፥ ዛሬ አጽናኝ” አለች።'),
  ('fbadfad6-4d1f-52d8-a6f2-b861701c47c9', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 8, 8, 'በኀይሏ ሁለት ጊዜ አንገቱን መታችው፤ ራሱንም ቈረጠችው።'),
  ('0b4675c3-7e84-5368-aec0-51a47a1f9c62', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', '0b2dd894-378c-59ba-a28b-c40d8c6eec56', 9, 9, 'ሬሳውንም ከመኝታው ወደ ምድር ጣለችው፤ የራስጌ መጋረጃውንም ከምሰሶው አወረደች፤ ጥቂትም ዐረፈች፤ ወጥታም ለብላቴናዋ የሆሎፎርኒስን ቸብቸቦ ሰጠቻት።'),
  ('eb5cefaa-34d1-577c-ab84-f1cf84598f2e', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 1, 10, 'እህል በምትይዝበት ከረጢትም ጨመረችው፤ ለጸሎት እንዳስለመዱ ሁለቱ ሁሉ በአንድነት ወጡ፤ ከሰፈሩም አልፈው ወደ ሸለቆው ዞሩ፤ ወደ ቤጤልዋ ዐቀበትም ወጡ፤ ወደ ከተማውም በር ደረሱ።'),
  ('60b5666a-c3dc-5d77-a78f-8573ae8fdec3', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 2, 11, 'ዮዲትም በሩቁ ሆና በር የሚጠብቁ ዘበኞችን፥ “ዛሬ ኀይልን እንዳደረገ ዳግመኛ ለእስራኤል በጠላቶቻቸው ላይ ጽናትና ኀይልን ያደርግ ዘንድ እግዚአብሔር ከእኛ ጋር አለና ክፈቱ፤ ክፈቱ” አለቻቸው።'),
  ('8abc511d-9e9e-5efa-ae7a-df3674cf675c', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 3, 12, 'ከዚህም በኋላ የከተማው ሰዎች ቃልዋን በሰሙ ጊዜ ወደ ከተማው በር ፈጥነው ወረዱ፤ የከተማ ሽማግሌዎችን ጠሩ።'),
  ('5b84fafc-3021-5195-a671-7ee40c371ecc', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 4, 13, 'እንደ ተመለሰችም አድንቀዋልና ታናሹም፥ ታላቁም ሁሉ ሮጠው ሄዱ፤ በሩንም ከፍተው ተቀበሏት፤ እሳትም አንድደው፥ ፋና አብርተው ከበቧት።'),
  ('aced35d1-bee0-5923-aa16-811db2bb10d6', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 5, 14, '“ጠላቶቻችንን በዚች ሌሊት በእጄ አጠፋቸው እንጂ ምሕረቱንና ይቅርታውን ከእስራኤል አላራቀምና በታላቅ ቃል እግዚአብሔርን አመስግኑት፤ አመስግኑት። እግዚአብሔርንም አመስግኑት” አለቻቸው።'),
  ('64265372-6c5a-5f34-ac56-bdd289f0aefa', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 6, 15, 'ቸብቸቦውንም ከከረጢቷ አውጥታ አሳየቻቸው፤ “የአሦር ሠራዊት አለቃ የሆሎፎርኒስ ቸብቸቦ እነሆ፥ በሚጠጣ ጊዜ ተንተርሶት የሚተኛበት ሰይፉም እነሆ፥ እግዚአብሔር በእኔ በሴቷ አድሮ ገደለው።'),
  ('28986b33-dd5d-52aa-a5b4-4f1a2d085976', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 7, 16, 'እንዲሞት በመልኬ አስተው ዘንድ በሄድሁበት ጎዳና የጠበቀኝ፥ በእኔም ኀጢአትንና በደልን፥ መዋረድንም ያላደረገ እግዚአብሔር ሕያው ነው” አለቻቸው።'),
  ('1ca3e104-c92e-595f-a4aa-c8c4c43e1945', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 8, 17, 'ሕዝቡም ሁሉ ፈጽመው አደነቁ፤ ለእግዚአብሔርም ፈጽመው ሰገዱ፤ በአንድነትም እንዲህ አሉ፥ “ዛሬ በዚች ቀን የወገኖችህን ጠላቶች ያጠፋሃቸው አንተ አምላካችን ቡሩክ ነህ።”'),
  ('d6cab55f-04b5-5203-adb9-945d247cfe66', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 9, 18, 'ዖዝያንም እንዲህ አላት፥ “በዚህ ዓለም ከሚኖሩ ሴቶች ይልቅ አንቺ ልጄ፥ ልዑል እግዚአብሔር የባረከሽ ነሽ። ሰማይንና ምድርን የፈጠረ፥ የጠላቶቻችንን አለቃ ቸብቸቦ ትቈርጪ ዘንድ የረዳሽ እግዚአብሔር አምላክም ቡሩክ ነው።'),
  ('52b54741-aee9-5e28-a07c-84243272c804', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 10, 19, 'ለዘለዓለሙ የእግዚአብሔርን ኀይል እያሰቡ ምስጋናሽ ከሰው ልቡና አይጠፋምና።'),
  ('6b05b49a-42e4-5de2-a762-d53175a59c75', 'f6d37bf4-3e99-5924-ae0e-651ee455d5d0', 'a9695be4-e73d-5640-a63f-835411de9621', 11, 20, 'እግዚአብሔር ይህን ለዘለዓለም እንድትከብሪ ያድርግልሽ፤ ስለ ወገኖችሽ አንቺ ልሙት ብለሽ ወጣሽ እንጂ፥ በፈጣሪያችን በእግዚአብሔርም ፊት በቀጥታ ሄድሽ እንጂ ለሰውነትሽ አልራራሽምና በቸርነቱ ይመልከትሽ።” ሕዝቡም ሁሉ፥ “አሜን፥ አሜን” አሉ።'),
  ('8c2a11c2-437a-5c1a-a872-6895d52796bd', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 1, 1, 'ዮዲትም፥ “ወንድሞች፥ ስሙኝ፤ ይህን ቸብቸቦ ይዛችሁ በግንቡ ጫፍ ላይ ስቀሉት።'),
  ('db962aa5-4353-5130-adc0-8bc0a1f54449', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 2, 2, 'ከዚህ በኋላ ሲነጋ ፀሐይ በወጣ ጊዜ ሁላችሁም የጦር መሣሪያችሁን ያዙ፤ አርበኞች የሆኑ ሰዎች ሁሉ ከከተማ ወደ ውጭ ይውጡ፤ የአሦራውያን ሠራዊት ጠባቂዎችም ወዳሉበት ቦታ እንደምትወርዱ ሆናችሁ አለቃ ለራሳችሁ ሹሙ። ነገር ግን አትውረዱ።'),
  ('30419d5b-ce2c-508d-ac42-607906a8f818', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 3, 3, 'ሁላችሁም የጦር መሣሪያችሁን ያዙ፥ ዘበኞችም ባዩአችሁ ጊዜ የአሦር ሠራዊት አለቆችን ይቀሰቅሱ ዘንድ ወደ ሰፈራቸው ይሄዳሉ፤ ከዚያም በኋላ ወደ ሆሎፎርኒስ ድንኳን ይሮጣሉ፤ አያገኙትም፤ ከዚያም በኋላ እጅግ ፈርተው ከፊታችሁ ይሸሻሉ።'),
  ('7f412fa0-eee2-59f9-aacc-ca8fd2079648', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 4, 4, 'ከዚህ በኋላም እናንተና በእስራኤል አውራጃ የሚኖሩ ሰዎች ሁሉ ተከተሏቸው፤ በጎዳናቸውም ሁሉ ርገጡአቸው።'),
  ('d740ab6b-9fd7-5ce7-a600-d011403d7dc8', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 5, 5, 'ይህንም ከማድረጋችሁ በፊት የእስራኤልን ወገን የካደውን ከእኛም ጋር ይሞት ዘንድ እርሱን ወደ እኛ የላከውን እርሱ መሆኑን አይቶ ያውቅ ዘንድ አሞናዊውን አክዮርን ጥሩልኝ” አለቻቸው።'),
  ('80fc099a-7122-5a76-a1cf-45abdd47a811', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 6, 6, 'አክዮርንም ከዖዝያን ቤት ጠሩት፤ መጥቶም የሆሎፎርኒስን ራስ በአንድ ሰው እጅ ባየ ጊዜ ሰውነቱ ደንግጦ በሕዝቡ ጉባኤ መካከል በግንባሩ ወደቀ።'),
  ('0d783b8e-8d62-564b-ad6c-cd542bbdaa53', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 7, 7, 'በአነሡትም ጊዜ በዮዲት እግር ላይ ወደቀ፤ ሰገደላትም፤ “ከይሁዳ ቤትና ከሕዝቡ ሁሉ አንቺ የተባረክሽ ነሽ፤ ስምሽንም ሰምተው ይደነግጣሉ።'),
  ('6ce5ca52-a751-59eb-ad3f-70435e9b05e1', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 8, 8, 'አሁንም በእነዚህ ወራት ያደረግሺውን ንገሪኝ” አላት። ዮዲትም ከወጣች ጀምሮ እስክትመለስ ድረስ ያደረገችውን ሁሉ በሕዝቡ መካከል ነገረችው።'),
  ('b3278e67-9417-5d6c-a06e-f19c0b5d2e97', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 9, 9, 'ነገሯን ተናግራ በጨረሰች ጊዜ ሕዝቡ ሁሉ ቃላቸውን አሰምተው ደነፉ፤ በየከተማቸውም በደስታ ቃል ጮኹ።'),
  ('5146bc2e-4b82-546a-af11-61205d03ac61', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', '48b6e28b-f66e-5bc0-a049-3cb7f1c7f0f7', 10, 10, 'አክዮርም እግዚአብሔር ለእስራኤል ያደረገውን ተአምራት በአየ ጊዜ ፈጽሞ በእግዚአብሔር አምኖ ተገዘረ። እስከ ዛሬም ድረስ ከቤተ እስራኤል ጋር አንድ ሆነ።'),
  ('6cdd7a19-bb24-55d9-a64d-a1877cf581a9', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 1, 11, 'በነጋም ጊዜ የሆሎፎርኒስን ቸብቸቦ በግንቡ ላይ ሰቀሉት፤ ወንዶቹም ሁሉ መሣሪያቸውን ይዘው ወጡ፤ በተራራውም ዐቀበት በኩል ከበቧቸው።'),
  ('ede6accc-ac9e-58a3-a898-a9701554ef87', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 2, 12, 'የአሦር ሠራዊትም በአዩአቸው ጊዜ ወደ ሹሞቻቸው ላኩ፤ እነርሱም ወደ አለቆቻቸው፥ ወደ ሹሞቻቸውና ገዢዎቻቸው ሄዱ።'),
  ('ec995549-9f78-550f-acf8-75e2d21edfed', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 3, 13, 'ወደ ሆሎፎርኒስም ድንኳን መጥተው ለመጋቢው፥ “እነዚህ ባሮች እስከ መጨረሻው ይጠፉ ዘንድ ሊዋጉን ተደፋፍረው ወርደዋልና ጌታችንን ከእንቅልፉ ቀስቅሰው” አሉት።'),
  ('f7aec086-52fc-5e0c-ac94-652230fa25a8', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 4, 14, 'ባግዋም ከዮዲት ጋር የተኛ መስሎታልና ገብቶ በድንኳኑ አንጻር ያለ በሩን መታ።'),
  ('96b39264-a26f-5b7c-ac1b-5f274895d612', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 5, 15, 'ቃል የሚመልስለት ሰውም በአጣ ጊዜ ድንኳኑን ተርትሮ ወደ እልፍኙ ገባ፤ ሬሳውንም በወለሉ ላይ ወድቆ አገኘው። ራሱም በላዩ አልነበረም።'),
  ('a2d66348-5a6d-5fd5-a38a-f5f9b42d008a', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 6, 16, 'እያለቀሰና እያቃሰተ በታላቅ ቃል ፈጽሞ ጮኸ፤ ልብሱንም ቀደደ።'),
  ('d63958da-3b30-54a6-a56c-ed3cbe729056', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 7, 17, 'ዮዲትም ወደምታድርበት ድንኳን ገባ፤ ነገር ግን አላገኛትም፤ ወደ ሕዝቡም እየሮጠ ሄዶ ጮኸላቸው። እንዲህም አላቸው፦'),
  ('745c7e0d-13fd-5527-a374-8ed7f1ea966b', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 8, 18, '“እነዚህ ባሮች አታለሉን፤ እነሆ፥ የሆሎፎርኒስ ሬሳው በምድር ላይ ወድቋልና፥ ራሱም በላዩ የለምና አንዲት ዕብራዊት ሴት በንጉሡ በናቡከደነፆር ቤት ላይ ኀፍረትን አድርጋለች።”'),
  ('449c8214-35b3-5e7c-a6b7-663336fc15e0', 'fefaf71a-3405-54bc-a1fd-36c6b08a9c0f', 'c957ba9b-5cda-50ce-a7e0-dda3ba8ff7be', 9, 19, 'የአሦር የሠራዊት አለቆችም ይህን ነገር በሰሙ ጊዜ ልብሳቸውን ቀደዱ፤ ሰውነታቸውም ፈጽማ ደነገጠች፤ በታላቅ ድምፅም በሰፈር መካከል ፈጽመው ጮኹ።'),
  ('e7a21794-8044-51f4-a92c-204a8e06bfa5', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '7163499a-2857-5d67-a4af-dc4b0c6f5691', 1, 1, 'በሰፈርም የነበሩ ሰዎች በሰሙ ጊዜ ስለ ተደረገው ነገር ደነገጡ፤'),
  ('a0c99762-4852-576f-aba5-5ba4cccaf438', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '7163499a-2857-5d67-a4af-dc4b0c6f5691', 2, 2, 'ፍርሀትና እንቅጥቅጥም ያዛቸው፤ ከባልንጀራውም ጋር የቆመ ሰው አልነበረም። ነገር ግን ሁሉም ደንግጠው ወደ ምድረ በዳውና ወደ ተራራማው ሀገር በአንድነት ሸሹ።'),
  ('a5d97cf9-c0df-597b-a79e-846477335f4e', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '7163499a-2857-5d67-a4af-dc4b0c6f5691', 3, 3, 'እነዚያም በቤጤልዋ ዙሪያ፥ በሰፈሩና በተራራማው ሀገር የነበሩ ሰዎች ሁሉ ተሸብረው ሸሹ፤ ያንጊዜም አርበኞች የሆኑ የእስራኤል ወንዶች ልጆች ሁሉ ተነሥተው ተከተሏቸው።'),
  ('a88c0f09-ae4e-5876-a06f-bbd7b00f4ffd', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '7163499a-2857-5d67-a4af-dc4b0c6f5691', 4, 4, 'ዖዝያንም ስለ ሆነው ሁሉ ይናገሩ ዘንድ፥ ሁሉም ይረዱ ዘንድ፥ ጠላቶቻቸውንም ተከትለው ያጠፏቸው ዘንድ፥ ወደ ቤጦምስታምና ወደ ቢቤ፥ ወደ ኮቤና ወደ ኮላ ወደ እስራኤልም አውራጃ ሁሉ ላከ።'),
  ('3c42379b-7acb-5172-a80a-9ebb60f094a1', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '7163499a-2857-5d67-a4af-dc4b0c6f5691', 5, 5, 'የእስራኤልም ልጆች በሰሙ ጊዜ ሁሉም በአንድነት እስከ ኮቤ ድረስ ተከትለው አጠፏቸው፤ በጠላቶቻቸው ሰፈር የሆነውን ነገር ነግረዋቸዋልና ከኢየሩሳሌምና ከአውራጃዋ ሁሉ የመጡ ሰዎች እንደዚሁ አጠፏቸው፤ ከገሊላና ከገለዓድም የመጡ ሰዎች አባረሯቸው፤ ከደማስቆና ከአውራጃዋም እስኪሻገሩ ድረስ ታላቅ ሰልፍ አድርገው አጠፏቸው።'),
  ('97effd09-1ef6-519f-a71d-4f2129811477', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '7163499a-2857-5d67-a4af-dc4b0c6f5691', 6, 6, 'በቤጤልዋም የሚኖሩ ሰዎች ወደ አሦራውያን ሰፈር ወርደው ገንዘባቸውን በዘበዝዋቸው፤ ፈጽመውም ከበሩ።'),
  ('5c460aa4-ecad-5b9a-a989-48cb66c6f689', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '7163499a-2857-5d67-a4af-dc4b0c6f5691', 7, 7, 'ከዚህ በኋላም የእስራኤል ልጆች ከተዋጉበት ተመለሱ፤ ከብዙ ዘመን ጀምሮ ሰፊ አውራጃቸውን ይዘውባቸው ነበርና የቀሩትን በተራራማው ሀገርና በሜዳው የነበሩትን መንደሮችና ከተሞች ወሰዱ።'),
  ('3d03bbcb-ed72-5f4f-afb5-6526477594e3', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '27499fe8-9094-5405-a3fb-0f26dc14b571', 1, 8, 'ታላቁ ካህን ኢዮአቄምና በኢየሩሳሌም የሚኖሩ የእስራኤል ልጆች ሽማግሌዎችም እግዚአብሔር ለእስራኤል ያደረገውን በጎ ነገር ያዩ ዘንድ፥ ዮዲትንም ያዩአት ዘንድ፥ ከእርሷም ጋራ ሰላምታ ያደርጉ ዘንድ መጡ።'),
  ('82e19166-65a7-5941-a5ef-b1f0af8047d8', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '27499fe8-9094-5405-a3fb-0f26dc14b571', 2, 9, 'ወደ እርሷም በገቡ ጊዜ ሁሉም በአንድነት መረቋት፤ እንዲህም አሏት፥ “የኢየሩሳሌም ልዕልና አንቺ ነሽ፤ የእስራኤልም ክብራቸው አንቺ ነሽ፤ የወገኖቻችንም መመኪያ አንቺ ነሽ፤'),
  ('56911106-5cf9-5bef-aca2-754bffad2e12', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '27499fe8-9094-5405-a3fb-0f26dc14b571', 3, 10, 'ይህ ሁሉ በእጅሽ ተደርጓልና፥ ይህንም በጎ ነገር ለእስራኤል አድርገሻልና፥ እግዚአብሔርም እነርሱን ወዷልና፥ ሁሉን የሚገዛ እግዚአብሔር ለዘለዓለሙ ይባርክሽ!” ሕዝቡም ሁሉ፥ “አሜን” አሉ።'),
  ('2035c1df-17f4-5f31-a4ba-ac6a7b2005f3', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '27499fe8-9094-5405-a3fb-0f26dc14b571', 4, 11, 'ሕዝቡም ሠላሳ ቀን ሰፈራቸውን በረበሩ፤ ለዮዲትም የሆሎፎርኒስን ድንኳንና የብሩን ዕቃ ሁሉ፥ ዙፋኑንና ያለውንም ገንዘብ ሁሉ ሰጧት፤ እርሷም ወስዳ በበቅሎዋ ጫነች፤ ሠረገላዎችዋንም ነድታ ከእርሷ ጋር ይዛ ገባች።'),
  ('5436313a-c6ec-560f-a62b-fcb14b9c4db1', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '27499fe8-9094-5405-a3fb-0f26dc14b571', 5, 12, 'የእስራኤልም ሴቶች ሁሉ ያይዋት ዘንድ፥ ይመርቋትም ዘንድ ወደ እርሷ ሮጠው ተሰበሰቡ፤ ታላቅ በዓልንም አደረጉላት፤ ዘንባባውንም በእጅዋ ያዘች፤ ከእርሷ ጋራ ላሉ ሴቶችም ሰጠች።'),
  ('1de6b4bc-a144-5f0c-a1ce-503f54f56369', '50468d89-63d7-5f97-aaea-6eaa80e4bd86', '27499fe8-9094-5405-a3fb-0f26dc14b571', 6, 13, 'ለእርስዋና ከእርስዋ ጋር ለነበረችውም ብላቴና የወይራ ጕንጕን አደረጉላቸው፤ በሕዝቡም ፊት ሴቶችን ሁሉ እየመራች በዝማሬ ሄደች፤ የእስራኤልም አርበኞች ሁሉ የጦር መሣሪያቸውን ከዘንባባ ጋር ይዘው እየዘመሩ ተከተሏት።'),
  ('8b6db25b-e157-51aa-a22a-3bdb0a9e6c88', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 1, 1, 'ዮዲትም ይህቺን የምስጋና መዝሙር በእስራኤል ሁሉ ዘንድ ትዘምር ጀመረች፤ ሕዝቡም ሁሉ ይህቺን የምስጋና መዝሙር ከእርስዋ ቀጥለው ዘመሩ።'),
  ('6db88c5a-f59f-5c9c-a22b-aad9720f296f', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 2, 2, 'ዮዲትም አለች፥ “አምላኬን በከበሮ አመስግኑት፤'),
