  ('f930daea-4840-5741-afdd-4f8a5c4ead7c', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 4, 4, 'ስሙም እግዚአብሔር ነው፤'),
  ('d4073b56-d35e-5f65-a66c-31507192d887', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 5, 5, 'አሦራውያን በመስዕ በኩል ከተራራው ወጡ፤'),
  ('fa642928-ba78-5b8e-a294-29a1126ddf2f', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 6, 6, 'አውራጃችንን በእሳት ያቃጥሉ ዘንድ፥'),
  ('10d36ca2-bb3e-587f-a90a-e029efba9252', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 7, 7, 'ነገር ግን ሁሉን ቻይ እግዚአብሔር በሴት እጅ አጠፋቸው።'),
  ('85eae546-a87e-5cf0-ac7e-a11d1fdbd05f', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 8, 8, 'አርበኛቸው በጐልማሳ እጅ ድል አልተነሣምና፥'),
  ('65e0a7b8-853c-5cb1-afe8-b4ff455cd609', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 9, 9, 'የመበለትነቷንም ልብስ በእስራኤል ዘንድ ስለሚጨነቁት ሰዎች ስትል ተወች።'),
  ('a7681cc9-1208-5069-a51e-0701b2e5919c', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 10, 10, 'ፊትዋንም ሽቱ ተቀባች፤'),
