  ('bb12f2d8-e4b0-5c04-a204-544588a5a5a1', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 12, 12, 'ከመደፋፈርዋም የተነሣ የፋርስ ሰዎች ደነገጡ፤'),
  ('3283cb7a-e612-58c3-a62f-6a943682a857', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 13, 13, 'ያንጊዜ የተጨነቁ ወገኖች ደስ ብሏቸው ደነፉ፤'),
