  ('eff85046-98a7-5740-ac0b-397937f4d59b', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 15, 15, 'ለእግዚአብሔር መዝሙር እዘምራለሁ፤'),
  ('696b64e4-5b51-59df-ac47-763594efbace', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 16, 16, 'እግዚአብሔር ሆይ፥ ገናና ነህ፤'),
  ('7a1d0947-aab7-5aab-afd5-1a686e5f7787', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 17, 17, 'ፍጥረትህ ሁሉ ለአንተ ይገዛሉ፤'),
  ('c27931c8-1431-583b-a8dc-8a11cf85442a', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 18, 18, 'ተራሮች ከውኆች ጋር ከመሠረቶቻቸው ይነዋወጣሉና፤'),
  ('a9d51c91-041d-5b51-a037-d05eb538fd9f', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 19, 19, 'መሥዋዕቱ ሁሉ ለበጎ መዓዛ አይበቃምና፥'),
  ('6830b289-c388-5fa9-a2f9-cc287561cce5', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 20, 20, 'በወገኖች ላይ በጠላትነት ለሚነሡ ለአሕዛብ ወዮላቸው፤'),
  ('ebbd6338-d93f-528c-ab7e-ba4bccfb9dcd', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 21, 21, 'በሥጋቸውም እሳትና ትልን ይልክባቸዋል፤'),
  ('347ee41a-d8aa-5bd4-ab60-7f5f7c91495d', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 22, 22, 'ወደ ኢየሩሳሌምም በደረሱ ጊዜ ለእግዚአብሔር ሰገዱ፤ ሕዝቡም ራሳቸውን ባነጹ ጊዜ የሚቃጠለውን መሥዋዕታቸውንና የፈቃድ ቍርባናቸውን፥ ስጦታቸውንም አቀረቡ።'),
  ('b1651f62-5054-5191-ab7f-609532f2fd88', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 23, 23, 'ዮዲትም ሕዝቡ የሰጧትን የሆሎፎርኒስን ገንዘብ፥ ከመኝታ ቤቱም የወሰደችውን የራስጌውን ሰይፍ ለመታሰቢያ ለእግዚአብሔር ሰጠች።'),
  ('ceab465d-d778-5792-ac2a-566035f16990', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 24, 24, 'ሕዝቡም በኢየሩሳሌም በቤተ መቅደስ ፊት ሦስት ወር ደስታ አደረጉ፤ ዮዲትም ከእነርሱ ጋር ተቀመጠች።'),
  ('5ad24a6a-7078-502c-a0ed-6281193146a2', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 25, 25, 'ከእነዚያም ወራት በኋላ ሰው ሁሉ ወደ ርስቱ ተመለሰ፤ ዮዲትም ወደ ቤጤልዋ ተመልሳ በንብረቷ ኖረች፤ በዘመኗም በሀገሩ ሁሉ የከበረች ሆነች።'),
  ('09e24437-e579-584a-aad3-f8072d40058d', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 26, 26, 'የሚፈልጓትም ብዙዎች ነበሩ፤ ባሏ ምናሴ ሞቶ በወገኖቹ ዘንድ ከተቀበረ ጀምሮ በሕይወት ዘመኗ ሁሉ በግብር ያወቃት ሰው የለም።'),
  ('2943e46b-e6e5-5350-a683-a893b66e4932', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 27, 27, 'ፈጽማም በክብር ገነነች።'),
  ('ddeb30db-906d-566e-ae06-9c51a104c2e2', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 28, 28, 'በባሏ በምናሴም ቤት እስክታረጅ ድረስ ኖረች፤ ዕድሜዋም መቶ ዐምስት ዐመት ነበር፤ ያችንም ብላቴናዋን ነጻ አወጣቻት፤ በቤጤልዋ ሞታ በባሏ በምናሴ ዋሻ ተቀበረች፤'),
  ('2fa2a995-6fca-5b7b-add6-34e8c9a714fb', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 29, 29, 'የእስራኤልም ወገኖች ሰባት ቀን አለቀሱላት፤ ከመሞትዋም በፊት ገንዘብዋን ለባልዋ ለምናሴ አቅራቢያና ለእርሷ አቅራቢያ ለሆኑ ዘመዶችዋ አካፈለች።'),
  ('0a29c6f0-c30f-5faf-a1ef-9dc15b597202', '391a3e8e-6826-5436-aa58-e38354cd4d7f', '804330ce-7c5e-5125-a344-231d7d810622', 30, 30, 'የእስራኤልንም ልጆች በዮዲት ዘመን፥ ዳግመኛም እርስዋ ከሞተች በኋላ ለብዙ ዘመን ያስፈራቸው አልነበረም።'),
  ('740a583c-f8c1-5e14-a5aa-dbaac65d44f6', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 1, 1, 'ታላቁ ንጉሥ አርጤክስስ በነገሠ በሁለተኛው ዓመት በኒሳን መባቻ የኢያዕር የሰሜኢ የቂስ ልጅ ከብንያም የተወለደ አይሁዳዊው መርዶክዮስ ሕልም አየ፤'),
  ('e3d35a1f-fb76-5be2-a009-5ef16f306236', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 2, 2, 'እርሱም በሱሳ ከተማ ይኖር ነበር፤ ታላቅ ሰውም ነበረ፤ በንጉሡ ቤት አደባባይም ያገለግል ነበር።'),
  ('fb175bb1-62cd-5441-aaff-a9f723d41bf9', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 3, 3, 'እርሱም የባቢሎን ንጉሥ ናቡከደነፆር ከይሁዳው ንጉሥ ከኢኮንያን ጋር ከኢየሩሳሌም ከማረካቸው ምርኮኞች አንዱ ነበረ።'),
  ('c47972b7-a8eb-544a-ae7e-4765fa8f1035', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 4, 4, 'ሕልሙም ይህ ነበረ፦ እነሆ ቃል፥ የምድር መነዋወጥና ሁከት፥ ነጐድጓድም ተሰማ፤ በምድርም ላይ ችኮላ ሆነ።'),
  ('e2777b86-6442-59eb-a7c1-057e03b6fa6f', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 5, 5, 'እነሆም ለጠብ የተዘጋጁ ሁለት ታላላቅ ዘንዶዎች መጡ፤ ቃላቸውም ታላቅ ሆነ።'),
  ('ae387988-7214-50b6-ac1e-da8bfecdb9c0', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 6, 6, 'በቃላቸውም አሕዛብ ሁሉ ጻድቃን ሕዝብን ይዋጉ ዘንድ ለሰልፍ ተዘጋጁ።'),
  ('ec38af06-a16e-5b85-a0c7-ab6d7fe67725', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 7, 7, 'እነሆም ጭጋግና ጨለማ፥ ኀዘንና መከራ፥ ጭንቅና ታላቅ ሁከት በምድር ላይ የሚደረግበት ቀን ሆነ፤'),
  ('2b63cae4-542f-5400-a5ef-9eefa4b43b8d', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 8, 8, 'ጻድቃን ሕዝቦች ሁሉ ክፋታቸውን እየፈሩ ታወኩ። ለጥፋትም ተዘጋጁ፤'),
  ('bc7c01b2-1406-5164-a7af-f3c1d11f9e02', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 9, 9, 'ወደ እግዚአብሔርም ጮኹ፤ ከጩኸታቸውም የተነሣ ከትንሽ ምንጭ ብዙ ውኃ እንዳለበት እንደ ትልቅ ወንዝ ሆነ፤'),
  ('18465e5e-739a-5910-aab5-3cd55a75cf13', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 10, 10, 'ብርሃንና ፀሐይ ወጣ፤ የተዋረዱም ሰዎች ከፍ ከፍ አሉ፤ የከበሩ ሰዎችንም አጠፉአቸው።'),
  ('a2983e1c-a9d0-5776-a285-5654ffa470c3', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'dca031a1-65e6-592b-a247-28b7487fdca7', 11, 11, 'መርዶክዮስም ይህን ሕልም እግዚአብሔርም ያደርግ ዘንድ የቈረጠውን ነገር አይቶ ነቃ፤ ይህንም ነገር በልቡ ጠበቀ፤ እስከ ሌሊትም ድረስ በሁሉም አቅጣጫ ያስተውለው ዘንድ ወደደ።'),
  ('95023136-2cdc-5469-a4d8-13b07f4f9cd0', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'a079f714-6691-5714-abef-49e394e071af', 1, 12, 'መርዶክዮስም ሀገሩንና አደባባይዋን ከሚጠብቁ ከንጉሡ ባለሟሎች ከሁለቱ ከታራና ከገበታ ጋር በአደባባይ ይቀመጥ ነበረ።'),
  ('ad9be9de-9451-5afa-a8bb-0a6cbd98279b', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'a079f714-6691-5714-abef-49e394e071af', 2, 13, 'ያሰቡት ምክራቸውንም ሰማ፤ ንጉሡን አርጤክስስን ይገድሉት ዘንድ ሴራን እንደ አዘጋጁ ዐወቀ፤ ተረዳም፤ ለንጉሡም የእነርሱን ነገር ነገረው።'),
  ('577722f8-2a4c-5a65-a660-b2deb9b56fe6', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'a079f714-6691-5714-abef-49e394e071af', 3, 14, 'ንጉሡም ሁለቱን ባለሟሎቹን መረመራቸው፤ ኀጢአታቸውንም አምነው በሞት ተቀጡ።'),
  ('dc8b197a-a5fd-5a7c-a9d9-3e5d05979016', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'a079f714-6691-5714-abef-49e394e071af', 4, 15, 'ንጉሡም ይህን ነገር በታሪክ ማስታወሻው ጻፈው፤ መርዶክዮስም ይህን ነገር ጻፈው።'),
  ('edcdb365-8134-594d-adca-cb06d2c76369', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'a079f714-6691-5714-abef-49e394e071af', 5, 16, 'ንጉሡም መርዶክዮስን በንጉሡ ግቢ ያገለግል ዘንድ አዘዘው፤ ስለዚህም ነገር ድርጎ አወጣለት።'),
  ('f2a61d56-7cae-5bf4-a588-b78350ecbbc3', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', 'a079f714-6691-5714-abef-49e394e071af', 6, 17, 'የአግ ወገን የሆነ የሐመዳቱ ልጅ ሐማ ግን የከበረ ነበረ፤ በንጉሡም ፊት ይቆም ነበር፤ የንጉሡ ባለሟሎች የሆኑ እነዚያ ሰዎች ስለ ሞቱ በወገኖቹና በመርዶክዮስ ክፉ ነገርን ያደርግ ዘንድ ይፈልግ ነበር።'),
  ('353041ab-9577-5da3-a271-d772e8ac7e36', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 1, 18, 'በአርጤክስስም ዘመን እንዲህ ሆነ፤ ይህም አርጤክስስ ከሕንድ ጀምሮ እስከ ኢትዮጵያ ድረስ በመቶ ሃያ ሰባት ሀገሮች ነገሠ።'),
  ('c2102080-4d50-5827-ae80-c0b9c532aee3', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 2, 19, 'በዚያም ዘመን ንጉሥ አርጤክስስ በሱሳ ከተማ በመንግሥቱ ዙፋን ላይ ተቀምጦ ሳለ፥'),
  ('d8402697-ca2d-5cf0-a100-d25abbb29d8e', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 3, 20, 'በነገሠ በሦስተኛው ዓመት ለባለሟሎቹና ለአገልጋዮቹ፥ ለቀሩትም ለፋርስና ለሜዶን ታላላቆች ሁሉ፥ ለሠራዊቱም አለቆች ሁሉ ግብዣ አደረገ።'),
  ('6f0fc764-e352-54c8-a63c-6a8977345298', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 4, 21, 'ከዚህም በኋላ የከበረውን የመንግሥቱን ሀብት፥ የታላቁንም የግርማዊነቱን ክብር መቶ ሰማንያ ቀን ያህል አሳያቸው።'),
  ('49265cf4-13fb-5508-adfb-9780acb6dd9c', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 5, 22, 'የሰርጉም ቀኖች በተፈጸሙ ጊዜ ንጉሡ በከተማ ለተገኙት ሕዝብ ሁሉ በንጉሡ ቤት አደባባይ ስድስት ቀን ግብዣ አደረገ።'),
  ('8ac4abcf-bc9a-5959-a567-3f255ad3504e', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 6, 23, 'በቤቱም ነጭ፥ አረንጓዴና ሰማያዊ መጋረጃዎች ከጥሩ በፍታና ከሐምራዊ ግምጃ በተሠራ ገመድ በብር ቀለበትና በዕብነ በረድ አዕማድ ላይ ተዘርግተው ነበር፤ አልጋዎቹም ከወርቅና ከብር ተሠርተው በቀይና በነጭ፥ በብጫና በጥቁር ዕብነ በረድ ወለል ላይ ነበሩ።'),
  ('c4588322-0c39-5e94-a7b0-2fd063e32fca', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 7, 24, 'የወርቅና የብር ጽዋዎች ነበሩ፤ ዋጋው ሠላሳ ሺህ የሚሆን የከበረ የዕንቍ ጽዋዕም ነበረ። ወይኑም ብዙ ነበር፤ ንጉሡም የሚጠጣው ወይን መዓዛ እጅግ መልካም ነበር።'),
  ('50e0b4c2-f848-5016-afe0-b6bb6689e09d', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 8, 25, 'በዓሉ ንጉሡ እንደ ፈቀደ ነበረ እንጂ እንደ ቀደመው ወግ አልነበረም። የእርሱንና የሰዎችን ፈቃድ ያደርጉ ዘንድ የቤቱን አዛዦች አዝዞ ነበርና።'),
  ('fd67c01c-8ab0-5d22-abab-19ce58423c76', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 9, 26, 'ንግሥቲቱም አስጢን በንጉሡ በአርጤክስስ ቤተ መንግሥት ለሴቶች ግብዣ አደረገች።'),
  ('3b08f837-b244-5ed7-aa67-ca344c525348', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 10, 27, 'በሰባተኛውም ቀን ንጉሡ አርጤክስስ ደስ ባለው ጊዜ በፊቱ የሚያገለግሉትን ሰባቱን ጃንደረቦች ሐማን፥ ባዛንን፥ ታራን፥ ባራዚንን፥ ዘቶልታን፥ አባታዛን፥ ታራባን'),
  ('25f51cfb-3101-5654-a007-22d8d243995e', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 11, 28, 'ንግሥቲቱ አስጢን መልከ መልካም ነበረችና ውበቷ ለአሕዛብ አለቆች እንዲታይ ዘውድ ጭነው ወደ ንጉሡ ፊት ያመጡአትና ያነግሡአት ዘንድ አዘዛቸው።'),
  ('0c8f2a5e-5989-5626-ae2b-d2496b194804', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 12, 29, 'ነገር ግን ንግሥቲቱ አስጢን በጃንደረቦች እጅ በላከው በንጉሡ ትእዛዝ ትመጣ ዘንድ እንቢ አለች፤ ንጉሡም አዝኖ እጅግ ተቈጣ።'),
  ('f8b6c20b-68b4-5fc5-a9a6-504e0bb71e51', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 13, 30, 'እርሱም አስጢን ያለችውን ለወዳጆቹ ነገራቸው፤ እንግዲህ እንደ ሕጉና እንደ ፍርዱም አድርጉ አላቸው፤'),
  ('84e24933-0cf9-5cad-a007-0fc893476df6', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 14, 31, 'በመንግሥቱም ቀዳሚዎች ሆነው የሚቀመጡ የንጉሡ ባለሟሎች የፋርስና የሜዶን መሳፍንት አርቄስዮስ፥ ሰርስትዮስ፥ ሚሊሲአር ወደ እርሱ መጡ፤'),
  ('17425c98-7991-51ef-aa33-1b67a3dafdc7', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 15, 32, 'ንጉሡም በጃንደረቦች እጅ ያዘዘውን ስላላደረገች በንግሥቲቱ በአስጢን ላይ ምን እንደሚያደርጉ እንደ ሕጉ ነገሩት።'),
  ('8df2170f-c109-57d6-abd5-c3c294e1bfb5', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 16, 33, 'ሜኬዎስም ለንጉሡና ለአለቆቹ እንዲህ አላቸው፥ “ንግሥት አስጢን ንጉሡን ብቻ የበደለች አይደለችም፤ አለቆቹንና የንጉሡን ሹሞች ሁሉ እንጂ።”'),
  ('787f8dc1-ce36-552c-a6e7-1c2101a46e1b', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 17, 34, 'እርሱም ንጉሡን እንቢ እንዳለችው የንግሥቲቱን ቃል ነገራቸው። “ዛሬ ይህች ንጉሡን አርጤክስስን እንሲ ካለችው፦'),
  ('7b3ac947-23ff-500d-a7da-552f70e37f9a', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 18, 35, 'ዛሬም የፋርስና የሜዶን መኳንንት ሚስቶች ንግሥቲቱ ለንጉሡ የመለሰችለትን ሰምተው እነርሱም ደፍረው ባሎቻቸውን ይንቃሉ።'),
  ('6375a8bf-80ae-5889-a629-0318a1289672', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 19, 36, 'ንጉሡም ቢፈቅድ ንግሥቲቱ አስጢን ወደ ንጉሡ ወደ አርጤክስስ ፊት ከእንግዲህ ወዲያ እንዳትገባ የንጉሡ ትእዛዝ ከእርሱ ይውጣ፤ እንዳይለወጥም በፋርስና በሜዶን ሕግ ይጻፍ፤ ንጉሡም ንግሥትነቷን ከእርስዋ ለተሻለችው ለሌላዪቱ ሴት ይስጥ።'),
  ('d8361ea5-5311-5e94-a9c0-b2636a5ed11b', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 20, 37, 'ንጉሡም የሠራው ሕግ በመንግሥቱ ሁሉ በሰፊው ይነገር፤ ያንጊዜ ሴቶች ሁሉ ባሎቻቸውን ባለጸጋም ቢሆን ድሃም ቢሆን ያከብራሉ።”'),
  ('4276dabf-8dac-5a51-a9ff-51ee45e0b9cb', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 21, 38, 'ይህም ምክር ንጉሡንና አዛውንቶቹን ደስ አሰኛቸው፤ ንጉሡም እንደ ሜኬዎስ ቃል አደረገ።'),
  ('c7ad7b91-46c8-5617-a51e-3c766b458814', '16c3f92c-c510-5f3a-ab29-b5a4aa6b15ad', '59ab0fe9-548c-5645-a6a6-b79d2102fb3b', 22, 39, 'ንጉሡም ሚስቶች ባሎቻቸውን ይፈሩአቸው ዘንድ በመንግሥቱ ወደ አሉ ሀገሮች ሁሉ በዚሁ ቃል ላከ።'),
  ('a1929779-ff22-5ef1-aae3-f2ed07b51af5', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 1, 1, 'ከዚህም ነገር በኋላ የንጉሡ የአርጤክስስ ቍጣ በበረደ ጊዜ ምን እንዳለችውና እንዴት እንደፈረደባት አስታውሶ አስጢንን ረሳት።'),
  ('8fb3781a-a42a-5836-a416-fc112b5bcb0b', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 2, 2, 'ንጉሡንም የሚያገለገሉ ብላቴኖች እንዲህ አሉት፥ “መልከ መልካም የሆኑ ደናግል ለንጉሡ ይፈለጉለት።'),
  ('022f2f02-3057-5414-a7a7-9fbb6c07b193', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 3, 3, 'ንጉሡም በመንግሥቱ ሀገሮች ሁሉ አለቆችንና መሳፍንትን ይሹም፤ መልከ መልካም ደናግል ልጆችንም ይምረጡለት፤ ወደ ሱሳ ከተማ ወደ ሴቶች ቤትም ያምጡአቸው፤ ሴቶችን ለሚጠብቅ ለንጉሡ ጃንደረባም ይስጡአቸው፤ ቅባትና የሚያስፈልጋቸውንም ይስጧቸው።'),
  ('d97b57e8-b6c8-5bd0-a74b-3e0d5690d819', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 4, 4, 'ከእነርሱም ንጉሡን ደስ የምታሰኝ ቆንጆ በአስጢን ስፍራ ከእርሱ ጋር ትንገሥ።” ይህም ነገር ንጉሡን ደስ አሰኘው፤ እንዲሁም አደረገ።'),
  ('6e8ef6b9-25f8-5af9-ab6a-38ab8cc3113f', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 5, 5, 'አንድ አይሁዳዊ የቂስ ልጅ የሰሜኢ ልጅ የኢያዕር ልጅ መርዶክዮስ የሚባል ከብንያም ወገን በሱሳ ከተማ ነበረ።'),
  ('8629f921-b42c-59aa-a573-6f57ab83c255', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 6, 6, 'እርሱም የባቢሎን ንጉሥ ናቡከደነፆር ከኢየሩሳሌም ከማረካቸው ምርኮኞች ወገን ነበረ።'),
  ('83f7be6a-2da0-5071-a61d-be3084bb3193', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 7, 7, 'ያሳደጋትም ልጅ ነበረችው፤ እርስዋም የአጎቱ የአሚናዳብ ልጅ ነበረች፤ ስምዋም አስቴር ይባል ነበር። ከወላጆችዋም በወጣች ጊዜ ልጅ ትሆነው ዘንድ አሳድጎአት ነበር፤ ያችም ልጅ መልከ መልካም ነበረች።'),
  ('f3dffda9-e929-5864-a075-badb078f2170', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 8, 8, 'የንጉሡም ትእዛዝና አዋጅ በተሰማ ጊዜ ብዙ ቆነጃጅት ወደ ሱሳ ከተማ ወደ ጋይ እጅ ተሰበሰቡ፤ አስቴርም ወደ ንጉሡ ቤት ወደ ሴቶች ጠባቂው ወደ ጋይ ተወሰደች።'),
  ('3fd04927-7b71-58ca-abcc-aee8f144e404', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 9, 9, 'ልጅቱም ደስ አሰኘችው፤ በእርሱም ዘንድ ሞገስን አገኘች፤ ቅባቷንም፥ ድርሻዋንም ከንጉሡ ቤት ልታገኝ የሚገባትን ሰባት ደንገጥሮች ፈጥኖ ሰጣት፥ እርስዋንና ደንገጥሮችዋንም በሴቶች ቤት በተመረጠ ስፍራ አኖረ።'),
  ('453bac73-e79e-59f2-a31b-d24db41fe1ea', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 10, 10, 'መርዶክዮስ እንዳትናገር አዝዞአት ነበርና አስቴር ሕዝብዋንና ወገንዋን አልተናገረችም።'),
  ('0cb2a53c-648d-5f7c-a6ae-2f86fe9bf309', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 11, 11, 'መርዶክዮስም የአስቴርን ደኅንነትና የሚሆንላትን ያውቅ ዘንድ ዕለት ዕለት በሴቶች ቤት ወለል ትይዩ ይመላለስ ነበር።'),
  ('b60d1883-5564-5d48-a667-a6f2b6803fb2', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 12, 12, 'የመንጻታቸውም ወራት ስድስት ወር ያህል በከርቤ ዘይት፥ ስድስት ወርም በጣፋጭ ሽቱና በልዩ ልዩም በሚያነጻ ነገር ይፈጸም ነበርና እንደ ሴቶች ወግ ዐሥራ ሁለት ወር እንዲሁ ከተደረገላት በኋላ ወደ ንጉሡ ወደ አርጤክስስ ለመግባት የአንዳንዲቱ ቆንጆ ተራ በደረሰ ጊዜ፥'),
  ('7ded19ab-2d20-5a65-a5a5-112d0f2c635c', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 13, 13, 'በዚህ ወግ ቆንጆዪቱ ወደ ንጉሡ ትገባ ነበር፤ ከሴቶች ቤት ወደ ንጉሡ ቤት ለመውሰድ የምትሻውን ሁሉ ይሰጡአት ነበር።'),
  ('6ad7952a-abaa-5b25-a399-c3ff2788045a', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 14, 14, 'ማታም ትገባ ነበር፤ ሲነጋም ተመልሳ ወደ ሁለተኛው የሴቶች ቤት ቁባቶችን ወደሚጠብቅ ወደ ንጉሡ ጃንደረባ ወደ ጋይ ትመጣ ነበር፤ ንጉሡም ያልፈለጋት እንደ ሆነ፥ በስምዋም ያልተጠራች እንደ ሆነ ከዚያ ወዲያ ወደ ንጉሡ አትገባም ነበር።'),
  ('0c199b51-b4af-555f-a307-6aec23c4a0ac', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 15, 15, 'ወደ ንጉሡም ትገባ ዘንድ የመርዶክዮስ አጎት የአሚናዳብ ልጅ የአስቴር ተራ በደረሰ ጊዜ የሴቶች ጠባቂ የንጉሡ ጃንደረባ ጋይ ከሚለው በቀር ምንም አልፈለገችም ነበር፤ አስቴርም በሚያዩአት ሁሉ ዐይን ሞገስን አግኝታ ነበር።'),
  ('4e385d01-498b-5988-a3e2-bdbd1f171925', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 16, 16, 'አርጤክስስም በነገሠ በሰባተኛው ዓመት አዳር በሚባለው በዐሥራ ሁለተኛው ወር አስቴር ወደ ንጉሡ ቤት ገባች።'),
  ('05c6ffff-df7d-591a-a1e6-5592825ed691', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 17, 17, 'ንጉሡም ከሴቶች ሁሉ ይልቅ አስቴርን ወደደ፤ በዐይኑም ከደናግል ሁሉ ይልቅ ሞገስንና መወደድን አገኘች፤ የንግሥትነትንም ዘውድ በራስዋ ላይ አደረገ።'),
  ('ae0f3436-0d30-55e5-add7-52ffb9472847', '455eca51-cea4-5884-ad6d-0019320b82e9', 'c84749db-9f0e-5858-a615-ff586f7ba2bd', 18, 18, 'ንጉሡም ለባለሟሎቹና ለአገልጋዮቹ ሁሉ ሰባት ቀን ያህል ትልቅ ግብዣ አደረገ፤ የአስቴርንም ሰርግ ከፍ አደረገው፤ ለሀገሮቹም ሁሉ ይቅርታ አደረገ።'),
  ('499e8457-e481-5ac1-a0dc-fcbdff814a71', '455eca51-cea4-5884-ad6d-0019320b82e9', '7853c152-83c9-5453-a507-6a99ae8c08eb', 1, 19, 'መርዶክዮስም በንጉሡ በር ያገለግል ነበር።'),
  ('90dde5bd-f5be-504a-a644-685b6f16a179', '455eca51-cea4-5884-ad6d-0019320b82e9', '7853c152-83c9-5453-a507-6a99ae8c08eb', 2, 20, 'አስቴርም እግዚአብሔርን እንድትፈራ ከእርሱ ጋር እንዳደገችበት ጊዜ ታደርግ ዘንድ መርዶክዮስ አዝዞአት ነበርና መርዶክዮስ እንዳዘዛት ወገንዋንና ሕዝብዋን አልተናገረችም። አስቴርም የአኗኗርዋን ሥርዐት አልለወጠችም።'),
  ('8451c5a9-8148-52cb-a930-bba2a9d29493', '455eca51-cea4-5884-ad6d-0019320b82e9', '7853c152-83c9-5453-a507-6a99ae8c08eb', 3, 21, 'በዚያም ወራት መርዶክዮስ ከፍ ከፍ ስላለ ደጁን ከሚጠብቁት ከንጉሡ ጃንደረቦች ሁለቱ ተቈጡ፤ ንጉሡን አርጤክስስንም ይገድሉት ዘንድ ፈለጉ።'),
  ('2c4199d1-33bc-577d-af50-7d3bdf176d8d', '455eca51-cea4-5884-ad6d-0019320b82e9', '7853c152-83c9-5453-a507-6a99ae8c08eb', 4, 22, 'ነገሩም ለመርዶክዮስ ተገለጠ፤ እርሱም ለንግሥቲቱ ለአስቴር ነገራት፤ አስቴርም በመርዶክዮስ ስም ለንጉሡ ነገረች።'),
  ('2f6e4513-154a-5fe1-aaa3-68f257ba2d6f', '455eca51-cea4-5884-ad6d-0019320b82e9', '7853c152-83c9-5453-a507-6a99ae8c08eb', 5, 23, 'ንጉሡም ሁለቱን ባለሟሎቹን በመረመራቸው ጊዜ አመኑ፤ ሰቀላቸውም። ከዚህም በኋላ ንጉሡ ይህን ነገር ስለ መርዶክዮስ ክብር የመንግሥቱ ታሪክ በተጻፈበት መጽሐፍ ይጽፉት ዘንድ አዘዘ።'),
  ('30c89dc0-ff3d-5fd6-a8d4-299049ca866c', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 1, 1, 'ከዚህም ነገር በኋላ ንጉሡ አርጤክስስ የቡጊያዊውን የሐመዳቱን ልጅ ሐማን ከፍ ከፍ አደረገው፤ ከባለሟሎቹም ሁሉ በላይ አስቀመጠው።'),
  ('17d63ac0-2f8f-5b8f-ab11-70d1fba51de2', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 2, 2, 'ንጉሡም ስለ እርሱ እንዲሁ አዝዞ ነበርና በንጉሡ በር ያሉት የንጉሡ አገልጋዮች ሁሉ ለሐማ ይሰግዱ ነበር። ነገር ግን መርዶክዮስ ብቻ አይሰግድለትም ነበር።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('655c23e2-3e90-55b3-abda-982b238f4be1', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 3, 3, 'በንጉሡም በር ያሉት የንጉሡ አገልጋዮች መርዶክዮስን፥ “የንጉሡን ትእዛዝ ለምን ትተላለፋለህ?” አሉት።'),
  ('857d9af1-7c62-5e31-ae86-661c9d4227fb', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 4, 4, 'ይህንም ዕለት ዕለት ይነግሩት ነበር፤ እርሱ ግን አይሰማቸውም ነበር፤ ለሐማም የንጉሡን ትእዛዝ እንደማይቀበልና መርዶክዮስ አይሁዳዊ እንደ ሆነ ነገሩት።'),
  ('78e6c628-5811-5fb5-aa32-04222c20558f', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 5, 5, 'ሐማም መርዶክዮስ እንዳልሰገደለት ባየ ጊዜ እጅግ ተቈጣ።'),
  ('23be242f-7baf-5010-a76f-05873a40bdf1', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 6, 6, 'በአርጤክስስ መንግሥት የነበሩትን የአይሁድን ሕዝብ ሁሉ ያጠፋም ዘንድ ፈለገ።'),
  ('f6b6dd32-8e3c-5813-ac4c-f3cf29eec781', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 7, 7, 'ንጉሡ አርጤክስስ በነገሠ በዐሥራ ሁለተኛው ዓመት እንዲህ አደረገ፤ የመርዶክዮስን ወገኖች በአንዲት ቀን ያጠፋቸው ዘንድ በየቀኑና በየወሩ ዕጣ ይጥል ነበር፤ ዕጣውም በአዳር ወር በዐሥራ አራተኛው ቀን ወጣ።'),
  ('0ade5684-198b-5e13-a94c-42a3ec138901', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 8, 8, 'ሐማም ለንጉሡ ለአርጤክስስ እንዲህ ብሎ ነገረው፥ “አንድ ከዳተኛ ሕዝብ በአሕዛብ መካከል በመንግሥትህ ሀገሮች ሁሉ ተበትነዋል፤ ሕጋቸውም ከሕዝቡ ሁሉ ሕግ የተለየ ነው፤ የንጉሡንም ሕግ አይጠብቁም፤ ንጉሡም ይተዋቸው ዘንድ አይገባውም።'),
  ('dc5eccb1-1f89-577c-ac55-9c3b8ec4ad35', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 9, 9, 'ንጉሡም ቢፈቅድ እንዲጠፉ ይጻፍ፤ እኔም ወደ ንጉሡ ግምጃ ቤት ዐሥር ሺህ መክሊት ብር አገባለሁ።”'),
  ('4661435f-1966-5ebb-aa38-a673738e4757', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 10, 10, 'ንጉሡም ቀለበቱን ከእጁ አወለቀ፤ በአይሁድም ላይ የጻፈውን እንዲያትምበት ለሐማ ሰጠው።'),
  ('65835a81-a7f5-5ac1-a2a8-c749489f59d6', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 11, 11, 'ንጉሡም ሐማን፥ “ብሩ ለአንተ ይሁን፤ ሕዝቡንም እንደ ወደድህ አድርግ” አለው።'),
  ('14ffc74a-3620-5091-a4d2-c3c79c510fdd', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 12, 12, 'በመጀመሪያውም ወር ከወሩም በዐሥራ ሦስተኛው ቀን የንጉሡ ጸሓፊዎች ተጠሩ፤ ከሕንድ ጀምሮ እስከ ኢትዮጵያ ድረስ ወዳሉ መቶ ሃያ ሰባት ሀገሮች በየሀገሩ ወዳሉ ሹሞችና አለቆች ወደ አሕዛብም ሁሉ ገዢዎች እንደ ቋንቋቸው በንጉሡ በአርጤክስስ ቃል ሐማ እንዳዘዘ ጻፉ።'),
  ('bc9c8442-e085-5c32-a188-f02471292251', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', '98f64ef2-5cf5-59c8-aa89-3907faeaaef7', 13, 13, 'በዐሥራ ሁለተኛው ወር በአዳር በዐሥራ ሦስተኛው ቀን የአይሁድን ዘር ሁሉ በአንድ ቀን ያጠፉ ዘንድ፥ ገንዘባቸውንም ይዘርፉ ዘንድ ደብዳቤዎች በመልእክተኞች እጅ ወደ ንጉሡ ወደ አርጤክስስ ሀገሮች ሁሉ ተላኩ።'),
  ('7946191a-d096-5eea-a8c7-a4a84f1a95e2', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 1, 14, 'የንጉሡ የአርጤክስስ ደብዳቤዎችም እንዲህ ይላሉ፥ “ከሕንድ ጀምሮ እስከ ኢትዮጵያ ድረስ በመቶ ሃያ ሰባት ሀገሮች ላሉ ለደጃዝማቾችና ለራሶች፥ ለመኳንንትም ትድረስ'),
  ('309f3e4e-ca01-5724-a168-5c2654093e65', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 2, 15, 'ብዙ አሕዛብን ከገዛሁ በኋላ፥ ሀገሩን ሁሉ ከገዛሁ በኋላ እነዚህን አጥፍቼ፥ ሁሉን አዘጋጅች ለዘለዓለሙ በየዋሀት፥ በጸጥታ እኖር ዘንድ ወደድሁ። መንግሥቴ የተወደደና፥ ጸጥ ያለ እንደ መሆኑ ሁሉን ሠራርቼ ለእኔ የሚታዘዝልኝ ሁሉ ያለ ድንጋጤ ይኖር ዘንድ ነው እንጂ ራሴን ከፍ ከፍ የማደርግ በመንግሥቴ ጽናት አይደለም፤ ደብዳቤዪቱም እስከ ምድር ዳርቻ ትድረስ፤ ከእኔ ዘንድ የሚገኝ፥ በሕዝቡም ዘንድ የሚወደድ ተድላ ደስታን አደርጋለሁ።'),
  ('4ad54658-343e-5ce4-a303-398a4d982fee', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 3, 16, 'በሚገባ ሁልጊዜ ይህን ማዘጋጀት በምችል ገንዘብ ለአማካሪዎች እሺ ብዬ በልቡናዬ ሳልጸጸት በጎ ነገርን አደርግ ዘንድ መጣሁ።'),
  ('770950a5-b923-5aa6-a7b0-c464a5ef57de', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 4, 17, 'ከእኔም በታች ከተሾመ ወደ በጎ ነገር ከመራን፥ ሥርዐቱም ልዩ የሆነ፥ ከአሕዛብም ሁሉ ተለይቶ ለንጉሡ ትእዛዝ ሁልጊዜ የማይታዘዝ፥ ሕጋችንንና ሥርዐታችንንም እንቢ የሚል ሕዝብ በዚህ ዓለም ሁሉ ካሉ አሕዛብ ሁሉ ጋር አንድ እንደ ሆነ ከነገረን ከሐማ በእውነት በሚገባ ተላከ።'),
  ('8b8b9679-a22c-5603-a684-dcd56372f4f9', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 5, 18, 'ይህንም ሕዝብ ብቻውን ተለይቶ፥ ሥርዐቱም ከሰው ሥርዐት የተለየ ሆኖ፥ ባዕድም ሆኖና ተለውጦ፥ ከሕጋችንም ወጥቶ አገኘነው። ፈቃዳቸውንም ለመፈጸም ክፉ ሥራ ይሠራሉ፤ መንግሥታችንንም እንደ ኢምንት አደረጓት።'),
  ('01718365-1fca-5365-a82c-a3b8bfea838c', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 6, 19, 'በሁሉም ላይ በተሾመ፥ ከአባታችን በታች በሆነ በሐማ ደብዳቤዎች ስለጻፍንላችሁ ፈጽማችሁ ሳትራሩላቸው የዚች ዓመት ዐሥራ ሁለተኛው ወር አዳር በባተ በዐሥራ አራተኛው ቀን ሁሉንም በጠላቶቻቸው ሰይፍ ከልጆቻቸውና ከሚስቶቻቸው ጋር ያጠፏቸው ዘንድ እነሆ አዘዝን።'),
  ('b4248d2c-eaaa-5bc6-a158-1802b51c956c', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 7, 20, 'እንደዚሁም ታናናሹንና ታላላቁን በአንዲት ቀን ወደ መቃብር ታወርዷቸው ዘንድ እነሆ አዘዝን፤ ከዚህም በኋላ ሀገራችን ፈጽማ ከሥራቸው ታርፍ ዘንድ ከእነርሱ የምታስቀሩት አይኑር።”'),
  ('2f640f52-ca1b-554f-a115-5ee0231b79c0', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 8, 21, 'በዚያም ቀን ይዘጋጁ ዘንድ የደብዳቤው ቅጅ በየሀገሩ ላሉ አሕዛብ ሁሉ ታወጀ።'),
  ('4357ea0a-9ac4-599f-ab24-db69838d3aea', '88d2e280-f6f4-5066-a38e-a4a8b163e8f0', 'ebec1e47-1444-58a0-a4b3-092edf58a939', 9, 22, 'መልእክተኞቹም በንጉሡ ትእዛዝ እየቸኰሉ ሄዱ፤ አዋጁም በሱሳ ከተማ ተነገረ። ንጉሡና ሐማም ሊጠጡ ተቀመጡ፤ ከተማዪቱ ሱሳ ግን ተደናገጠች።'),
  ('df2742f4-a42b-5254-afe8-a66f1887a430', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 1, 1, 'መርዶክዮስም የተደረገውን ሁሉ በዐወቀ ጊዜ ልብሱን ቀደደ፤ ማቅም ለበሰ፤ በራሱም ላይ ዐመድ ነሰነሰ፤ ወደ ከተማዪቱም መካከል ወጣ። “ያለ በደል ሕዝብን ታጠፋላችሁን?” እያለም ታላቅና የመረረ ጩኸት ጮኸ።'),
  ('1665960b-4c90-547c-a499-abc8928378b9', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 2, 2, 'ማቅም ለብሶ፥ ዐመድ ነስንሶ በንጉሡ በር መግባት አይገባም ነበርና ከንጉሡ በር ደርሶ ቆመ።'),
  ('92b571d7-2a89-53c9-ae1f-b0ae23e3f971', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 3, 3, 'የንጉሡም ትእዛዝና ዐዋጅ በደረሰበት ሀገር ሁሉ በአይሁድ ላይ ታላቅ ኀዘን፥ ልቅሶና ዋይታም ሆነ፤ ብዙዎችም ማቅና ዐመድ ለራሳቸው አነጠፉ።'),
  ('72993a3a-239b-5b62-af5c-c08c52f070ff', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 4, 4, 'የአስቴርም ደንገጥሮችዋና ጃንደረቦችዋ መጥተው ነገሩአት፤ ንግሥቲቱም እጅግ አዘነች፤ ማቁንም ይለውጥ ዘንድ የሚለብሰውን ልብስ ለመርዶክዮስ ላከችለት፤ እርሱ ግን ማቁን አልተውም አለ።'),
  ('8ec501c3-385a-5e12-ad15-08e29ce5b845', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 5, 5, 'አስቴርም ያገለግላት ዘንድ ንጉሡ ያቆመውን አክራትዮስን ጠራች፤ እርሱም ከጃንደረቦቹ አንዱ ነበረ፤ እርስዋም ይህ ነገር ምንና ምን እንደ ሆነ ያስታውቃት ዘንድ ወደ መርዶክዮስ እንዲሄድ ላከችው።'),
  ('55d47089-f453-55e2-a4ed-0d7f3508a75a', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 6, 6, 'አክራትዮስም በንጉሡ በር ፊት ወደ ነበረችው ወደ ከተማዪቱ አደባባይ ወደ መርዶክዮስ ወጣ።'),
  ('e0c96458-a251-5c92-a452-05fb5633b72d', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 7, 7, 'መርዶክዮስም የተደረገውን ሁሉ፥ አይሁድንም ለማጥፋት ሐማ በንጉሡ ግምጃ ቤት ይመዝን ዘንድ የተናገረውን የብሩን ቍጥር ነገረው።'),
  ('1569e20e-631e-5ace-a5ba-5061cd1c3a05', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 8, 8, 'ለአስቴርም እንዲያሳያት ለመጥፋታቸው በሱሳ የተነገረውን የዐዋጁን ጽሕፈት ቅጅ ሰጠው፤ ወደ ንጉሡም ገብታ ስለ ሕዝብዋ ትለምነውና ትማልደው ዘንድ እንዲነግራት፥ “በእጄ እንዳደግሽ የችግርሽን ጊዜ አስቢ፤ ከንጉሡ በታች የተሾመው ሐማ ይገድሉን ዘንድ አዝዞአልና ወደ ጌታ ወደ እግዚአብሔር ለምኝ፤ ለንጉሡም ነግረሽ ከሞት አድኝን በላት” አለው።'),
  ('626b1c1e-8c74-570a-aaef-3b09cd85c121', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 9, 9, 'አክራትዮስም ገብቶ የመርዶክዮስን ቃል ለአስቴር ነገራት።'),
  ('343129a7-e128-5d9f-ab7b-de9bc6dd9d4a', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 10, 10, 'አስቴርም አክራትዮስን ተናገረችው፤ ለመርዶክዮስም እንዲህ የሚል መልእክት ሰጠችው።'),
  ('047fc7ba-6046-52e2-ab34-079c49a13374', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 11, 11, '“የንጉሡ አገልጋዮችና በሀገሮችም የሚኖሩ ሕዝብ ሁሉ ወንድ ወይም ሴት ቢሆን ሳይጠራ ወደ ንጉሡ ወደ ውስጠኛው ወለል የሚገባ ሁሉ በሕይወት ይኖር ዘንድ ንጉሡ የወርቁን ዘንግ ካልዘረጋለት በቀር እርሱ ይሞት ዘንድ ሕግ እንዳለ ያውቃሉ፤ እኔ ግን ወደ ንጉሡ ለመግባት ይህን ሠላሳውን ቀን አልተጠራሁም።”'),
  ('4b440959-cfc8-5475-ab21-6419f1112e55', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 12, 12, 'አክራትዮስም የአስቴርን ቃል ለመርዶክዮስ ነገረው።'),
  ('efe60129-6d32-5666-a96e-fa56675509f6', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 13, 13, 'መርዶክዮስም አክራትዮስን አለው፥ “ሂድና ለአስቴር እንዲህ በላት፦ አንቺ በንጉሥ ቤት ስለ ሆንሁ ከአይሁድ ሁሉ ተለይች ብቻዬን እድናለሁ ብለሽ በልብሽ አታስቢ።'),
  ('931b397f-b657-55f6-a7d2-071ffa0f94d0', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 14, 14, 'በዚህ ጊዜ ቸል ብትዪ ረድኤትና መዳን ለአይሁድ ከሌላ ስፍራ ይሆንላቸዋል፤ አንቺና የአባትሽ ቤት ግን ትጠፋላችሁ፤ ደግሞስ ወደ መንግሥት የመጣሽው እንደዚህ ላለው ጊዜ እንደ ሆነ ማን ያውቃል?”'),
  ('defe73b8-b102-591e-a141-433e6272ceb2', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 15, 15, 'አስቴርም እንዲህ ብሎ ለመርዶክዮስ እንዲመልስ አዘዘችው፦'),
  ('0933515d-3227-57f6-a1b4-5f09bf939980', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 16, 16, '“ሂደህ በሱሳ ያሉትን አይሁድ ሁሉ ሰብስብ፤ ለእኔም ጹሙ፤ ሦስት ቀን ሌሊቱንና ቀኑን አትብሉ፤ አትጠጡም፤ እኔና ደንገጥሮች ደግሞ እንዲሁ እንጾማለን፤ ምንም እንኳ ያለ ሕግ ቢሆን ወደ ንጉሡ እገባለሁ፤ ብጠፋም እጠፋለሁ።”'),
  ('3f1652b8-6f32-5b34-a8ac-e960a374a344', '1114968f-f838-55d9-aace-956f8d0a55d2', '3e206d28-4bac-50bf-a3b9-ec46e494f519', 17, 17, 'መርዶክዮስም ሄዶ አስቴር እንዳዘዘችው ሁሉ አደረገ።'),
  ('a11a0efe-3fdd-587e-ae7e-0a5eb3ed9e7b', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 1, 18, 'እግዚአብሔር ያደረገውን ሁሉ እያሰበ ወደ እግዚአብሔር ለመነ።'),
  ('e7ea3abc-3a80-5037-ae0d-37209e3482b2', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 2, 19, 'እንዲህም አለ፥ “አቤቱ! አቤቱ! ሁሉን የምትገዛ፥ በሥልጣንህ ሁሉን የፈጠርህ ንጉሥ! እስራኤልን ታድናቸው ዘንድ ብትወድ የሚከራከርህ የለም፤'),
  ('78c2f123-3003-59ed-acf2-19c4b6f0376b', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 3, 20, 'ሰማይንና ምድርን፥ ከሰማይ በታች ያለ ድንቅ ፍጥረትንም ሁሉ አንተ ፈጥረሃልና፥'),
  ('e2183df8-c58e-5f20-a17f-9c8329d4c64e', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 4, 21, 'አንተ ሁሉን ታውቃለህ፤ አቤቱ ለዚህ ትዕቢተኛ ሐማ ያልሰገድሁ በመናቅ እንዳይደለ፥ በትዕቢትም እንዳይደለ፥ ራሴንም ከፍ ከፍ በማድረግ እንዳይደለ አንተ ታውቃለህ።'),
  ('55ed8917-2251-550d-a699-c57cc3d1564b', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 5, 23, 'የእግዚአብሔርን ክብር የሰው ክብር እንዳላደርግ፥ ከአንተም ከጌታዬ በቀር ለማንም እንዳልሰግድ፥ ይህን ነገር አደረግሁት እንጂ፥ እስራኤልስ የሚድኑ ከሆነ እግሩን እስም ዘንድ በወደድሁ ነበር፤ ይህንም ሥራ በትዕቢት አላደረግሁትም።'),
  ('094ccf03-c124-5085-a368-f5b17a2bff9b', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 6, 25, 'ያጠፉን ዘንድ በጠላትነት ተነሥተውብናልና፥ መጀመሪያ ርስትህንም ያጠፉ ዘንድ ወድደዋልና አሁንም አቤቱ የአብርሃም አምላክ ንጉሥ እግዚአብሔር ሆይ! ወገኖችህን አድን።'),
  ('dbb2edc6-ed70-53e4-a9fb-1c11cfcc7fd0', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 7, 26, 'ከግብፅ ሀገር ያዳንኻቸው ርስትህን ቸል አትበል።'),
  ('a7ac053d-5dc5-5fa4-a427-17de89136bd6', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 8, 27, 'ልመናችንንም ሰምተህ ወገኖችህን ይቅር በል፤ አቤቱ በሕይወት ሳለን ስምህን እናመሰግን ዘንድ ኀዘናችንን ወደ ደስታ መልሰው፤ ተስፋ የሚያደርጉህንም ሰዎች አለኝታቸውን አታጥፋ።”'),
  ('acb3edde-b80b-55c1-a9e6-2d396f3f21e2', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 9, 28, 'በፊታቸው ሞት ደርሶባቸዋልና እስራኤል ሁሉ ጮኹ፤ ቃላቸውንም አሰምተው በኀይላቸው ተናገሩ።'),
  ('51e9242a-e318-5bf4-a567-53504bde41a8', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 10, 29, 'አስቴርም ሞትን ወደ መፍራት ደርሳለችና ሰውነትዋን ለእግዚአብሔር አደራ ሰጠች።'),
  ('a68c641a-0ad4-505d-ab12-1b7cffcb2163', '1114968f-f838-55d9-aace-956f8d0a55d2', 'a5a5dd06-0e9d-5167-a369-9dc49c8f2779', 11, 30, 'የደስታ ልብስዋን አውልቃ የኀዘን ልብስዋን ለበሰች፤ በደስታ ሽቱም ፋንታ በራስዋ ላይ ዐመድና ትቢያን ነሰነሰች። ሰውነትዋንም ፈጽማ አሳዘነች። በፀጕርዋ ሰርሜዶ ፋንታም ትቢያ ጨመረች።'),
  ('31de195d-e3f1-54b3-a41a-99c40ed80f70', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 1, 31, 'ወደ እስራኤል አምላክ ወደ እግዚአብሔር እንዲህ ብላ ለመነች፥ “አቤቱ! ረዳት አንተ ብቻ ነህ፤ ሞት ወደ እኔ ቀርቦአል፤ ረዳት የሌለኝ ብቸኛ የሆንሁ እኔን ርዳኝ።'),
  ('2a858552-5420-5526-a454-887c9facde2a', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 2, 33, 'አቤቱ! እኔም ከልጅነቴ ጀምሬ ከአባቶች ወገኖች ዘንድ አንተ ከአሕዛብ ሁሉ ለይተህ እስራኤልን ገንዘብ እንዳደረግሃቸው፥ ለዘለዓለሙም ርስት ይሆኑህ ዘንድ አባቶቻችንን ከዘመዶቻቸው ለይተህ እንደተቀበልሃቸው ሰማሁ፤ አሁንም እንደ ተናገርህ ሁሉን አደረግህላቸው።'),
  ('ebbedd27-4536-5c6a-abc4-ef30761d5e74', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 3, 34, 'በፊትህ በደልን፤ በጠላቶቻችንም እጅ ጣልኸን። የአሕዛብን ጣዖቶች አመስግነናልና። አቤቱ አንተ ጻድቅ ነህ።'),
  ('64ddb772-b088-5f6e-a4a8-2889d816eb76', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 4, 36, 'አሁንም እጃቸውን ወደ ጣዖቶቻቸው ያነሡ አሕዛብ በጽኑ አገዛዝ ገዙን እንጂ አልተዉንም።'),
  ('4305b192-9437-53ff-a936-ac742d57f128', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 5, 37, 'በቃልህ የሠራኸውን ሥርዐት ያስወግዱ ዘንድ፥ ርስትህንም ያጠፉ ዘንድ፥ የሚያመሰግኑህንም ሰዎች አፍ ይዘጉ ዘንድ፥ የቤተ መቅደስንም ሥርዐትና መሠዊያህን ያጠፉ ዘንድ፥'),
  ('41f0c3fc-a0aa-511f-a428-f4f8aeb13b2f', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 6, 38, 'ለከንቱ ጣዖት ለማድላት የአሕዛብንም አፍ ይከፍቱ ዘንድ፥ ሥጋዊ ንጉሥንም ለዘለዓለሙ ያመሰግኑ ዘንድ በጽኑ አገዛዝ ገዙን።'),
  ('978c4f0d-c7ff-587c-a312-85cd7d3220cb', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 7, 39, 'ባጸናኸው ሕግ ያሉትን አሳልፈህ አትስጣቸው፤ በመከራችንም አይሳቁብን። ነገር ግን ምክራቸውን በራሳቸው መልስ፤ በእኛም ላይ በጠላትነት የተነሣውን አዋርደው።'),
  ('b061d9b7-9835-5a67-abeb-d084c74bb58e', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 8, 40, 'አቤቱ አስበን፤ በመከራችንም ጊዜ ተገለጥልን፤ አለቆችን ሁሉ ያጸናህ የአማልክት ንጉሥ ሆይ! እኔንም አጽናኝ።'),
  ('bf8806f3-4028-5212-a02e-9876a9259b06', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 9, 41, 'በአንበሳው ፊት በአንደበቴ በጎ ነገርን አድርግ፤ የሚዋጋንንም ይጣላው ዘንድ፥ የእርሱንና ከእርሱ ጋር የሚተባበሩትንም ጥፋት ይናገር ዘንድ ልቡናውን መልሰ።'),
  ('f747d5a7-4962-50f9-ad34-5d55a79d969f', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 10, 42, 'እኛን ግን በእጅህ አድነን፤ አቤቱ ከአንተ በቀር ማንም ሌላ ረዳት የሌለኝ ብቸኛ የሆንሁ እኔንም ርዳኝ። አቤቱ አንተ ሁሉን ታውቃለህ፤ የኀጢአተኞችን ክብራቸውን እንድጠላ፥ ያልተገረዙትንና የሌሎችን ሁሉ ምንጣፍ እንደምጠላ አንተ መርምረህ ታውቃለህ።'),
  ('8f5fcc7d-9bdf-5902-a250-0b8d41dfa36d', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 11, 44, 'አንተ መከራዬን ታውቃለህ፤ በከበርሁበትም ወራት የምታይበት በራሴ ላይ ያለ ጌጥ ደስ እንደማያሰኘኝ፥ እንደ ደም ጨርቅም እንደምጸየፈው፥ በምከብርበትና በማርፍበትም ወራት እንደማላጌጥበት አንተ ታውቀዋለህ።'),
  ('39e27e09-19f4-5db6-a854-baf5a4f8dbac', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 12, 45, 'እኔ ባሪያህ የሐማን ማዕድ አልበላሁም፤ የንጉሡም መጠጥ ደስ አያሰኘኝም፤ ከወይናቸውም አልጠጣሁም።'),
  ('e95e50ef-8a86-5783-ab92-6f992a00a107', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 13, 46, 'አቤቱ! የአብርሃም አምላክ! ከገባሁ ጀምሮ እስከ ዛሬ ድረስ እኔ ባሪያህ በአንተ እንጂ በእነርሱ ደስ አልተሰኘሁም።'),
  ('be8856a9-9b66-5ac3-a99a-41d58cedacce', '1114968f-f838-55d9-aace-956f8d0a55d2', '1a52d923-99fb-5834-a818-f1940f6654e3', 14, 47, 'አቤቱ ሁሉን የምትችል፥ ተስፋ የቈረጡትን ጸሎት ስማ፤ በእኛ ክፉ ነገር ከሚያደርጉ እጅም አድነን፤ እኔንም ከምፈራው አድነኝ።”'),
  ('18e05237-b6a4-5581-a9b3-1a0823cb6010', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 1, 1, 'ከዚህም በኋላ በሦስተኛው ቀን ጸሎቷን በጨረስች ጊዜ የኀዝን ልብስዋን አወለቀች፤ የክብር ልብስዋንም ለበሰች፤'),
  ('46569f69-05d3-55fb-a5bf-c852d4cdd089', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 2, 2, 'የም ታስፈራም ሆነች፤ ሁሉን የሚመለከት አዳኝ እግዚአብሔርንም ጠራችው።'),
  ('55c9036a-2f6b-51ff-af6c-edea5dc968c7', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 3, 3, 'ሁለቱን ደንገጥሮችዋንም አስከትላ ሄደች፤ ትወዳታለችና ላንዲቱ ትራራላት ነበር፤ ሁለተኛዪቱም ልብስዋን ተሸክማ ትከተላት ነበር። እርስዋ ግን በጌጡ ሁሉ ፈጽማ አጊጣ ነበር፤ ወደ ወዳጆችዋ እንደምትሄድም ፊቷ የሚያበራ ሆነ፤ ልብዋ ግን ሞትን ከመፍራት የተነሣ አዝኖ ነበር።'),
  ('f244038e-a9de-59bb-af29-773c675f08b5', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 4, 6, 'በሩን ሁሉ ገብታ ወደ ንጉሡ ደረሰች፤ እርሱ ግን በመንግሥቱ ዙፋን ላይ ተቀምጦ ነበር።'),
  ('78c04540-0582-541d-a210-e5a01527e10f', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 5, 7, 'ዋጋው ብዙ የሆነ፥ ሁለንተናውም በዕንቍና በወርቅ ያጌጠ የክብር ልብሱን ለብሶ ነበር፤ ፈጽሞም ያስፈራ ነበር። ፊቱም ከክብሩ ጋር ተመልሶ በቍጣ አያት፤ ንግሥቲቱም ፈራች፤ ጠወለገችም፤ ለመውደቅም ተፍገመገመች፤ በፊቷ የምትሄድ የብላቴናዋንም ራስ ተደገፈች።'),
  ('9803e93c-f94d-515d-aff9-7a1de24bfaf7', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 6, 8, 'እግዚአብሔርም የንጉሡን ልቡና ወደ የዋህነት መለሰው፤ ታገሣትም፤ ከዙፋኑም ተንሥቶ ስቦ በአጠገቡ አስቀመጣት፤ በበጎ ቃልም ያባብላት ጀመር፤ እንዲህም አላት፥ “አስቴር ሆይ! ምን ሆንሽ? እኔ ወንድምሽ ነኝ፤ እንደማትሞች እመኚ፤ የአገራችን ሕግ ልዩ ነውና፤”'),
  ('87c28a6a-8e1e-5572-ad0f-72351619706c', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 7, 11, 'የወርቁንም ዘንግ አንሥቶ በአንገቷ ላይ አኖረው፤ እቅፍ አድርጎ ይዞም “ንገሪኝ” አላት።'),
  ('eaa0dfb9-7870-510e-ae72-975c22888eeb', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 8, 13, 'እርስዋም አለች፥ “አንተ ድንቅ ነህና፥ ፊትህም ሞገስን የተመላ ነውና ክብርህን ከመፍራት የተነሣ ጌታዬ እንደ መልአከ እግዚአብሔር ሆነህ ባየሁህ ጊዜ ልቡናዬ ደንገጠብኝ።”'),
  ('0a19b717-f309-5ee4-a9b7-6babd696e182', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 9, 15, 'ስትናገርም ተዝለፍልፋ ወደቀች። ንጉሡም ደነገጠ፤ ሰዎቹም ሁሉ ደነገጡ፤ ያጽናኗትም ጀመር።'),
  ('9946e31c-bac4-5d71-a94c-e06e4727f10a', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 10, 17, 'ንጉሡም፥ “አስቴር ሆይ! ምን ትፈልጊያለሽ? ምንስ ትለምኛለሽ? እስከ መንግሥቴ እኩሌታ እንኳ ቢሆን ጠይቂ፤ ሁሉም ይሰጥሻል” አላት።'),
  ('3c7b65da-307f-5091-afe6-38751d910ad5', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 11, 18, 'አስቴርም፥ “የግብዣ ቀን አለኝ፤ ንጉሡ ቢፈቅድ ወደ አዘጋጀሁለት ግብዣ ከሐማ ጋር ዛሬ ይምጣ” አለች።'),
  ('b2384430-e505-580c-af30-2357cd10f1ab', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 12, 19, 'ንጉሡም፥ “አስቴር እንዳለች ይደረግ ዘንድ ሐማን በፍጥነት ጥሩት” አለ። ንጉሡና ሐማ አስቴር ወዳዘጋጀችው ግብዣ መጡ።'),
  ('b25930fa-33e1-5d3c-abbb-60558c1435a3', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 13, 20, 'ንጉሡም በግብዣ ሳለ አስቴርን፥ “አስቴር ሆይ! የምትሺው ምንድን ነው? ጠይቂ፤ የምትጠይቂው ሁሉ ይደረግልሻል” አላት።'),
  ('04571796-4472-548e-a5b6-5ac8c12d2e20', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 14, 21, 'አስቴርም መልሳ፥ “ልመናዬና የምሻው ነገር ይህ ነው፤'),
  ('14c5be21-bccd-5a77-ae30-ac4a7e715fc1', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'e23209e1-6839-55bf-a4bc-c56673723d10', 15, 22, 'በንጉሡ ዘንድ ሞገስን አግኝቼ እንደ ሆነ ንጉሡና ሐማ ወደማዘጋጅላቸው ግብዣ ነገ ይምጡ፤ ያንም ነገ አደርገዋለሁ” አለች።'),
  ('a4d56323-0d05-57ed-a002-c3d66dcf108d', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'a7e7bca9-dd60-5c1d-a951-75e60ce5bcff', 1, 23, 'ሐማም እጅግ ደስ ብሎት ከንጉሡ ዘንድ ወጣ፤ ነገር ግን አይሁዳዊው መርዶክዮስን በአደባባዩ ባየው ጊዜ እጅግ ተቈጣ።'),
  ('3fdf566b-41c3-5d3e-a53c-c5cc04f99f7e', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'a7e7bca9-dd60-5c1d-a951-75e60ce5bcff', 2, 24, 'ሐማ ግን ወደ ቤቱ ሄደ፤ ወዳጆቹንና ሚስቱን ዞሳራን ጠራ።'),
  ('d21c427c-ea79-55d3-af4f-1c17077235f1', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'a7e7bca9-dd60-5c1d-a951-75e60ce5bcff', 3, 25, 'ንጉሡም ያደረገለትን ሀብቱንና ክብሩን ሁሉ፥ በግዛቱም ላይ ከፍ ከፍ እንዳደረገው አጫወታቸው።'),
  ('85f4c822-178f-5c54-ad46-ff58c6d6767c', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'a7e7bca9-dd60-5c1d-a951-75e60ce5bcff', 4, 26, 'ሐማም፥ “ንግሥቲቱ አስቴር ወዳዘጋጀችው ግብዣ ከእኔ በቀር ከንጉሡ ጋር ማንንም አልጠራችም፤ ደግሞ ነገ ከንጉሡ ጋር ወደ እርስዋ ተጠርቻለሁ።'),
  ('47e2dc36-6d43-5b26-a360-758dc6129f13', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'a7e7bca9-dd60-5c1d-a951-75e60ce5bcff', 5, 27, 'ነገር ግን አይሁዳዊው መርዶክዮስ በንጉሡ በር ተቀምጦ ከአየሁ ይህ ሁሉ ለእኔ ምንም ደስ አያሰኘኝም” አለ።'),
  ('6e5ac309-dfc6-5766-ade4-160e969b1769', '07509f87-2add-5e4c-a2e1-36a62d343eaf', 'a7e7bca9-dd60-5c1d-a951-75e60ce5bcff', 6, 28, 'ሚስቱም ዞሳራና ወዳጆቹም ሁሉ፥ “ቁመቱ አምሳ ክንድ የሆነ ግንድ ይቈረጥ፤ ነገም መርዶክዮስ ይሰቀልበት ዘንድ ለንጉሡ ተናገር፤ ደስ ብሎህም ከንጉሡ ጋር ወደ ግብዣው ግባ” አሉት። ይህም ነገር ሐማን ደስ አሰኘው፤ ግንዱንም አዘጋጀ።'),
  ('b93b6bb2-66a8-5866-a93f-ffd8ff265fef', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 1, 1, 'በዚያም ሌሊት እግዚአብሔር እንቅልፍን ከንጉሡ አጠፋ፤ የዘመኑንም ታሪክ መጽሐፍ ያመጣና ያነብለት ዘንድ ጸሓፊውን አዘዘ።'),
  ('406157b5-4a07-5663-a9d0-5bcc73d0bebd', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 2, 2, 'ደጁንም ከሚጠብቁት ከንጉሡ ጃንደረቦች ሁለቱ ንጉሥ አርጤክስስን ይገድሉ ዘንድ እንደ ፈለጉና መርዶክዮስም ሰምቶ እንደ ነገረው ተጽፎ ተገኘ።'),
  ('a548a586-29c9-54f5-a0df-53a24dbdc8d3', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 3, 3, 'ንጉሡም “ስለዚህ ነገር ለመርዶክዮስ ምን ክብርና ደግነት አደረግንለት?” አለ። ንጉሡንም የሚያገለግሉ ብላቴኖች “ለመርዶክዮስ ምንም አላደረግህለትም” አሉት።'),
  ('25130ce8-f24c-530d-a1ba-171968f19fc7', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 4, 4, 'ንጉሡም የመርዶክዮስን ደግነት ሲናገር እነሆ ሐማ ወደ አደባባይ ደረሰ። ንጉሡም፥ “በአደባባይ ማን አለ?” አለ። ሐማም ባዘጋጀው ግንድ ላይ መርዶክዮስን ለማሰቀል ለንጉሡ ይናገር ዘንድ ወደ ውስጥ ገባ።'),
  ('a248905f-437e-556b-a4e2-170f5ebd6e48', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 5, 5, 'የንጉሡም ብላቴኖች፥ “እነሆ ሐማ በአደባባይ ቆሞአል” አሉት። ንጉሡም “ጥሩት” አለ።'),
  ('6b15a4fd-3041-53ef-ad3f-3827bc1b6f8f', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 6, 6, 'ንጉሡም ለሐማ አለው፥ “እኔ ላከብረው ለምወድደው ሰው ምን ላድርግለት?” ሐማም በልቡ፥ “ንጉሡ ከእኔ ይልቅ ማንን ያከብር ዘንድ ይወድዳል?” አለ።'),
  ('b293fdca-582c-52af-ace9-bceaaa63e643', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 7, 7, 'ንጉሡንም እንዲህ አለው፥ “ንጉሡ ያከብረው ዘንድ ለሚወድደው ሰው እንዲህ ይደረግ።'),
  ('96dbb452-67b2-52ce-ac37-54abff4513e3', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 8, 8, 'የንጉሡ ብላቴኖች ንጉሡ የሚለብሰውን የክብር ልብስ፥ ንጉሡም የሚቀመጥበትን ፈረስ ያምጡለት።'),
  ('e6b48dc7-5b20-5713-a063-be05894436aa', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 9, 9, 'ልብሱንና ፈረሱንም ከንጉሡ አዛውንት በዋነኛው እጅ ያስረክቡት፤ ንጉሡም ያከብረው ዘንድ የሚወድደውን ሰው ያልብሱት፤ በፈረሱም ላይ አስቀምጠው በከተማዪቱ አደባባይ ያሳልፉት፤ በፊቱም ንጉሡ ያከብረው ዘንድ ለሚወድደው ሰው እንዲህ ይደረግለታል ተብሎ ዐዋጅ ይነገር።”'),
  ('e2f02d94-f22c-5c71-a9b2-f7fe5b0690c5', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 10, 10, 'ንጉሡም ሐማን፥ “መልካም ብለሃል፤ እንደ ተናገርኸውም ልብሱንና ፈረሱን ውሰድ፤ በንጉሡም በር ለሚቀመጠው ለአይሁዳዊው ለመርዶክዮስ እንዲሁ አድርግለት፤ ከተናገርኸው ሁሉ ምንም አታስቀር” አለው።'),
  ('dd873f9c-1752-59a3-a944-df3345378bee', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 11, 11, 'ሐማም ልብሱንና ፈረሱን ወሰደ፤ መርዶክዮስንም አለበሰው፤ በፈረሱም ላይ አስቀመጠው፤ በከተማዪቱም አደባባይ በፊቱ አሳለፈው። በፊቱም “ንጉሡ ያከብረው ዘንድ ለሚወድደው ሰው እንዲህ ይደረግለታል” ብሎ ዐዋጅ ነገረ።'),
  ('7d5cf100-a1aa-5717-a5f6-630eb1f6f26b', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 12, 12, 'ከዚህም በኋላ መርዶክዮስ ወደ ንጉሡ ዐደባባይ ተመለሰ። ሐማ ግን አዝኖና ራሱንም ተከናንቦ ወደ ቤቱ ሄደ።'),
  ('3b109b60-d117-5e82-a8a0-d627bd04808b', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 13, 13, 'ሐማም ለሚስቱ ለዞሳራና ለወዳጆቹ ሁሉ ያገኘውን ሁሉ አጫወታቸው። ወዳጆቹና ሚስቱM “በፊቱ መውደቅ የጀመርህለት መርዶክዮስ ከአይሁድ ወገን የሆነ እንደ ሆነ በፊቱ ፈጽመህ ትወድቃለህ እንጂ አታሸንፈውም፤ ሕያው እግዚአብሔር ከእርሱ ጋር ነውና” አሉት።'),
  ('0e48bba1-d700-5c60-a624-b0f15895140a', '48fef922-3a14-5069-afb0-df995481c837', '2d1edd0a-31da-5b4c-aae5-adce721145d3', 14, 14, 'እነርሱም ሲናገሩት ሳሉ እነሆ የንጉሡ ጃንደረቦች መጡ፤ አስቴርም ወዳዘጋጀችው ግብዣ ይመጣ ዘንድ ሐማን አስቸኰሉት።'),
  ('9750657b-a4c4-57a1-af8d-95541f292ce4', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 1, 1, 'ንጉሡና ሐማም ከንግሥቲቱ ከአስቴር ጋር ይጋበዙ ዘንድ ገቡ።'),
  ('5d087c8f-4c4a-58c2-a84d-83a4ff3b85e5', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 2, 2, 'በሁለተኛውም ቀን ንጉሡ በወይኑ ጠጅ ግብዣ ሳለ አስቴርን፥ “ንግሥት አስቴር ሆይ! ምን ሁነሻል? የምትለምኚኝ ምንድን ነው? የምትሺውስ ምንድን ነው? እስከ መንግሥቴ እኩሌታ እንኳ ቢሆን ይደረግልሻል” አላት።'),
  ('823bce56-d6e4-5aeb-a774-9f3b7207d853', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 3, 3, 'ንግሥቲቱም አስቴር መልሳ አለች፥ “ንጉሥ ሆይ! በአንተ ዘንድ ሞገስን አግኝቼ እንደ ሆነ ሕይወቴ በልመናዬ፥ ሕዝቤም በመሻቴ ይሰጠኝ።'),
  ('461b4620-79e2-5511-a71e-b7feb49c70aa', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 4, 4, 'እኔና ሕዝቤ ለመጥፋት፥ ለመገደልና ለመደምሰስም ተሸጠናልና። እኛና ልጆቻችን ባሪያዎችህ ልንሆን ተሸጠን ቢሆን ኑሮ ዝም ባልሁ ነበር፤ ጠላት ወደ ንጉሡ አደባባይ መግባት አይገባውም ነበርና።”'),
  ('759dfc93-cad4-5bbd-abb0-38e4c5cc466b', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 5, 5, 'ንጉሡም፥ “ይህን ያደርግ ዘንድ የደፈረ ማን ነው?” ብሎ ተናገራት።'),
  ('1fbd90fb-6491-5fdd-a2cb-40293e5d348c', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 6, 6, 'አስቴርም፥ “ያ ጠላትና ባላጋራ ሰው ይህ ክፉው ሐማ ነው” አለች። ሐማም በሰማ ጊዜ በንጉሡና በንግሥቲቱ ፊት ደነገጠ።'),
  ('bf10ebaa-23e4-5282-aa85-018d1c69b018', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 7, 7, 'ንጉሡም የወይን ጠጅ ከመጠጣቱ ተነሣ፤ ወደ አታክልት ቦታ ውስጥም ሄደ። ሐማም ክፉ ነገር እንደ ደረሰበት አይቶአልና ንግሥቲቱን ይለማመጥ ጀመር።'),
  ('f09afeee-de84-59fb-afe2-9836b4c5902d', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 8, 8, 'ንጉሡም ከአታክልቱ ቦታ ተመለሰ፤ ሐማም ንግሥቲቱን እየተለማመጠ በአልጋው ላይ ወድቆ ነበር። ንጉሡም ደግሞ፥ “በቤቴ ሚስቴን ይጋፋታልን?” አለ። ሐማም ይህን ቃል በሰማ ጊዜ ፊቱ ጠቈረ።'),
  ('eff5e5a6-cf9b-5138-a90f-71aa4b3d995c', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 9, 9, 'በንጉሡም ፊት ካሉት ጃንደረቦች አንዱ ቡጋታን፦ “እነሆ ሐማ ለንጉሡ በጎ ለተናገረው ለመርዶክዮስ ያዘጋጀው ርዝመቱ አምሳ ክንድ የሆነ ግንድ በሐማ ቤት ተተክሎአል” አለ። ንጉሡም በእርሱ ላይ ስቀሉት አለ።'),
  ('c8dacd53-2bff-548e-a66c-4b362e3f233f', '274ab8d9-97fe-56e8-acd3-626fd6d1f117', '3d8b4f7a-1e35-566c-af54-cc8a59c7d223', 10, 10, 'ሐማንም ለመርዶክዮስ ባዘጋጀው ግንድ ላይ ሰቀሉት፤ በዚያም ጊዜ የንጉሡ ቍጣ በረደ።'),
  ('380c0630-4e3e-5bcf-a039-fed956f78f05', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 1, 1, 'በዚያም ቀን ንጉሡ አርጤክስስ የጠላት የሐማን ንብረት ሁሉ ለንግሥቲቱ ለአስቴር ሰጠ። ንጉሡም መርዶክዮስን ጠራው፤ አስቴር በቤቱ እንዳደገች ነግራው ነበርና።'),
  ('d6e2a097-fcd2-534a-a45d-f4363cc4381b', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 2, 2, 'ንጉሡም ከሐማ ያወለቀውን ቀለበቱን አወጣ፤ ለመርዶክዮስም ሰጠው። አስቴርም በሐማ ንብረት ሁሉ ላይ መርዶክዮስን ሾመችው።'),
  ('2f27868e-c314-5038-a03f-47c9c79577c4', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 3, 3, 'አስቴርም እንደ ገና ለንጉሡ ነገረችው፤ በእግሩም ላይ ወድቃ የሐማን ክፋትና በአይሁድ ላይ የተተነኰለውን ተንኰል ይሽር ዘንድ ለመነችው።'),
  ('61a9aa7a-875b-5853-a45f-89c2ae0fd358', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 4, 4, 'ንጉሡም የወርቁን ዘንግ ለአስቴር ዘረጋላት፤ አስቴርም ተነሥታ በንጉሡ ፊት ቆመች።'),
  ('2531185c-b43a-52cf-a874-483fc1733946', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 5, 5, 'እንዲህም አለች፥ “ንጉሥ ሆይ፥ ደስ ቢያሰኝህ በፊትህም ሞገስ አግኝቼ እንደ ሆነ በመንግሥትህ ሁሉ ያሉትን አይሁድ ለማጥፋት ሐማ የጻፋቸው ደብዳቤዎች ሁሉ ይገለበጡ ዘንድ ላክ።'),
  ('3c8405d8-817f-592c-ac5c-677fd0dfdf38', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 6, 6, 'እኔ በሕዝቤ ላይ የሚወርደውን ክፉ ነገር አይ ዘንድ እንዴት እችላለሁ? ወይስ ከዘመዶች ጥፋት በኋላ እኖር ዘንድ እንዴት እችላለሁ?”'),
  ('77d6472a-b7d8-577d-a8b1-098f95a7107b', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 7, 7, 'ንጉሡም ንግሥቲቱን አስቴርን አላት፥ “እነሆ የሐማን ገንዘብ ሁሉ ፈጽሜ ሰጠሁሽ፤ እርሱንም እጆቹን በአይሁድ ላይ ስለዘረጋ በግንድ ላይ ሰቀልሁት፤ እንግዲህ ምን ትፈልጊያለሽ?'),
  ('f26b7bcf-3ac8-5dc6-a5bd-1019a83f583c', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 8, 8, 'በንጉሡም ስም የተጻፈውንና በንጉሡ ቀለበት የታተመውን እንቢ የሚል የለምና እናንተ ደግሞ ደስ የሚያሰኛችሁን በእኔ ስም ጻፉ፤ በቀለበቴም አትሙ።”'),
  ('f20d34ac-a067-5fae-a100-785577e34deb', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 9, 9, 'በዚያም ዓመት ኔሳን በተባለው በመጀመሪያው ወር ከወሩም በሃያ ሦስተኛው ቀን የንጉሡ ጸሓፊዎች ተጠሩ፤ ንጉሡም እንዳዘዘው ሁሉ ከሕንድ ጀምሮ እስከ ኢትዮጵያ ድረስ በመቶ ሃያ ሰባቱ ሀገሮች ላሉ ሹሞችና አለቆች፥ አዛውንትም፥ ለእያንዳንዱም ሀገር እንደ ጽሕፈቱ፥ ለእያንዳንዱም ሕዝብ እንደ ቋንቋው፥ ለአይሁድም እንደ ጽሕፈታቸውና እንደ ቋንቋቸው ተጻፈ።'),
  ('6755865a-6de7-58e3-a756-2867461781a2', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 10, 10, 'በንጉሡም በአርጤክስስ ስም ጻፉ፤ በንጉሡም ቀለበት አትመው ደብዳቤውን በመልእክተኞች ላኩ።'),
  ('ad2de3cf-1c96-5e21-a5c8-b8b021d878bd', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 11, 11, 'በከተሞች ሁሉ እንደ ሕጋቸው ያደርጉ ዘንድ፥ እርስ በርሳቸውም ይረዳዱ ዘንድ ጠላቶቻቸውንና የሚነሡባቸውን ሁሉ እንደ ወደዱ ይቋቋሙ ዘንድ አዘዛቸው።'),
  ('8c584952-418b-50ef-aa0a-488caa08c7e2', '82987cab-b06d-5279-aa53-5a87fcf013e5', '5933a5ef-8c7a-50ff-a5ce-8b743e49a03d', 12, 12, 'ይህም አዳር በሚባለው በዐሥራ ሁለተኛው ወር በዐሥራ ሦስተኛው ቀን በንጉሡ በአርጤክስስ ሀገሮች ሁሉ በአንድ ቀን እንዲሆን ነው።'),
  ('1c419142-ba91-5e7d-ac6c-b82dbc8f408b', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 1, 13, 'የዐዋጁም ደብዳቤ ግልባጭ የሚከተለው ነው።'),
  ('fe92109b-5260-55a7-a17b-8b5ff8ca30ee', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 2, 14, 'በቸርነትና ሹመትን ፈጥኖ በመስጠት ከሚጠቅሙአቸው ክብርን ያገኙ ብዙዎች ትዕቢትን አበዙ።'),
  ('f237ad64-7c55-5427-a274-43c6a58b01eb', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 3, 15, 'ክፉ የሚያደርጉትም ለእኛ በሚገዙት ላይ ብቻ አይደለም፤ ነገር ግን ጥጋባቸውን መታገሥ ባለመቻላቸው የሚጠቅሙአቸውን ይተናኰሉ ዘንድ ያስባሉ።'),
  ('73be39ff-64dd-56b6-a9c5-e3dd18ea73ba', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 4, 16, 'የሰውን ምስጋና የሚክዱ ብቻ አይደሉም፤ ዳግመኛም አዲሶች ባለጸጎች እንደ መሆናቸው በመታበይ ራሳቸውን ከፍ ያደርጋሉ። ሁልጊዜም ሁሉን ከሚመለከት፥ ኀጢአትንም ከሚጠላ ከእግዚአብሔር ፍርድ የሚያመልጡ ይመስላቸዋል።'),
  ('97e387e9-2cb7-58c7-a370-6f43832e4939', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 5, 17, 'ነገር ግን ብዙ ጊዜ የሚገዙልን በመስማማት ይገዙልንና ያገለግሉን ዘንድ የታመናቸው የተዘጋጁ እነዚያ ሰዎች ንጹሕ ደምን በማፍሰስ አንድ ሆኑ፤'),
  ('275338e0-e6b3-501b-a4fb-b8dc9e946d11', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 6, 18, 'ሐሰትንም በመምከር በየውሀትና በፀጥታ የምትኖር መንግሥትን አታለው የሚያስጨንቅ መከራን መከሩባቸው።'),
  ('ff036398-6b10-5a0f-a14d-0fd35be9405d', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 7, 19, 'ነገር ግን በማሰብ ይቀራል፤ ይኸውም ከእኛ አስቀድሞ ከነበሩ ሰዎች ይልቅ እንድናበልጥ አይደለም፤ ሕጉን እንደ ተቀበልነው እንዲሁ ጸንተን እንኖራለን፤።'),
  ('edbe1d71-51c6-5e77-a801-b4024e3f3b7b', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 8, 20, 'ነገር ግን ከዚህ በኋላ ያለ ሕግ የተደረገውን ነገር እንመረምራለን፤ በሚገባ መፍረድ የማይችሉ፥ የማይገባቸውን ክብር አግኝተዋልና።'),
  ('db87904e-65ea-5153-a3bc-2047f5be95f0', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 9, 21, 'ከዚህም በኋላ መንግሥታችን ያለ ሁከት ጸንታ የምትኖርበትን፥ የሕዝቡም ኑሮ የሚቃናበትን አስበን፥ የተገለጠውንም ሁልጊዜ በየዋህነት እንፈርዳለን።'),
  ('67444e8a-3e02-5609-a5da-5e032642710e', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 10, 22, 'መቄዶናዊ የሐመዳቱ ልጅ ሐማ ግን ከእውነት ነገር የወጣና የፋርስ ደም የሌለው እንደ መሆኑ ከእኛ ቸርነት ርቆአል፤ በእኛ ዘንድም ሲኖር ባዕድ ሁኖአል።'),
  ('3e2b40bd-1746-588c-ad54-755640a63bb2', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 11, 23, 'እርሱም በሕዝቡ ላይ ሁሉ ሹመትንና ባለሟልነትን አገኘ። አባታችን እስክንለውና የመንግሥታችንም ዙፋን ሁለተኛ እስክንለው የወደደውን ሹመት አገኘ።'),
  ('2076f870-5548-5449-ae77-95ce6bf3176c', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 12, 24, 'ዳግመኛም ይህ አልበቃውም፤ ነገር ግን ታብዮ ከመንግሥታችን ያወጣን ዘንድ፥ ሰውነታችንንም ወደ ጥፋት ይወስድ ዘንድ አሰበ።'),
  ('86d860a4-5402-52ea-a17e-e4a5403c7d8b', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 13, 25, 'በሁሉ የሚጠቅመንንና የሚያድነንን፥ የሚያገለግለንንም መርዶክዮስን፥ ያለ ነቀፋ የመንግሥታችን ተባባሪ የምትሆን አስቴርንም በብዙ ተንኰል፥ ነገርንም በማሳመር ከወገኖቻቸው ሁሉ ጋር ያጠፋቸው ዘንድ ለመነ።'),
  ('7e6745fd-3219-5819-a977-dbb2245d28ec', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 14, 26, 'ስለዚህም ነገር በየዋህነት እንኖራለንና የፋርስን መንግሥት አገኘን፤ እሱ ግን ወደ መቄዶን ያዛውረው ዘንድ አሰበ።'),
  ('c7c7ab02-f5d2-5ca9-ab3e-62e6b3aac89e', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 15, 27, '“እኛ ግን ያጠፋቸው ዘንድ የፈለጋቸውን አይሁድን በክፋት እንዳይደሉ፥ ነገር ግን በእውነተኛ ሕጋቸው እንደሚኖሩ አገኘናቸው።'),
  ('9cdfcbc8-5048-5ac8-a890-c76601ae1d60', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 16, 28, 'በእውነት ለእኛና ከእኛ በፊት ለነበሩ እንደ ልባችን ቅንነት መንግሥትን ያዘጋጀልን የልዑሉና የታላቁ የሕያው እግዚአብሔር ልጆች ናቸው።'),
  ('a4977e4f-c20d-5abe-ae00-0a5b5c0d7eda', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 17, 29, 'ነገር ግን የሐመዳቱ ልጅ የሆነ የሐማን ትእዛዝ፥ የላከውንም ደብዳቤ ቃል ባትሰሙ መልካም ነገር ታደርጋላችሁ።'),
  ('f9ddddd1-ac05-5f05-aba7-c5004eca8ee2', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 18, 30, 'እርሱ ራሱ ይህን ነገር አስቦበታልና፥ ሁሉን የሚገዛ እግዚአብሔር ፈጥኖ ፍዳውን ስለ ከፈለው ከወገኖቹ ሁሉ ጋር በሱሳ ከተማ አደባባይ ተሰቀለ።'),
  ('bb7c0981-cee6-5c80-afe3-f99449c83564', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 19, 31, 'ይህችንም ደብዳቤ በግልጥ ዘርግታችሁ በቦታው ሁሉ አሳዩአት፤ አይሁድንም በሕጋቸው ጸንተው ይኖሩ ዘንድ ተዉአቸው።'),
  ('122bd955-60be-5e10-a9cb-3022e1f96bed', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 20, 32, 'ዐሥራ ሁለተኛው ወር አዳር በባተ በዐሥራ ሦስተኛው ቀን ከዚያች ጀምሮ እስከዚች ሰዓት ድረስ ቀድሞ በመከራቸው ወራት ከአስጨነቋቸው ራሳቸውን ይከላከሉ ዘንድ ርዱአቸው።'),
  ('3c0232b1-31f4-5db9-af89-fe7ce7c0df48', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 21, 33, 'ሁሉን የሚችል እግዚአብሔርም በጥፋታቸው ፋንታ ለእነዚህ ለተመረጡ ሕዝብ ደስታን አደረገላቸው።'),
  ('c3063723-8d41-5d9c-a65f-6e94a2e2f4fd', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 22, 34, 'እናንተም በተጠሩት በበዓሎቻችሁ በታወቀ ቀን እንደዚሁ አድርጉ።'),
  ('f386cdf2-84ef-5081-a248-6cf9e14d404b', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 23, 35, 'እነሆ፥ ከዚህ በኋላም ለእኛና ለፋርስ ሰዎች፥ በጎ ነገርን ለሚያደርጉ ሕይወት ይሆንላቸዋል፤ እኛን ይወነጅሉ ዘንድ ለሚወድዱ ግን የጥፋታቸው መታሰቢያ ይሆናል።'),
  ('0a6b4194-ea28-5b7a-aeda-edaa079637be', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 24, 36, 'ሀገሩ ሁሉ፥ ወይም ከተማው በሁሉም ቦታ እንዲህ ያላደረገ በጦርና በእሳት በመዓት ይጠፋል፤ ጥፋትም የሚሆነው በሰዎች ብቻ አይደለም፤ ነገር ግን በአውሬዎችና በዎፎችም ላይ ይሆናል።”'),
  ('70a9cfd6-16b6-5ec9-ab6b-515254aa4243', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 25, 37, 'አይሁድም ጠላቶቻቸውን እንዲበቀሉ በዚያ ቀን ይዘጋጁ ዘንድ የደብዳቤው ቅጂ በግዛቱ ሁሉ በግልጥ ቦታ ተዘርግቶ እንዲታይ ተደረገ።'),
  ('b0058107-58d1-57d6-ab1a-ee95a3356762', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 26, 38, 'ፈረሰኞችም የንጉሡን ትእዛዝ ይፈጽሙ ዘንድ ቸኩለው ወጡ። ዐዋጁም በሱሳ ከተማ ተነገረ።'),
  ('3579a841-974c-52a3-aff2-53348e8f7256', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 27, 39, 'መርዶክዮስም ልብሰ መንግሥት ለብሶ፥ የወርቅ አክሊልም ደፍቶ፥ ከሐምራዊ ግምጃ የተሠራ መጐናጸፊያም ተጐናጽፎ ወጣ፤ በሱሳ ከተማ የነበሩትም አይተው ደስ አላቸው።'),
  ('ee54f1b1-8714-549b-a8e6-65c4f11de238', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 28, 40, 'ለአይሁድም ብርሃንና ደስታ ሆነ።'),
  ('e51e7d9c-a08e-50d5-af8b-1b48945fd596', '82987cab-b06d-5279-aa53-5a87fcf013e5', 'a34ee731-b9da-5604-a82d-9051c81087aa', 29, 41, 'ትእዛዙም በታወጀበት፥ ደብዳቤውም በተገኘበት አውራጃና ከተማ ሁሉ ለአይሁድ ደስታና ተድላ፥ የግብዣም ቀን፥ መልካምም ቀን ሆነ። ከአሕዛብም ብዙዎች አይሁድን ስለ ፈሩ ተገዝረው አይሁድ ሆኑ።'),
  ('b47f0071-832f-5eab-a72f-7e9033af4e7f', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 1, 1, 'አዳር በሚባለውም በዐሥራ ሁለተኛው ወር ከወሩም በዐሥራ ሦስተኛው ቀን ንጉሡ የጻፈው ደብዳቤ ደረሰ።'),
  ('57d80fc1-e955-54ae-aa46-e716db0fc24f', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 2, 2, 'በዚያችም ቀን የአይሁድ ጠላቶች ጠፉ። ስለፈሩአቸውም አይሁድን የሚቃወም ሰው አልነበረም።'),
  ('6bd6c3c4-072b-5cda-a528-b1045f740267', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 3, 3, 'መርዶክዮስን መፍራትም በላያቸው ስለ ወደቀ በየሀገሩ የነበሩ አዛውንትና ሹሞች፥ አለቆችም፥ የንጉሡም ጸሓፊዎች ሁሉ አይሁድን አከበሩ።'),
  ('d675ced2-b853-5008-ac58-f9e1165b93d9', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 4, 4, 'መርዶክዮስ በመንግሥቱ ሁሉ ይከበር ዘንድ የንጉሡ ደብዳቤ ያስገድድ ነበርና፤'),
  ('23210b1c-179b-578b-acb1-f41da6097d32', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 5, 5, 'አይሁድም ጠላቶቻቸውን ሁሉ በሰይፍ እየመቱ ገደሉአቸው፤ አጠፉአቸውም፤ በሚጠሉአቸውም ላይ እንደ ወደዱ አደረጉባቸው።'),
  ('3d0076bc-d723-5cc8-a891-74592a20bd47', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 6, 6, 'አይሁድም በሱሳ ከተማ አምስት መቶ ያህል ሰዎችን ገደሉ፤ አጠፉም።'),
  ('0577e49d-7f81-5653-a85a-1c7bc7eeaae2', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 7, 7, 'ፈርሰኔስ፥ ደልፎን፥ ፋስጋ፤'),
  ('daeffecf-acfb-53d8-ac4a-f581f9a0482f', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 8, 8, 'ፋርዳታ፥ በርያ፥ ሰርበካ፤'),
  ('49881c5f-d99e-5764-a3c1-2ff3550adeaa', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 9, 9, 'መርመሲማ፥ ሩፋዮስ፥ አርሳዮስ፥ ዛቡታዮስ የሚባሉትን፥'),
  ('1ebd3a1c-bad8-5ae9-a883-e7140db17a6b', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 10, 10, 'የቡጊያዊው የሐመዳቱን ልጅ የአይሁድን ጠላት የሐማን ዐሥሩን ልጆች ገደሉ፤ በዚያም ቀን ገንዘባቸውን ሁሉ ዘረፉ።'),
  ('6dec7bb2-6050-5b15-af42-06bed888dcbe', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 11, 11, 'በሱሳ ከተማ የተገደሉት ሰዎች ቍጥርም ወደ ንጉሡ ተላለፈ።'),
  ('e3809cb8-5855-5317-a2bb-f3da3e0ffa10', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 12, 12, 'ንጉሡም ንግሥቲቱን አስቴርን፥ “አይሁድ በሱሳ ከተማ አምስት መቶ ሰዎችን ገደሉ፤ አጠፉአቸውም፤ በቀሩትስ በንጉሡ ሀገሮች እንዴት አድርገው ይሆን? እንግዲህስ ይደረግልሽ ዘንድ የምትፈልጊው ምንድን ነው?” አላት።'),
  ('1a04eab9-c403-5376-a025-47a8f5b05434', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 13, 13, 'አስቴርም፥ “አይሁድ ነገ ደግሞ እንዲሁ እንዲያደርጉ፥ ዐሥሩንም የሐማ ልጆች በግንድ ላይ እንዲሰቅሉ ይፈቀድላቸው፤” አለች።'),
  ('704ae8cb-fcf9-5a6d-a99a-23123e53c3a5', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 14, 14, 'ንጉሡም ይህ ይደረግ ዘንድ ፈቀደ፤ በከተማ ለሚኖሩ አይሁድም የሐማን ልጆች አስከሬን ይሰቅሉ ዘንድ አዘዘ።'),
  ('a5e06f82-738e-5786-aa41-f283c1746d2d', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 15, 15, 'አይሁድም አዳር በሚባለው ወር በዐሥራ አራተኛው ቀን በሱሳ ተሰብስበው ሦስት መቶ ያህል ሰዎችን ገደሉ፤ ነገር ግን ንብረታቸውን አልዘረፉም።'),
  ('1c224f55-5c3c-5785-a35b-cbd4a728ff1e', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 16, 16, 'የቀሩትም በንጉሡ ሀገር ያሉ አይሁድ ተሰብስበው እርስ በርሳቸው ተረዳዱ፤ ከጠላቶቻቸውም ዐረፉ፤ ከሚጠሉአቸውም አዳር በሚባለው ወር በዐሥራ ሦስተኛው ቀን ዐሥራ አምስት ሺህ ገደሉ፤ ነገር ግን የዘረፉት የለም።'),
  ('4a6e1bb5-39d6-5060-a353-5edb562726e8', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 17, 17, 'በዚያም ወር በዐሥራ አራተኛው ቀን ዐረፉ፤ ያችንም ቀን ከግብዣና ከደስታም ጋር የዕረፍት ቀን አደረጓት።'),
  ('2250ae0d-8106-5ee8-a720-f20ba6e2f263', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 18, 18, 'በሱሳ ከተማ የነበሩት አይሁድ ግን በዐሥራ አራተኛው ቀን ተሰብስበው ዐረፉ፤ በዐሥራ አምስተኛውም ቀን በዓልና ደስታ አደረጉ።'),
  ('1d059efc-9146-5891-aa1f-194815f0f122', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', 'a85ff606-7d27-552e-adbe-79a3fac57bc4', 19, 19, 'ስለዚህ በገጠር መንደሮች ተበታትነው የሚኖሩ አይሁድ አዳር በሚባለው ወር ዐሥራ አራተኛውን ቀን የደስታና የመጠጥ፥ የመልካምም ቀን፥ እርስ በርሳቸውም ስጦታ የሚሰጣጡበት ቀን ያደርጉታል።'),
  ('5747fc20-1cc3-54e2-a068-ef014a9c17a3', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 1, 20, 'መርዶክዮስም ይህን ነገር በመጽሐፍ ጻፈው፤ በንጉሡም በአርጤክስስ ሀገሮች ሁሉ፥ በሩቅም በቅርብም ላሉት ሁሉ ላከው።'),
  ('d91bd0e2-a3d1-5d99-a449-5473a9ac19fd', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 2, 21, 'በየዓመቱም አዳር በሚባለው ወር ዐሥራ አራተኛውንና ዐሥራ አምስተኛውን ቀን የደስታ ቀኖች አድርገው ይጠብቋቸው ዘንድ፥'),
  ('a8aac9af-de76-52f2-a196-b1b611cc4d74', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 3, 22, 'በእነዚያ ወራት አይሁድ ከጠላቶቻቸው ዕረፍትን አግኝተዋልና፥ አዳር የተባለውም ወር ከኀዘን ወደ ደስታ፥ ከልቅሶም ወደ መልካም ቀን የተለወጠበት የግብዣና የደስታም ቀን፥ ለወዳጆቻቸውና ለድኆችም ስጦታ የሚልኩበት ቀን ነውና።'),
  ('61b59d96-8ca0-523e-a09b-651bd4e04312', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 4, 23, 'አይሁድም መርዶክዮስ እንደ ጻፈላቸው ተቀበሉት፤'),
  ('93e26510-7e28-5a99-a8eb-3f9b101677ff', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 5, 24, 'መቄዶንያዊው የሐመዳቱ ልጅ ሐማም አይሁድን በተንኰል ያጠፋ ዘንድ ተዋግቶአቸው ነበር፤ ዐዋጅም ዐውጆ ነበር፤ ዕጣም ጥሎ ነበር።'),
  ('58ee86bc-aaf8-588a-a9dd-c651b8503618', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 6, 25, 'እንዲሁም ወደ ንጉሡ ገብቶ መርዶክዮስን ይሰቅለው ዘንድ ጠይቆ ነበር፤ ነገር ግን በአይሁድ ላይ የተተነኰለው ክፉ ተንኰል በራሱ ላይ ተመለሰ። እርሱም ልጆቹም ተሰቀሉ።'),
  ('e38bf399-aa8c-5bb8-a36e-6e8e50cc0174', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 7, 26, 'ስለዚህም እነዚህ ቀኖች ዕጣ ስለ ተጣለባቸው ፉሪም ተባሉ። በዚችም ደብዳቤ ስለ ተጻፈው ቃል ሁሉ፥ በውስጥዋም ስለ ተገኘውና ስላገኙአቸውም ነገሮች ሁሉ በቋንቋቸው ፉሪም ይሏቸዋል።'),
  ('2b1a446a-fe99-54a1-a397-5897eaf72863', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 8, 27, 'አይሁድም ለራሳቸው፥ ለዘራቸውና ከእነርሱ ጋር አንድ ለሚሆኑ ሁሉ ከዚህ ሥርዐት እንዳይወጡ የተጻፈውን ተቀበሉ። እነዚህም ቀኖች በየትውልዳቸውና በየወገናቸው፥ በየሀገራቸውም፥ በየከተማቸውም ለዘለዓለም የታሰቡና የተከበሩ ይሆናሉ።'),
  ('62ffe084-c936-5638-a4cf-78afd699c2ec', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 9, 28, 'እነዚህም የፉሪም ቀኖች ሁልጊዜ ይከበራሉ፤ መታሰቢያቸውም በትውልድ ሁሉ አይደመሰስም።'),
  ('5104b5ab-e689-5fc3-a202-4664af5dd499', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 10, 29, 'የአሚናዳብም ልጅ ንግሥቲቱ አስቴርና አይሁዳዊው መርዶክዮስ ያደረጉትን ሁሉ ጻፉ። የፉሪምንም ደብዳቤ አጸኑ።'),
  ('7dd32c74-2fdf-5e14-add5-fefc4942bd87', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 11, 30, 'ደብዳቤዎቹንም በአርጤክስስ መንግሥት በመቶ ሃያ ሰባቱ ሀገሮች ወዳሉ አይሁድ ሁሉ በሰላምና በእውነት ቃል ላኩ።'),
  ('a3d3d5a8-c17c-565c-a640-3856bb9eae35', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 12, 31, 'እነዚህንም የፉሪም ቀኖች መርዶክዮስና ንግሥቲቱ አስቴር ለራሳቸው የጾም ቀን አደረጓቸው፤ በሕይወታቸውና በምክራቸውም ማሉ።'),
  ('1719edb1-ec84-541e-ada5-313f600c646e', 'e68390cb-ef69-5047-a190-b795fd3f3fbc', '1d9b36cb-a22b-5689-ad16-6d6b5e8d8b1e', 13, 32, 'አስቴርም ይህን ነገር በትእዛዝ አጸናችው፤ ለመታሰቢያም ተጻፈ።'),
  ('77e4b2b1-747d-5b99-ac0c-d53e3efff611', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 1, 1, 'ንጉሡም አርጤክስስ በመንግሥቱ በምድርና በባሕር ላይ ግብር ጣለ።'),
  ('8dd2a051-76ae-5880-ab22-1da7977d4d01', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 2, 2, 'የኀይሉና የብርታቱ፥ የሀብቱና የመንግሥቱ ክብር እነሆ በፋርስና በሜዶን ነገሥታት ታሪክ መጽሐፍ ለመታሰቢያ ተጻፈ።'),
  ('da48082d-aab2-52ef-a739-13f89af9c85e', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 3, 3, 'አይሁዳዊውም መርዶክዮስ ለንጉሡ ለአርጤክስስ በማዕረግ ሁለተኛ ነበረ፤ በመንግሥቱም ታላቅ ሰው ነበረ፤ በአይሁድም የከበረ ነበረ፤ በወንድሞችም ዘንድ የተወደደ፥ ለሕዝቡም ሁሉ መልካምን የሚያደርግ ነበረ።'),
  ('a406be20-dba1-5189-a470-2447dd1e2081', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 4, 4, 'መርዶክዮስም፥ “ይህ ነገር በእግዚአብሔር ፈቃድ ተደረገ።'),
  ('d47d1d58-3a74-5a3a-aaa7-f454440762ea', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 5, 5, 'የዚያ ሕልም ጊዜው አላለፈምና ስለዚህ ነገር ያየሁት የሕልሜን ነገር አሰብሁ” አለ።'),
  ('3c6a87f6-4332-5c3b-ad56-1b9d5263e510', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 6, 6, 'ፀሐይና ብርሃን የወጣባት፥ ብዙው ውኃም የተገኘባት ወንዝ የሆነች ያች ትንሿ የውኃ ምንጭ ንጉሥ ያገባት፥ ንግሥትም ያደረጋት አስቴር ናት።'),
  ('5e1d18bd-c7fa-538a-abe5-daa7c59f5d5d', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 7, 7, 'እነዚያ ሁለቱ ዘንዶዎችም ሐማና እኔ ነን።'),
  ('628f71a4-68c2-5272-ad81-e35f24e30a2e', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 8, 8, 'የአይሁድንም ስም ያጠፉ ዘንድ የተሰበሰቡት አሕዛብ ናቸው።'),
  ('26fa576d-4cc4-5b6a-ae79-7b19f7746204', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 9, 9, 'ወደ እግዚአብሔርም የጮኹ፥ ከመከራውም የዳኑ ወገኖች እስራኤል ናቸው።” እግዚአብሔርም ወገኖቹን ከመከራው አዳናቸው፤ እግዚአብሔርም ከመከራው ሁሉ አዳነን፤ እግዚአብሔርም በሕዝቡ ዘንድ እንደዚህ ያልተደረገ ታላቅ ድንቅና ብዙ ታምራትን አደረገ።'),
  ('a6f9d173-16b1-58e7-a77c-b4a1ce3370e1', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 10, 10, 'ስለዚህም ነገር ሁለት ዕጣ አደረገ፤ አንዱ ለእግዚአብሔር ወገኖች ነው፤ ሁለተኛውም ለአሕዛብ ነው፤'),
  ('65cc0248-abfe-5c5a-a5b6-af74c21cc4ec', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 11, 11, 'እነዚያም ሁለት ዕጣዎች በቍርጥ ፍርድ ቀንና ሰዓት በእግዚአብሔር ፈቃድ በአሕዛብ ሁሉ ላይ ደረሱ።'),
  ('510f4fb1-6294-58bf-aa50-9478b828e690', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 12, 12, 'እግዚአብሔርም ወገኖቹን አሰባቸው፤ ርስቱንም አነጻ።'),
  ('06f918a2-6d3c-566e-a440-5b345ff70de4', 'e41aad70-5eb3-5adc-a78d-0740d4f2c660', '8c506563-5c04-5d1d-ad0e-7da18eb3c4f0', 13, 13, 'እነዚያም ቀኖች አዳር የተባለው ወር በባተ በዐሥራ አራተኛውና በዐሥራ አምስተኛው ቀን በእግዚአብሔር ፊት በደስታ ተሰብስበው በትውልዳቸው በእስራኤል ዘንድ ለዘለዓለሙ የሚያከብሩአቸው ሆኑ።'),
  ('6c6c65dc-f25d-5f2c-a76b-c902da07e06f', 'e0cc3720-8d1f-5310-a9f1-8fd9d298eb90', 'c5a232d3-0c0e-5d3f-aa74-e049bed09eb0', 1, 1, 'ጰጠሎሜዎስና ቀለዮጳጥራ በነገሡ በአራተኛው ዓመት፥ ካህንና ሌዊ ነኝ ያለው ዞሲጢዮስና ልጁ ጰጠሎሜዎስ በኢየሩሳሌም ከሚኖሩት አንዱ የጰጠሎሜዎስ ልጅ ሊሲማኮስ ተረጐማት ያሏትን የፉሪምን መልእክት አመጡ።'),
  ('f6464350-8844-5887-aac2-3bdf8efe5429', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 1, 1, 'ስሙ ጺሩጻይዳን የሚባል፥ ክፋትንም የሚወዳት አንድ ሰው ነበር፤ በፈረሶቹ ብዛትና ከሥልጣኑ በታች ባሉ በጭፍራዎቹ ጽናት ይመካ ነበር።'),
  ('d89b0129-fe43-568b-a064-0a254ee6fe20', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 2, 2, 'የሚያመልካቸውና የሚሰግድላቸው፥ በመዓልትና በሌሊት መሥዋዕት የሚሠዋላቸው ብዙ ጣዖታት ነበሩት።'),
  ('b9addf49-bde6-5726-aaa6-016e3267baf3', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 3, 3, 'እርሱ ግን በልቡናው ድንቍርና እነርሱ ኀይልንና ብርታትን የሚሰጡት ይመስለው ነበር።'),
  ('3d68a825-7792-505a-a6d6-7ec750c2d4e3', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 4, 4, 'በልቡም በግዛቱ ሁሉ እነርሱ ሥልጣንን የሚሰጡት ይመስለው ነበር።'),
  ('6c8c3919-2e3b-537e-a1ed-7e44ad6c3350', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 5, 5, 'ዳግመኛም በሰልፍ ጊዜ እነርሱ ሥልጣንንና የተመኘውንም ሁሉ የሚሰጡት ይመስለው ነበር።'),
  ('c6b1297a-e294-5981-a7a1-4b52c5ac82f2', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 6, 6, 'እርሱም ቀንና ሌሊት ይሠዋላቸው ነበር።'),
  ('32b15ab4-59bb-5cd2-afaf-df87f616a876', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 7, 7, 'ጣዖታቱን የሚያገለግሉ ካህናትን ሾመ።'),
  ('805c0035-db07-5bc5-a23a-e5c84232a040', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 8, 8, 'ከዚያች ከረከሰች መሥዋዕት እነርሱ እየበሉ ቀንና ሌሊት ጣዖቶቹ የሚበሉ አስመስለው ይነግሩት ነበር።'),
  ('6acc2d7a-b81a-55d1-ae3d-fbc5417b2180', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 9, 9, 'ዳግመኛ መሥዋዕት ሠውተው ይበሉ ዘንድ ሌሎች ሰዎችን እንደ እነርሱ ያተጉ ነበረ። ዳግመኛም እነርሱ መሥዋዕት ሠውተው እንደ እነርሱ መሥዋዕት ይሠዉ ዘንድ ሌሎች ሰዎችን ያተጉ ነበር።'),
  ('935467f7-0de5-5ec9-a107-a816dbd4a513', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 10, 10, 'እርሱ ግን ጥቅም በሌለው ጣዖቱ ይታመን ነበር።'),
  ('5ff7673e-bfea-5acf-aa25-e67114c0d6cc', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 11, 11, 'በልቡ ድንቍርናና በዕውቀቱ ማነስ እነርሱ የፈጠሩት፥ እነርሱም የሚመግቡትና የሚያነግሡት ይመስለው ነበር፤ አማልክት ሳይሆኑ አማልክት ካላቸው ከእርሱ ጋራ ተፈርዶባቸው ለዘለዓለም ወደ ገሃነመ እሳት ይሄዱ ዘንድ ካለ መኖር ወደ መኖር አምጥቶ የፈጠረውን ፈጣሪውን እርሱ ከወገኖቹ ጋር እንዳያውቅ ሰይጣን ልቡናውን አደንቁሮታልና የፈጠሩት ይመስለው ነበር።'),
  ('89cca10c-e553-5cac-a81f-7dd77076766c', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 12, 12, 'መቼም መች ሕያዋን አይደሉምና ሙታን ይሏቸው ዘንድ ይገባል።'),
  ('51c03392-1356-5f94-a9b2-7356329a37fc', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 13, 13, 'የሚያስታቸው የሰይጣን መንፈስ በዚያ በጣዖቱ ምስል ያድራልና፥ የልቡናቸውንም ፈቃድ ይነግራቸዋልና፥ እንደ ወደዱም ይገለጥላቸዋልና ባመኑባቸው፥ ልቡናቸውም እንደ ዐመድ የሆነ የአዳም ልጆች በሚታመኑባቸው በጣዖቶቹ ይፈረድባቸዋል።'),
  ('86cc82b4-dc3d-5fb1-a8ae-cc6f3a37a597', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 14, 14, 'ያሰቡትንም እንደ ፈጸመላቸው በአዩ ጊዜ ያደንቃሉ፤ እነርሱም ከባሕርያቸው የተወለዱ ወንዶች ልጆቻቸውንና ሴቶች ልጆቻቸውን እስኪሠዉ፥ የወንዶች ልጆቻቸውንና የሴቶች ልጆቻቸውን ንጹሕ ደም እስኪያፈስሱ ድረስ ፈቃዱን ያደርጋሉ።'),
  ('936b07ed-1ce4-509c-adbe-c4a4d5e1207a', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 15, 15, 'እስከ ዘለዓለም ድረስ መውጫ ወደሌለባት፥ እርሱ መከራ ወደሚቀበልባት እንደ እርሱ ወደ ገሃነም ያወርዳቸው ዘንድ ሰይጣን ክፉ ፈቃዳቸውን ለመፈጸም መሥዋዕቱን አጣጥሞላቸዋልና አላሳዘኗቸውም።'),
  ('87c347b9-9e61-5afc-a8dd-b215267bfc3e', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 16, 16, 'ያ ጺሩጻይዳን ግን ትዕቢተኛ ነበር፤ በወንዶች አምሳል የተሠሩ ሃምሳ፥ በሴቶች አምሳል የተሠሩም ሃያ ጣዖቶች ነበሩት።'),
  ('53b9a7a7-3306-5a72-a59f-3d284418453b', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 17, 17, 'ጥቅም በሌላቸው በእነዚያ በጣዖታቱም ይመካ ነበር፤ እጅግም ያከብራቸው ነበር፤ ጧትና ማታም ይሠዋላቸው ነበር።'),
  ('485be3e4-2e6e-56bf-a115-52cd3d9c7473', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 18, 18, 'ሰዎችንም ለጣዖቱ መሥዋዕት ይሠዉ ዘንድ ያዛቸው ነበር፤ እርሱም ከዚያች የረከሰች መሥዋዕት ይበላ ነበር፤ ሌሎችንም ከመሥዋዕቱ ይበሉ ዘንድ ያዝዛቸው ነበር፤ ይልቁንም ለክፋት ይተናኰል ነበር።'),
  ('d5cdf493-9f82-5d1d-a7e9-85457cf76dc0', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 19, 19, 'የብረትና የናስ፥ የእርሳስም ለሆኑ፥ ተመትተውም ለተሠሩ ጣዖታቱ አምስት ቤት ሠራላቸው።'),
  ('755f0fed-a01f-5b13-a488-1d1d2592112a', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 20, 20, 'በወርቅና በብርም አስጌጣቸው፤ በቤቱም ዙሪያ መጋረጃ አስጋረደላቸው፤ ድንኳንም አስተከለላቸው።'),
  ('6ea132af-2bd3-50dd-ae6f-0f1b8c861044', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 21, 21, 'በዚያም ጠባቂዎችን ሾመላቸው፤ የሰቡ ዐሥር በሬዎችን፥ ዐሥር መሲናዎች ላሞችን፥ የሰቡ ዐሥር የበግ ሙክቶችን፥ የመሰኑ ዐሥር ፍየሎችንም ክንፍ ከአላቸው ከወፎች ጋራ ለጣዖታቱ ዘወትር አርባ ይሠዋላቸው ነበር።'),
  ('e2a01c44-9137-55ce-ab6a-755a518d4812', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 22, 22, 'ለእርሱ ግን ጣዖታቱ የሚበሉ ይመስለው ነበር፤ ሃምሳ ፊቀን ወይን፥ በዘይት የታሸ ሃምሳ ወጪት ስንዴንም ያቀርብላቸው ነበር።'),
  ('55f52134-93b9-520e-a98e-7eceb6f990da', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 23, 23, 'ካህናቱንም “ወስዳችሁ ስጧቸው፤ ፈጣሪዎች ያረድሁላቸውን ሥጋ ይብሉ፤ ያቀረብሁላቸውንም ወይን ይጠጡ፤ ባይበቃቸውም እኔ እጨምርላቸዋለሁ” አላቸው።'),
  ('f6f2e63a-7665-57c7-a1c1-a9b0511dd228', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 24, 24, 'ከዚያች ከረከሰች መሥዋዕትም ይበሉና ይጠጡ ዘንድ ሁሉን ያስገድድ ነበር።'),
  ('186bc501-fd16-50cc-a680-b4acb3442be8', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 25, 25, 'እርሱ ግን በክፉ ተንኰሉ የማይሠዋም፥ የማይሰግድም እንዳለ ለይተው ዐውቀው ያመጡት ዘንድ፥ በፊቱም በእሳትና በሰይፍ ይቀጡት ዘንድ ገንዘቡንም ይበረብሩት ዘንድ፥ ቤቱንም በእሳት ያቃጥሉት ዘንድ፥ ያለውንም ገንዘቡን ሁሉ ይወስዱበት ዘንድ በግዛቱ ሁሉ የሚሰልሉ ጭፍራዎቹን ላከ።'),
  ('97c7ed5e-0578-56c5-aa7b-4f08239a2537', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 26, 26, 'ለአማልክቶችም መሠዋትንና ማምለክን እንቢ ካለ ለእርሱ እኔ መከራንና ቅጣትን አሳየዋለሁ። እነርሱ ደጋጎችና ታላላቆች ናቸውና፥ በቸርነታቸውም እኛን ፈጥረዋልና፤'),
  ('dc742e2a-472a-532e-af33-5e8a122d5f2b', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 27, 27, 'ሰማይንና ምድርን፥ ታላቅ ባሕርንም፥ ፀሐይንና ጨረቃን፥ ከዋክብትንም፥ ነፋሳትንና ዝናማትንም፥ ለእኛም ምግብና ጥጋብ ሊሆነን የሚንቀሳቀሰውን ሁሉ ፈጥረዋልና።'),
  ('7986575c-b434-5471-a7cf-44cf2987e5c2', '2461ce7a-f55b-56fa-a459-d8f92c0ec138', 'c50bb513-feea-5174-a970-8a7987f55a85', 28, 28, 'የማያመልኳቸው ግን በፍጹም መከራ ይቀጣሉ፤ አይራሩላቸውምም።'),
  ('a7ff7383-2039-5bcf-a2a5-b8ca688b68f4', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 1, 1, 'ከነገደ ብንያም ስሙ መቃቢስ የሚባል አንድ ሰው ነበረ።'),
  ('43b16254-11e5-5961-ad8f-768eba4cd0f7', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 2, 2, 'መልከ መልካሞችና እጅግ ብርቱዎች የሆኑ ሦስት ልጆች ነበሩት፥ በሰው ሁሉ ዘንድ በዚያች የጺሩጻይዳን ግዛት በምትሆን በከለዳውያን ምድር በምድያምና በሜዶን ሀገር መወደድ ነበራቸው።'),
  ('fe72efff-c83d-5532-ac82-1cf5663867b5', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 3, 3, 'በአገኙአቸውም ጊዜ እንዲህ አሏቸው፥ “ንጉሡ እንዳዘዘ ለጺሩጻይዳን አማልክት አትሰግዱምን? መሥዋዕትስ አትሠዉምን?'),
  ('48d7919d-e898-52eb-ac90-3ed20e89e634', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 4, 4, 'እንቢ ብትሉ ግን ይዘን ወደ ንጉሡ እንወስዳችኋለን፤ ንጉሡም እንዳዘዘ ገንዘባችሁን ሁሉ እናጠፋለን።”'),
  ('9cf8c99b-acc8-558a-afea-a7077321c044', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 5, 5, 'እነዚያ መልከ መልካሞች ጐልማሶችም፥ “እኛስ የምንሰግድለት ሰማይንና ምድርን፥ ባሕርን፥ በውስጧም ያለውን፥ ፀሐይንና ጨረቃን፥ ከዋክብትንና ደመናትን የፈጠረ የአባቶቻችን አምላክ አለ፤ እኛ የምናመልከው፥ የምናምንበትም እውነተኛ አምላክ እርሱ ነው” ብለው መለሱላቸው።'),
  ('3c57d5ef-6ad5-5e06-ad61-3b2d604d59fd', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 6, 6, 'እነዚያም የንጉሡ ብላቴኖች አራት መሳፍንት ነበሩ፤ የጦር መሣሪያቸውን የሚሸከሙ አሽከሮቻቸውም ሃምሳ፥ ሃምሳ ነበሩ።'),
  ('554aace4-5aba-5c3d-ac91-142fb0b24d0b', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 7, 7, 'እነዚህንም ቅዱሳን ይይዟቸው ዘንድ በወደዱ ጊዜ ከእጃቸው አመለጡ፤ የነካቸውም የለም፤ እነዚያ ጐልማሶች በኀይል ፈጽሞ አርበኞች ናቸውና ጋሻ ጦራቸውን ይዘው ሄዱ።'),
  ('56650bad-a224-525c-abae-5a68e6a20ca6', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 8, 8, 'ከእነርሱም ድብን አንቆ የሚገድል ነበር፤ ወዲያውኑም እንደ ዶሮ ያንቀው ነበር።'),
  ('aa2277c5-f17a-55c4-a0ef-99b6d22ff1dd', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 9, 9, 'ከእነርሱም በአንዲት ድንጋይ ወይም በአንድ ጊዜ በበትር መትቶ አንበሳ የሚገድል ነበር።'),
  ('5ec3c508-1b82-5298-a4fe-a4fd68673b94', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 10, 10, 'ከእነርሱም በሰልፍ ጊዜ በአንድ ሰይፍ በአንድ ጊዜ መትቶ ሰው የሚገድል ነበር፤ እንዲሁም ስማቸውና አደናቸው በሞዓብና በከለዳውያን ምድር ሁሉ የተጠራ ነበር።'),
  ('d9a0e04f-c3a5-5c40-a1f0-0c6decd167e9', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 11, 11, 'በኀይልም አርበኞች ነበሩ፤ ደም ግባትም፥ የነገርም መወደድ ነበራቸው።'),
  ('2ebb355f-11fa-5932-ad42-481d1f5a3405', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 12, 12, 'ዳግመኛም የመልካቸው ደም ግባት ድንቅ ነበር፤ ነገር ግን እግዚአብሔርን ስላመለኩት፥ ሞትንም ስላልፈሩት ከሁሉ የምትበልጥ የልቡናቸው ደም ግባት ናት።'),
  ('2dcef61e-1d5b-5ad0-aac1-f55a293fdd7d', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 13, 13, 'ጭፍራዎችንም ባስፈሩአቸው ጊዜ ይይዛቸው ዘንድ የቻለ የለም፤ ብርቱዎች የሆኑ እነርሱ ግን ከፍ ወደ አለ ተራራ ወጥተው አመለጡ።'),
  ('38fe8ef4-2f6f-552f-a659-fa941345551a', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 14, 14, 'እነዚያ ጭፍሮችም ወደ ከተማ ተመልሰው ያንባውን በር ዘጉ፤ እነዚያን አርበኞች መቃብያንን ካላመጣችኋቸው ከተማችሁን በእሳት እናቃጥላታለን፤ ወደ ንጉሡም ልከን ሀገራችሁን እናጠፋለን ብለው ሕዝቡን አስፈራሯቸው።'),
  ('e3e0d8c7-32f3-579f-a3fd-3c67c350787d', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 15, 15, 'የዚያን ጊዜም የሀገሩ ሰዎች ድሆችና ባለጸጎች፥ ወንዶችና ሴቶች፥ አባቱና እናቱ የሞቱበት ልጅና ባልቴቶችም፥ ሁሉም ወጥተው በአንድነት ጮሁ፤ ዐይኖቻቸውንም ወደ ተራራ አቀኑ፤ “እኛንና ሀገራችንን አታጥፉ” ብለው ወደ እነርሱ ጮሁ።'),
  ('de1c5718-90dd-5b38-a8f9-01797f1c25c7', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 16, 16, 'የዚያን ጊዜም በአንድነት አለቀሱ፤ ከእግዚአብሔርም የተነሣ ፈሩ።'),
  ('2eeba6b8-5e7f-5d2b-a7c2-d5902aefd18d', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 17, 17, 'ፊታቸውን ወደ ምሥራቅ መልሰው፥ እጃቸውንም ዘርግተው በአንድነት ወደ እግዚአብሔር ለመኑ፤ እንዲህም አሉ፥ “አቤቱ ትእዛዝህንና ሕግህን ያፈረሱ እነዚህን ሰዎች እንቢ እንበላቸውን?'),
  ('99ca3155-e27c-580a-a870-dcc18ba3ebe6', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 18, 18, 'እኛ ግን በወርቅና በብር፥ የሰው እጅም በሠራው በደንጊያና በእንጨት ይታመናል እንጂ ሕግህን የማያምን የዚያን ወንጀለኛ ቃል እንሰማ ዘንድ አንወድም።'),
  ('2087b93b-6483-5980-ac5c-0282437b7651', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 19, 19, 'የምታድንና የምትገድል አንተ ፈጣሪው ሳለህም ራሱን እነርሱ እንደ ፈጠሩት ያደርጋል፤ እርሱስ የሰውን ደም የሚያፈስ፥ የሰውንም ሥጋ የሚበላ ነው።'),
  ('6b05dc9b-e633-5a23-aa90-90ecf5ca2b0b', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 20, 20, 'እኛ ግን የዚያን የወንጀለኛ ፊት እናይ ዘንድ፥ ቃሉንም እንሰማ ዘንድ አንወድም።'),
  ('2ffae362-f965-5cd1-a3e2-588ed38f2e55', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 21, 21, 'ነገር ግን አንተ ካዘዝኸን ወደ እርሱ እንሄዳለን፤ በአንተ ስላመንን ሰውነታችንን ለሞት አሳልፈን እንሰጣለን፤ ለአማልክቶች መሥዋዕት ሠዉ ባለ ጊዜም የዚያን የወንጀለኛ ቃል አንሰማም።'),
  ('d993d3b4-bf5d-51d5-a414-fdd5460fa433', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 22, 22, 'ፈቃድህን ያደረጉ፥ በሕግህም ጸንተው የኖሩ የአባቶቻችን አምላክ አቤቱ፥ ኵላሊትንና ልቡናን የምትመረምር የአብርሃም፥ የይስሐቅ፥ የያዕቆብም አምላክ ሆይ! እኛ ግን በፍጹም ልባችን አንተን አመንን።'),
  ('85a73497-2422-5d45-a3ae-c3d1c5859461', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 23, 23, 'የሰውን ልቡና መርምረህ ኃጥኡንና ጻድቁን ትረዳዋለህ፤ የሚሰወርህም የለም፤ የተሸሸገውም ባንተ ዘንድ የተገለጠ ነው።'),
  ('f912e79c-d151-5adf-abd6-b75d315ee2d2', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 24, 24, 'እኛ ግን ከአንተ በቀር ሌላ አምላክ የለንም።'),
  ('a1585eee-3e10-575a-a2c9-ed577509d498', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 25, 25, 'ነገር ግን ስለ ቅዱስ ስምህ ሰውነታችንን ለሞት እንሰጥ ዘንድ በዚህ በምንገዛልህ ሥራ ኀይል፥ ብርታትና መጠጊያም ሁነን።'),
  ('91efef52-d596-58c9-a009-689c90158368', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 26, 26, 'እስራኤልም ወደ ግብፅ ሀገር በገቡ ጊዜ የያዕቆብን ጸሎት ሰማህ፤ አሁንም ቅዱስ አምላክ ሆይ እንለምንሃለን።”'),
  ('42adc31d-cc68-593e-a27f-3083f82b6893', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 27, 27, 'መልካቸው ፈጽሞ ያማረ፥ ሁለቱም ሰዎች በፊታቸው ቆመው በታዩአቸው ጊዜ እንደ መብረቅ የሚያስፈሩ የእሳት ሰይፎች ወርደው ያንጊዜ አንገታቸውን ቈርጠው ገደሏቸው፤ ያንጊዜም እንደ ቀደመው ሕያዋን ሁነው ተነሡ።'),
  ('1440e15c-8113-5844-a89d-41ad3e590793', 'aa37706c-8af7-5e53-af9a-86f5e5aefc93', 'a1c816b4-cfe6-5562-a2bb-34dc0ec9ab03', 28, 28, 'የመልካቸው ደም ግባት ፈጽሞ ያማረ ሆነ፤ ከፀሐይም ይልቅ አበሩ፤ ከቀደመውም ይልቅ ያማሩ ሆኑ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0e2b9004-a449-592a-a227-c14e348d01c9', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 1, 1, 'ከሰማይም እንዲህ የሚል ቃል መጣ፤ “የልዑል እግዚአብሔር ባሮች አብያ፥ ሲላ፥ ፈንቶስ፥ ሞተው የተነሡ እነዚህን በፊታችሁ እንዳያችሁ ከሞታችሁ በኋላ እንደዚሁ ትነሡ ዘንድ አላችሁ፤ ፊታችሁም በመንግሥተ ሰማይ ይበራል።'),
  ('797f4cfb-7bf5-540d-a8e5-5c6fb328a338', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 2, 2, 'ከእነዚያ ሰዎችም ጋራ ሂዱ፤ በዚያም ሰማዕትነትን ተቀበሉ።”'),
  ('b92cae33-4c07-51ad-a500-c9995bea9c76', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 3, 3, 'ያንጊዜም ጸለዩና አመሰገኑ፤ ለእግዚአብሔርም ሰገዱ፤ ሞትና የንጉሡ ቅጣትም አላስፈራቸውም።'),
  ('0b544281-ad88-50b3-ab61-3e9ab6ada363', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 4, 4, 'ወደ እነዚያ ብላቴኖችም ሄዱ፤ ክፋት እንደሌለው በግ ሆኑ እንጂ አላስፈሩአቸውም፤ ወደ እነርሱም በደረሱ ጊዜ ይዘው መትዋቸው፤ አስረውም ገረፏቸው፤ ወደ ንጉሡም አድርሰው በፊቱ አቆሟቸው።'),
  ('0a7ee1ed-3355-5a7d-ac82-8d3be53f93ed', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 5, 5, 'ንጉሡም፥ “እናንተ እንቢተኞች ለአማልክቶች እንዴት አትሠዉም? እንዴትስ አትሰግዱም?” ብሎ መለሰላቸው።'),
  ('48fb3442-9c0a-522d-ac00-332cba7b908b', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 6, 6, 'እነዚያ ቅዱሳንና ቡሩካን፥ የተመረጡና ደስ ያላቸው፥ ዋጋው ድንቅ እንደ ሆነ ዕንቍም የሚያበሩ ወንድማማቾች አብያ፥ ሲላና ፈንቶስም ባንድ ቃል መለሱለት።'),
  ('4db80077-549c-5bf0-ad62-6b77954a0f23', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 7, 7, 'ቸነፈር የሆነ ያን ንጉሥም እንዲህ አሉት፥ “እኛስ ዕውቀትና ልቡና ለሌላቸው ለረከሱ ጣዖቶች አንሠዋም፤ አንሰግድምም።'),
  ('921da697-3cba-51f8-adfd-fc4fad29f713', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 8, 8, 'ዳግመኛም፦ የሰው እጅ ለሠራቸው ወርቅና ብር፥ ድንጋይና እንጨት ለሆኑ፥ ነፍስና ልቡና፥ ዕውቀትም ለሌላቸው፥ መልካም ለሚያደርግላቸው መልካምን ለማያደርጉ፥ ክፉ ለሚያደርግባቸውም ክፉን ለማያደርጉ ጣዖታት አንሰግድም።”'),
  ('d70b045e-274f-5b92-a1d3-1d4487a529f8', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 9, 9, 'ንጉሡም እንዲህ ብሎ መለሰላቸው፥ “ለምን እንዲህ ታደርጋላችሁ? እነርሱ የሚሰድባቸውንና የሚበድላቸውን ያውቃሉና የከበሩ አማልክቶችን ለምን ትሰድባላችሁ”።'),
  ('459a3b36-da97-5e63-a901-9722077fc08b', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 10, 10, '“እነርሱም በእኛ ዘንድ እንደ ኢምንት ናቸውና እኛ እንሰድባቸዋለን፤ አናከብራቸውምም” ብለው መለሱለት።'),
  ('db9c2b48-7098-530a-ae89-18142487fa59', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 11, 11, 'ንጉሡም፥ “እንደ ሥራችሁ ክፋት መጠን እቀጣችኋለሁ፤ በጽኑ መከራና በግርፋት፥ በእሳትም የመልካችሁን ደም ግባት አጠፋለሁ።'),
  ('aaedd7f6-047e-58d9-ae82-9bc91993f120', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 12, 12, 'አሁንም ለአማልክቶች ትሠዉ እንደ ሆነ ወይም አትሠዉ እንደ ሆነ ንገሩኝ፤ ይህ ካልሆነ ግርፋትንና ሰይፍን በእናንተ ላይ አነሣለሁ” ብሎ መለሰላቸው።'),
  ('75493917-a5f3-562b-aef0-249c7109f1d7', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 13, 13, 'እነርሱም፥ “እኛስ ለረከሱ ጣዖታት አንሠዋም፤ አንሰግድምም” ብለው መለሱለት፤ ንጉሡም በወፍራም በትር ይመትዋቸው ዘንድ፥ ዳግመኛም በጅራፍ ይገርፏቸው ዘንድ፥ ከእዚያም በኋላ የውስጥ አካላቸው እስኪታይ ድረስ ይሰነጥቋቸው ዘንድ አዘዘ።'),
  ('6610fd07-255e-53d4-a414-0f049d7ff20f', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 14, 14, 'ከዚህም በኋላ ይቀጣቸውና ይገድላቸው ዘንድ እስኪመክር ድረስ አስረው በግዞት ቤት አዋሏቸው።'),
  ('47d27a86-6a99-5a7f-a3b3-ada6a9d9fd1d', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 15, 15, 'ወስደውም ያለ ርኅራኄ በእስር ቤት ጽኑዕ እስራት አሰሩአቸው፤ እነርሱም በእስር ቤት ሦስት መዓልትና ሦስት ሌሊት ተቀመጡ።'),
  ('e70a3221-bb88-5672-a060-1265988dedcc', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 16, 16, 'ከሦስት ቀንም በኋላ ንጉሡ፥ መኳንንቱና አማካሪዎቹ፥ ሹሞቹና የሀገር ሽማግሌዎች እንዲሰበሰቡ ዐዋጅ ነጋሪ ይዞር ዘንድ አዘዘ፤'),
  ('bd13645b-f250-50a6-a71c-b552f609a77e', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 17, 17, 'ንጉሡ ጺሩጻይዳንም በአደባባይ በተቀመጠ ጊዜ እነዚያን የከበሩ አብያን፥ ሲላንና ፈንቶስን ያመጧቸው ዘንድ አዘዘ፤ የታሰሩና የቈሰሉ ሆነውም በፊቱ ቆሙ።'),
  ('b7c57885-1caf-5b0b-ac4e-0dadb596d23c', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 18, 18, 'ንጉሡም፥ “ይህን ሦስቱን ቀን ስትቀመጡ በውኑ የተመለሳችሁት መመለስ አለን? ወይስ እናንተ በቀደመው ክፋታችሁ አላችሁ?” አላቸው።'),
  ('1b63417b-dbc0-5533-a2de-782d216a5fb9', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 19, 19, 'የከበሩ የእግዚአብሔር ጭፍራዎችም፥ “እኛስ የጨከን ነን፤ ኀጢአትና ክፋትን የተመላ፥ አንተ የምታመልከውን ጣዖትን እናመልክ ዘንድ እሺ አንልም” ብለው መለሱለት።'),
  ('02821425-a039-59da-ad76-5dee087db971', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 20, 20, 'ያም ወንጀለኛ ተቈጥቶ ይሰቅሉአቸውና ቍስላቸውንም ያድሱት ዘንድ አዘዘ፤ ደማቸውም በምድር ላይ ፈሰሰ።'),
  ('b2b6bfe6-1af2-5eb1-a951-a1c095b6fa6b', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 21, 21, 'ዳግመኛም በጭራሮ መብራት ያቃጥሏቸው ዘንድ፥ ሥጋቸውም ያር ዘንድ አዘዘ፤ እንዲሁም አደረጉ፤ እነዚያም የከበሩ ሰዎች “አንተ ዝንጉዕ፥ ተናገር፤ ቅጣታችንን በምታበዛብን መጠን ዋጋችን ይበዛል” አሉት።'),
  ('aca37ec4-7ec8-5438-a5c5-5e9d35a7b9f9', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 22, 22, 'ዳግመኛም ሥጋቸውን ከአጥንታቸው ጋራ ፈጽመው ይበሏቸው ዘንድ ምግባቸውን ሳይበሉ ክፉ አውሬዎችን ነብርንና ድብን፥ አንበሳንም አምጥተው ይሰዱባቸው ዘንድ አዘዘ።'),
  ('53d7aa3b-9053-5bfc-a6b9-50dab7752e60', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 23, 23, 'አውሬዎችን የሚጠብቁ ሰዎችንም አውሬዎቹን ይሰዱባቸው ዘንድ አዘዘ፤ እነርሱም እንዳዘዛቸው አደረጉ፤ የከበሩ እነዚያን ቅዱሳን ሰማዕታትንም የፊጥኝ አሰሩአቸው፤ ዳግመኛም ተተንኵለው፥ ካስማ መትተው አሰሩዋቸው።'),
  ('bd8768cd-e7ee-5170-a025-0201c591c172', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 24, 24, 'እነዚያም አውሬዎች እያገሡ በላያቸው ተወረወሩ፤ ወደ ሰማዕታቱም በደረሱ ጊዜ ሰገዱላቸው፤ እጅም ነሡአቸው።'),
  ('0b4d445e-3bb6-53ba-adfc-5cb67b46da86', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 25, 25, 'እያገሡም ወደ ጠባቂዎቻቸው ተመለሱ፤ ጠባቂዎቻቸውንም አስፈሯቸው፤ ወደ ንጉሡም ፊት እስኪያደርሷቸው ድረስ አባረሯቸው።'),
  ('00b028e2-4f5a-5b60-a8d3-603effc76fc1', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 26, 26, 'በዚያም ከወንጀለኞች ሠራዊት ሰባ አምስት ሰዎችን ገደሉ።'),
  ('b630b00d-aa7a-533a-a444-077acafb7b9c', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 27, 27, 'ንጉሡ ዙፋኑን ትቶ እስኪሸሽ ድረስ በፍርሀት አንዱ ባንዱ ላይ ተጨናንቀው ብዙ ሰዎች ተሰበሩ፤ አውሬዎቹንም በጭንቅ ይዘው ወደ ማደሪያቸው ወሰዱዋቸው።'),
  ('51f0d03d-473f-5ba7-a240-ff6de785a785', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 28, 28, 'የአብያና የሲላ የፈንቶስም ሁለቱ ወንድሞቻቸው መጥተው፥ ካሰሩአቸው እስራት ፈትተው “እነዚህ ወንጀለኞችና ተጠራጣሪዎች እንዳያገኙን ኑ እንሽሽ” አሏቸው።'),
  ('e261f7f5-3505-5f3f-a0b6-007369a545bd', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 29, 29, 'እነዚያም ሰማዕታት ወንድሞቻቸውን፥ “ለሰማዕትነት ከቆምን በኋላ እንሸሽ ዘንድ አግባብ አይደለም፤ እናንተ ፈርታችሁ እንደ ሆነ ሸሽታችሁ ሂዱ” ብለው መለሱላቸው።'),
  ('d897dac0-fd7d-5155-aba0-15e12db976b0', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 30, 30, 'እነዚያም ታናናሽ ወንድሞቻቸው፥ “እኛም በንጉሡ ፊት ከእናንተ ጋር እንቆማለን፤ ብትሞቱም እኛ አብረን እንሞታለን” አሉ።'),
  ('50af947c-27ac-550c-a11d-d1afc75c714b', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 31, 31, 'ከዚህም በኋላ ንጉሡ በመንግሥቱ አዳራሽ ሰገነት ላይ ሆኖ እነዚህ የተባረኩ ሰዎች እንደ ተፈቱና አምስቱ ወንድማማቾች ሁሉ በአንድነት እንደ ቆሙ አየ፤ ጭፍራዎችን የሚሠራሩና፥ የሚቀጡ እነዚያ አለቆችም ወንድሞቻቸው እንደ ሆኑ ጠይቀው ለንጉሡ ነገሩት፤ ንጉሡም ተቈጥቶ እንደ ምድረ በዳ እሪያ ጮኸ።'),
  ('0834d6fc-c1dc-5469-a28b-87d81f501718', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 32, 32, 'ንጉሡም አምስቱን ወንድማማቾች ሁሉ ይቀጣቸው ዘንድ እስኪመክር ድረስ ይዘው በእስር ቤት እንዲጨምሩአቸው አዘዘ፤ በተፈለፈለም ግንድ ያለ ርኅራኄ ጽኑ እስራትን አስረው በእስር ቤት አኖሯቸው።'),
  ('a5a37b68-9c07-524f-a726-c5f062fdde57', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 33, 33, 'ንጉሡ ጺሩጻይዳንም፥ “እነዚህ የሳቱ ጐልማሶች አደከሙኝ፤ የእነዚህ ሰዎች ልቡናቸው ምን ይጸና! የሥራቸውም ክፋት እንደ ኀይላቸው ጽናት ነው፤ ይመለሳሉ ብል ልቡናቸውን ያከፋሉ።'),
  ('4aa870fb-a429-5bae-a1f5-d26038de7eeb', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 34, 34, 'እኔም እንደ ሥራቸው ክፋት መጠን እከፍላቸዋለሁ፤ አርሮም አመድ ይሆን ዘንድ ሥጋቸውን በእሳት አቃጥላለሁ፤ ነፋስም ይወስዳቸው ዘንድ በዚያ የሥጋቸውን ዐመድ እንደ ትቢያ በተራራ ላይ እበትናለሁ” አለ።'),
  ('44315509-60df-5abf-a33d-73ca321dfaa1', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 35, 35, 'ይኽንም ከተናገረ በኋላ ሦስት ቀን ቈይቶ እነዚያን ቅዱሳን ያመጧቸው ዘንድ አዘዘ፤ እነዚያም ቅዱሳን በቀረቡ ጊዜ በታላቁ ጕድጓድ ምድጃ ውስጥ እሳት ያነዱ ዘንድ እሳቱን የሚያናድድና ድስት የሚያፈሉበት የተንኰል ሥራን ስብንና እንዶድን፥ የባሕር አረፋና ሙጫን፥ ድኝንም በውስጡ ይጨምሩ ዘንድ አዘዘ።'),
  ('ad00f35a-2e22-5f28-a30a-676e6fc5cd29', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 36, 36, 'በጕድጓዱም ያለው እሳት በነደደ ጊዜ መልእክተኞቹ “ያዘዝኸንን አደረግን፤ የሚጨመረውን ሰው ስደድ” ሲሉ ወደ ንጉሡ ሄዱ።'),
  ('070abfac-d740-5c6e-a393-8f445581e14d', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 37, 37, 'ተቀብለውም በእሳቱ ጕድጓድ ይጥሏቸው ዘንድ አዘዘ፤ ብላቴኖቹም ንጉሡ እንዳዘዛቸው አደረጉ፤ እነዚያም ቅዱሳን ወደ እሳቱ በገቡ ጊዜ፥ ነፍሳቸውን ለእግዚአብሔር ሰጡ።'),
  ('0dd5d19c-57a2-5656-a3f6-466fb9178f79', 'c73d6539-94a6-5c5d-a3fb-3ec4ee1a7c58', '4657ad45-3d1c-5c72-a45a-515613a06511', 38, 38, 'መላእክትም የጣሉአቸው ሰዎች እያዩ ተቀበሉአቸው፤ ነፍሳቸውንም አብርሃምና ይስሐቅ ያዕቆብም ወደ አሉበት፥ ደስታ ወደሚገኝበት ወደ ገነት ወሰዷቸው።'),
  ('2ed76a73-7d23-599a-a42b-40829b201cd0', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 1, 1, 'ያም ወንጀለኛ እንደ ሞቱ በአየ ጊዜ ዐመድ እስኪሆን ድረስ ሥጋቸውን በእሳት ያቃጥሉ ዘንድ፥ በነፋስም ይበትኗቸው ዘንድ አዘዘ፤ እሳቱ ግን ከሬሳቸው ወገን የራሳቸውን ጠጕር ያቃጥል ዘንድ አልተቻለውም፤ ከጕድጓዱም አወጧቸው።'),
  ('39cc5d23-ff79-525e-aac4-e34ca95e76c6', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 2, 2, 'ዳግመኛም ከጧት ጀምረው እስከ ማታ ድረስ በላያቸው እሳትን አነደዱ፤ አልነካቸውምም፤ “አሁንም ኑ፤ ሬሳቸውን ወደ ባሕር እንጣለው” አሉ።'),
  ('57e9f8ec-5fb1-5bf3-a86e-b6962ff8b653', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 3, 3, 'ንጉሡም እንዳዘዛቸው አደረጉ፤ ወደ ባሕርም ጣሏቸው፤ ምንም ከባድ ከባድ ብረቶችንና ታላላቅ ድንጋዮችን፥ አህያ በመዘውር የሚፈጭበትንም ወፍጮ ጨምረው ወደ ባሕር ቢጥሏቸው ባሕሩ ያሰጠማቸው ማስጠም የለም፤ የእግዚአብሔር መንፈስ አድሮባቸዋልና በባሕሩ ላይ ተንሳፈፉ እንጂ በጥልቁ ባሕር አልሰጠሙም፤ በተተነኰለባቸውም ተንኰል ሁሉ እነርሱን ማጥፋት ተሳነው።'),
  ('67248428-4454-597e-ab6f-84f058c12205', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 4, 4, '“ከሕይወታቸውም ይህ ሞታቸው አድክሞኛልና ይበሏቸው ዘንድ ሬሳቸውን ለአውሬዎች ልጣል እንጂ ምን አደርጋለሁ?” አለ።'),
  ('e477a296-b5fc-5b52-a78c-7e5de32ab4c5', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 5, 5, 'እንዲሁም አደረጉ፤ አውሬዎችና አሞሮችም ሬሳቸውን አልነኩትም፤ አሞሮችና ወፎች በፀሐይ ከመቃጠል በክንፋቸው ጋርደዋቸው የአምስቱ ሰማዕታት ሬሳቸው ዐሥራ አራት ቀን ተቀመጠ።'),
  ('aad2d9e6-8e52-5364-ab74-722eb24ece62', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 6, 6, 'በአዩአቸውም ጊዜ ሰውነታቸው እንደ ፀሐይ ጨረር አበራ፤ ብርሃንም ድንኳኑን እንዲከብ፥ መላእክት ሬሳቸውን ከበቡት።'),
  ('db470630-ae95-58f0-a268-a93f764f019e', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 7, 7, 'ምክርን መከረ፤ የሚያደርገውንም አጣ፤ ከዚህም በኋላ ምድርን ቈፍሮ የአምስቱን ሰማዕታት ሬሳቸውን ቀበረ።'),
  ('f1a0d8c1-269f-5c23-a1f7-5a17a4920c26', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 8, 8, 'ለዚያም ዝንጉ ንጉሥ ሌሊት በአልጋ ተኝቶ ሳለ አምስቱ ሰማዕታት ተቈጥተው ሰይፋቸውን ይዘው ሌሊት በፊቱ ቁመው ታዩት።'),
  ('d836b4b8-560a-560f-a8bf-70d71cef9791', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 9, 9, 'ሌሊት በወንጀል ወደ ቤቱ የገቡ መስሎታልና ከእንቅልፉ በነቃ ጊዜ ፈርቶ ከቤት ማዕዘን ወደ ማዕዘን ይሸሽ ዘንድ ወደደ፤ የወነጀሉትም መሰለው፤ የሚገድሉትም መስሎታልና ፈርቶ ጕልበቱ ተንቀጠቀጠ።'),
  ('74491e5b-a757-5aa1-ac11-bf9d462b6700', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 10, 10, 'ስለዚህም “ጌቶች፥ ምን ትፈልጋላችሁ? እኔስ ምን ላድርግላችሁ?” አለ።'),
  ('5994629c-b8e1-598e-a5ab-0f230c4ca4f3', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 11, 11, '“በእሳት አቃጥለህ የገደልኸንና እኛን በባሕር ላይ ይጥሉን ዘንድ ያዘዝህ አይደለምን፤ ስለአመንበት እግዚአብሔር ሰውነታችንን ጠብቆአልና እኛን ማጥፋት ተሳነህ፤ በእርሱ ያመነ ሰው አይጠፋምና ለእግዚአብሔር ክብር ምስጋና ይግባው፤ ያመንበት እኛም በመከራው አላፈርንም” ብለው መለሱለት።'),
  ('8b9e0796-4c43-5235-a21e-3d7ad0d4cf8c', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 12, 12, '“እንደዚህ ያለ ቅጣት እንዲያገኘኝ አላወቅሁምና ክፉ ነገርን ስላደረግሁባችሁ ፋንታ ምን ዋጋ ልስጣችሁ?'),
  ('58a56b52-6ede-586a-a25c-71f9e946a3bd', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 13, 13, 'አሁንም ሰውነቴን በሞት እንዳትወስዱ፥ በሕይወትም ሳለሁ ወደ ሲኦል እንዳታወርዱኝ የምሰጣችሁን ዋጋ ለዩልኝ።'),
  ('86d33ea0-bfba-5c4e-a9db-9888bc9a9978', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 14, 14, 'እኔ በድያችኋለሁና የአባታችሁ የእግዚአብሔር ሕግ ርኅራኄ ስለሆነ ኀጢአቴን ይቅር በሉኝ” አላቸው።'),
  ('8a0fcd2c-4207-511f-a195-62340b494dff', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 15, 15, 'እነዚያም ቡሩካን ሰማዕታት እንዲህ ብለው መለሱለት፥ “ክፉ ነገርን ስላደረግህብን ፋንታ እኛ ክፉ ነገርን አንከፍልህም፤ ፍዳን የሚከፍል እግዚአብሔር ነውና ፍዳንስ የሚከፍልህ ፈጣሪያችን እግዚአብሔር አለ።'),
  ('87b5baff-5ed1-532c-aec3-810176e3ba00', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 16, 16, 'ነገር ግን ስለዕውቀትህ ማነስና ስለ ልቡናህ ድንቍርና እኛ ሕያዋን እንደ ሆንን ተገልጠን ታየንህ፤ እኛንስ የገደልኸን መስሎህ ሕይወትን አዘጋጀህልን።'),
  ('e09dde25-88d7-543e-a183-bf2c12d063bc', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 17, 17, 'አንተና የጣዖቶችህ ካህናት ግን ለዘለዓለሙ መውጫ ወደሌለባት ወደ ገሃነም ትወርዳላችሁ።'),
  ('f20cfd24-8743-520f-a164-bf25a0a173b1', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 18, 18, 'እናንተ ምራቅ ስትሆኑ ለፈጠራችሁ ለእግዚአብሔር መስገድን ትታችሁ ለምታመልኩአቸውና ለምትሰግዱላቸው ጣዖቶችና ለአንተ ወዮላችሁ፤ ከወዴትም እንደ አመጣችሁ አታውቁም፤ ዛሬ ታይታችሁ ነገ የምትጠፉ ጢስ አይደላችሁምን?”'),
  ('309cae22-d04e-5742-a7bf-6080a4001dff', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 19, 19, 'ንጉሡም፥ “የወደዳችሁትን ሁሉ አደርግላችሁ ዘንድ ምን ታዝዙኛላችሁ?” ብሎ መለሰላቸው።'),
  ('89e3c629-87f2-5d1b-abc5-ce1388a85c5a', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 20, 20, '“ወደ ገሃነመ እሳት እንዳትገባ ስለ ራስህ ነው እንጂ የምናስተምርህ ስለ ራሳችን አይደለም።'),
  ('65dfeab5-cb28-584d-a2b6-6c811837f9cf', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 21, 21, 'ጣዖቶቻችሁ ነፍስና ልቡና፥ ዕውቀትም የሌላቸው፥ የሰው እጅ የሠራቸው ወርቅና ብር፥ ድንጋይና እንጨት ናቸውና።'),
  ('f4cd73f6-f894-5c00-acd6-42b14dbd9e76', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 22, 22, 'እነርሱ ግን አይገድሉም፤ አያድኑምም፤ መልካም አያደርጉም፤ ክፉም አያደርጉም፤ አያዋርዱም፤ አያከብሩምም፤ አያደኸዩም፤ ባለጸጋም አያደርጉም፤ አይነቅሉም፤ አይተክሉምም።'),
  ('4689bd88-3f5f-5384-a3e1-5603a8efa2a2', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 23, 23, '“ነገር ግን ከሰዎች ይልቁንም እንደ እናንተ ዕውራነ ልብ ከሆኑ አንዱስ እንኳ እንዳይድን በሚወድዱ አጋንንት መንፈስ እናንተን ያስታሉ። እናንተ የሠራችኋቸው ስትሆኑ እነርሱ የፈጠሯችሁ ይመስላችኋልና።'),
  ('3857b079-0c7c-572d-a139-ea4d03cc8490', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 24, 24, 'የአጋንንትና የሰይጣናት መናፍስት አድረውባቸዋልና በባሕረ ገሃነም ውስጥ ያሰጥሟችሁ ዘንድ እንደ ወደዳችሁ ይመልሱላችኋል።'),
  ('78662bd8-d963-5cc4-a7c5-6412cb30851e', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 25, 25, 'አንተ ግን ይህን ስሕተትህን ትተህ አምላካችን እግዚአብሔርን አምልከው፤ ይህም ነፍሳችንን እንጠቅማት ዘንድ ስለ ሞታችን ፋንታ ዋጋችን ይሁን” አሉት።'),
  ('e69216cc-9057-5ea2-a1ba-6347d9d0e261', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 26, 26, 'እርሱ ግን ደንግጦ ፈጽሞ ያደንቅ ነበር፤ አምስቱም ሁሉ ሰይፋቸውን መዝዘው ታይተውታልና ፈራ፤ ስለዚህም ሰገደላቸው።'),
  ('38c64826-b96b-59b5-aa11-081b8c6762bd', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 27, 27, '“እንግዲህስ ትቢያ የሆኑ ሙታን ከሞቱ በኋላ በእውነት እንዲነሡ ዐወቅሁ፤ እኔስ ልሞት ጥቂት ብቻ ቀርቶኝ ነበር” አለ።'),
  ('527ee5b0-ac64-546e-a95a-c68f631b59ca', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 28, 28, 'ከዚህ በኋላ ከዚያ ንጉሥ ፊት ተሰወሩ፤ ከዚያችም ቀን ወዲያ ፈጽሞ ትዕቢተኛና ኵራተኛ የሚሆን ያ ጺሩጻይዳን ሬሳቸውን ማቃጠልን ተወ።'),
  ('08f64a8f-3cde-5756-ae30-fbdaf8b24ef4', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 29, 29, 'ብዙ ዘመን አስተውታልና በልቡናው ስሕተት በጣዖቶቹ ደስ ይለው ነበር፤ የፈጠራቸውንም መከተል እስኪተዉ ድረስ እንደ እርሱ ያሉ ብዙ ሰዎችን አሳተ እንጂ እርሱ ብቻ የሳተ አይደለም።'),
  ('612e6f48-d760-534b-a1c7-5eb34feda6bf', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 30, 30, 'ወንዶች ልጆቻቸውንና ሴቶች ልጆቻቸውንም ለአጋንንት ይሠዉ ነበር፤ እግዚአብሔር የማይወድደውን ሁከትንና መዳራትን ያደርግ ዘንድ አባታቸው ሰይጣን ያስተማራቸው የልቡናቸውን ፈቃድ ዝሙትንና መዳራትን ይሠሩ ነበር።'),
  ('ad640cef-1883-5791-ab9b-3f98f11c65bd', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 31, 31, 'እናታቸውን ያገቡ፥ እኅቶቻቸውንና አክስቶቻቸውንም ያረክሱ ነበር፤ ይህን የረከሰ ሥራና የሚመስለውንም ሁሉ ይሠሩ ነበር፤ ሰውነታቸውንም ያረክሱ ነበር፤ ሰይጣን የእነዚያን ጠማሞች ሰዎች ልቡናቸውን አጥንቶታልና አንመለስም አሉ።'),
  ('91909f75-42cb-5973-ac9f-0b77a086512c', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 32, 32, 'ፈጣሪውን የማያውቅ ያ ጺሩጻይዳን ግን ኵሩና ትዕቢተኛ ነበር፤ በጣዖቶቹም ይመካ ነበር።'),
  ('466b732a-c844-52b9-a7ed-eeed72a42b7e', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 33, 33, '“እግዚአብሔር ለማያውቁት ሰዎች መንግሥትን እንዴት ይሰጣል? ፈጽመው ወደ እርሱ ይመለሱ እንደ ሆነ ስለሚፈትናቸው ነው” አለ።'),
  ('9b25739b-ecfb-5e78-a0b0-f869c8915824', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 34, 34, 'እነርሱ ግን ፈጽመው ቢመለሱ ይወድዳቸው ነበር፤ መንግሥታቸውንም ይጠብቅ ነበር፤ እንቢ ቢሉ ግን ለዘለዓለሙ በገሃነም እንቅጥቅጥ ይቀጣቸዋል።'),
  ('6a6b6473-3a14-53e9-a254-6ced86bad6c4', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 35, 35, 'ንጉሡ ግን እንደ መንግሥቱ ገናናነት እግዚአብሔር አምላክን ሊፈራው ይገባው ነበር፤ ፈራጅም እንደ ግዛቱ ገናንነት ለፈጣሪው በመልካም ሊገዛ ይገባ ነበር።'),
  ('507f96a1-d64b-5282-afb0-98c53647de3e', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 36, 36, 'ታላላቆች ሽማግሌዎች፥ አለቆችና ሹሞችም እንደ ክብራቸው ገናንነት ለፈጣሪያቸው ሊታዘዙ ይገባ ነበር።'),
  ('e4bfefb6-c916-5fbc-af75-e2ef251be064', 'd15eac4a-e8ed-5d29-a3cf-550d82cd5e47', 'a2dafa2e-36fe-51a8-af3b-74b8368cda23', 37, 37, 'ፍጥረቱን ሁሉ የፈጠረ የሰማይና የምድር ጌታ እርሱ ነውና፤ የሚያደኸይ፥ ባለጸጋም የሚያደርግ፥ የሚያዋርድ፥ የሚያከብርም እርሱ ነው፤ በላይ በሰማይ፥ በታችም በምድር ከእርሱ በቀር ሌላ አምላክ የለምና።'),
  ('e2409f46-e802-56de-a89c-a64ef872eaf5', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 1, 1, 'ረዓይታዊው ኮራ፤ እግዚአብሔርም፦ በአንዲት የወባ ትንኝ ከእግሩ ጀምሮ እስከ ራሱ ድረስ ሰውነቱ እንዲያብጥ አደረገው፤ በዚያችም ትንሽ የወባ ትንኝ ሞተ።'),
  ('0c5d5ea7-f20e-5d44-acb1-987f98bbe9fb', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 2, 2, 'ዳግመኛም ከኀይለኝነቱ ብዛት የተነሣ የብረት አልጋ ያሠራው ናምሩድ ኰራ፤ እርሱንም እግዚአብሔር አጠፋው።'),
  ('3106a9ef-8bf6-5511-ad18-af0b2442aa6a', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 3, 3, 'ዳግመኛም ናቡከደነጾር ኰራ፤ “ያለ እኔም ሌላ ንጉሥ የለም፤ በምድርም ላይ ፀሐይን የማወጣ እኔ ነኝ” አለ፤ ከትዕቢቱም ብዛት የተነሣ እንዲህ አለ።'),
  ('60e90721-6c22-5ed1-a94a-42ede797e292', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 4, 4, 'እግዚአብሔር ከሰው ለይቶ ሰባት ዓመት ወደ ምድረ በዳ ሰደደው፤ የፈጠረውም እግዚአብሔር እንደ ሆነ እስኪያውቅ ድረስ ዕድሉን ከምድረ በዳ አራዊትና ከሰማይ ወፎች ጋር አደረገ።'),
  ('6c683fed-2dd1-599b-a31a-c14e614570c2', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 5, 5, 'ባወቀውም ጊዜ ዳግመኛ ወደ መንግሥቱ መለሰው፤ በፈጠረው በእግዚአብሔር ላይ ተደፋፍሮ የኰራ፥ መሬትም ያልሆነ ማን ነው?'),
  ('88b2013c-4402-5b03-a781-1f78c0d6ffb1', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 6, 6, 'ሕጉንና ሥርዐቱንስ አፍርሶ መሬት ያልዋጠችው ማን ነው?'),
  ('750e9bda-57e4-51e6-a3d1-124d2ec9fad3', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 7, 7, '“ጺሩጻይዳን አንተም በፈጣሪህ ላይ ትኰራ ዘንድ ትወድዳለህ፤ አንተንም ዳግመኛ ከትዕቢትህ የተነሣ እንደ እነርሱ ያጠፋህ ዘንድ፥ ወደ መቃብርም ያወርድህ ዘንድ አለህ።'),
  ('2b8a3970-769d-59db-a809-b90ffa9cee42', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 8, 8, 'ዳግመኛም ጥርስ ማፋጨትና ልቅሶ ወዳለበት የጨለማ ፍጻሜ ወደ ሆነው ወደ ሲኦል፥ ከገቡም በኋላ ለዘለዓለም መውጫ ወደሌለበት ወደ ትልቁና ጥልቁ ጕድጓድ ያወርድህ ዘንድ አለህ።'),
  ('108a07c2-0022-5748-aac4-a7ba53005de3', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 9, 9, 'አንተስ እንደ አንተ እንደ ነበሩና የዚህን ዓለም ኑሮ እንደ ተዉ እንደ ትዕቢተኞች ነገሥታት ነገ የምትሞትና የምትፈርስ ነህ።”'),
  ('041d38df-102f-5bd8-a854-dfc6a2fed914', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 10, 10, 'እኛስ እንዲህ እንላለን፥ “አንተ ሰው ነህ፤ እግዚአብሔርም አይደለህም፤ እግዚአብሔር ምድርንና ሰማይን የፈጠረ፥ አንተንም የፈጠረ ነውና፤'),
  ('da4a6be6-307a-5d52-a2fc-45ee57abd0cb', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 11, 11, 'እርሱም ትዕቢተኞችን ያወርዳቸዋል፤ የተዋረዱትንም ያከብራቸዋል፤ እርሱም ለደከሙት ብርታትን ይሰጣቸዋል፤ ለኀያላኑም ድካምን ይሰጣል።'),
  ('36876d7c-29e3-5c5f-a9ed-9c4fcffbfbd6', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 12, 12, 'እርሱ ሕያዋንን ይገድላል፤ እርሱም በመቃብር ተቀብረው መሬት የሆኑትን ሙታን ያስነሣቸዋል።'),
  ('4a72299c-0205-5063-a884-c1c74d7f4f5a', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 13, 13, 'ባሮችንም ከኀጢአት ባርነት ወደ ሕይወት ነጻ ያወጣቸዋል።'),
  ('a3d4fec7-9ac3-5a91-ac17-f531a25a14dd', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 14, 14, '“ንጉሥ ጺሩጻይዳን ሆይ! ጥቅም በሌላቸው በረከሱ ጣዖቶችህ ለምን ትመካለህ?'),
  ('7184df62-1b12-5411-a1af-33908bf2e2bb', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 15, 15, 'እግዚአብሔር ግን ሰማያትን ፈጠረ፤ ምድርንም መሠረተ፤ ታላቁንም ባሕር ፈጠረ፤ ፀሐይንና ጨረቃን ፈጠረ፤ ዘመኖችንና ዓመታትን አዘጋጀ።'),
  ('ebcb67a4-920e-55dc-ab75-fde5fc2c0be0', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 16, 16, 'ሰውም ወደ እርሻው ይሰማራል፤ እስኪመሽም ድረስ ሲያርስ ይውላል፤ የሰማይ ከዋክብትም በቃሉ ጸንተው ይኖራሉ።'),
  ('ed8dc2b3-df5b-5def-ac68-2f1c4fa3554e', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 17, 17, 'ሁሉንም በየስማቸው ይጠራቸዋል፤ እግዚአብሔርም ሳያውቀው የሚደረግ ነገር የለም።'),
  ('7dda1c66-064b-53f8-a0e8-fa37d6f9c8cb', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 18, 18, 'እርሱም ያገለግሉት ዘንድ፥ የከበረ ስሙንም ያመሰግኑ ዘንድ የሰማይ መላእክትን አዘዘ፤ መላእክትም ሕይወትን ወደሚወርሱ ሰዎች ሁሉ ይላካሉ።'),
  ('6cbc56d6-3a49-5cec-acc9-491883f74d35', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 19, 19, 'መልአኩ ሩፋኤል ወደ ጦቢት ተላከ፤ ጦብያንም በራጉኤል ሀገር አዳነው።'),
  ('97b55bc9-dc3a-50ac-ac50-2d22df00a4d1', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 20, 20, 'ኤሎፍላውያንንም እንዲያጠፋቸው ያሳውቀው ዘንድ መልአክ ወደ ጌዴዎን ተላከ፤ እስራኤልንም የኤርትራን ባሕር ባሻገራቸው ጊዜ መልአክ ወደ ነቢዩ ሙሴ ተላከ።'),
  ('b0659616-a421-5848-a573-dd9b88af3f14', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 21, 21, 'እንዲህ ብሏልና፦ እግዚአብሔር ብቻውን መራቸው፥ ከእነርሱም ጋር ሌላ አምላክ አልነበረም።'),
  ('66b9265b-40d2-533c-a52d-a450bdfefefd', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 22, 22, 'በምድር ላይ ወደአለ አዝመራም አወጣቸው።'),
  ('5179a404-1868-5abb-aa62-dbde10cc6d54', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 23, 23, 'የሁዳዱንም እህል መገባቸው፤ ፈጽሞ ወዷቸዋልና፥ ከዐለት ማርን መገባቸው።'),
  ('167a09b5-be2f-51ed-a573-d1b155a5ad0b', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 24, 24, '“አንተንም በሕዝቡ ላይ አነገሠህ፤ ወገኖቹንም በሚገባ ፈጽመህ ትጠብቅ ዘንድ፥ የፈጠረህ የእግዚአብሔርንም ፈቃዱን ታደርግ ዘንድ በአራቱ መንግሥታት ላይ ሥልጣንን ሰጠህ።'),
  ('c71956f0-4065-53c9-a045-62b74a1f3db8', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 25, 25, 'ከሁሉም ከፍ ከፍ አድርጎ አንግሦሃልና ፈጣሪህ እግዚአብሔርን ትወደው ዘንድ ፈጽሞ አነገሠህ።'),
  ('8c043281-c2ec-5298-a53a-4aa6c4ed4f35', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 26, 26, 'አንተም እንደ ወደደህ፥ በሕዝቡም ሁሉ ላይ እንዳመነህ ፈጣሪህ እግዚአብሔርን ፈጽመህ ትወድደው ዘንድ ይገባሃል፤ አንተም የእግዚአብሔርን ፈቃድ አድርግ፥ በምድር ሁሉ ዘመንህ ይበዛ ዘንድ፥ ከአንተም ጋር ይኖር ዘንድ፥'),
  ('ae4191c6-4018-50c6-aec8-b886d74b631d', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 27, 27, 'በጠላቶችህም ላይ ይቆምልህ ዘንድ፥ በዙፋንህም ሁሉ ያስቀምጥህ ዘንድ፥ ክንፉንም በራስህ ላይ ይጋርድ ዘንድ።'),
  ('efd5cb61-cefb-5656-a886-1bb51bf48730', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 28, 28, 'ብታውቅስ እግዚአብሔር ሳኦልን የአባቱን አህዮች ሲጠብቅ ከእስራኤል ልጆች መርጦ በወገኖቹ በእስራኤል ላይ እንደ አነገሠው፥ ከነቢዩም ከሳሙኤል ጋር በዙፋን እንደ ተቀመጠ አንተን መረጠህ።'),
  ('7bc43ddc-1adc-5a53-a76b-b72d3b69948a', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 29, 29, 'ከወንድሞቹም ለይቶ ከፍ ያለ ዕድልን ሰጠው፤ እንዲህም አለው፦ ከዛሬ ጀምሮ ወገኖቹን ትጠብቅ ዘንድ እግዚአብሔር በሕዝቡ ላይ አነገሠህ፤'),
  ('4b3739a5-2f7a-5676-a0b9-e4f683336a7f', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 30, 30, 'ትገድልና ታድን ዘንድም እግዚአብሔር በላያቸው ሾሞሃልና በጎ የሚሠሩትን በበጎ፥ ክፉ የሚሠሩትንም በክፉ ጠብቃቸው።'),
  ('ca44d33d-64c7-5629-ad46-1d1271c776f8', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 31, 31, 'እየገረፍህና እያዳንህም ቢሆን ፈቃዱን ታደርግ ዘንድ እግዚአብሔር አንተን በሁሉ ላይ ሾሞሃልና በጎ የሚሠሩትን በጎ ክፈላቸው፤ ክፉ የሚሠሩትንም ክፉ ክፈላቸው።'),
  ('44ef31cc-64dc-531f-a56c-293c2d9fc0cb', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 32, 32, 'አንተ በሰማይ ያለ ሁሉን የሚገዛ የእግዚአብሔር ባሪያ ነህና፥ ባሰብኸው ሁሉ በፊቱ እየተገዛህ፥ በለመንኸውም ሁሉ ፈቃድህን ያደርግልህ ዘንድ አንተም በየጊዜውና በየሰዓቱ የእግዚአብሔርን ፈቃድ አድርግ።'),
  ('8c9caa9f-afc2-53d1-a8da-18a1c3c15ebb', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 33, 33, '“እርሱን የሚገዛው የለም፤ እርሱ ግን ሁሉን ይገዛል።'),
  ('fb7c9499-e0e4-541c-ac18-4a09d97cfdb4', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 34, 34, 'እርሱን የሚሾመው የለም፤ እርሱ ግን ሁሉን ይሾማል።'),
  ('158f78f2-f2f2-5d0d-aa6b-c159c34a80a7', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 35, 35, 'እርሱን የሚሽረው የለም፥ እርሱ ግን ሁሉን ይሽራል።'),
  ('11f52577-79d2-553a-aa92-832786cf00e8', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 36, 36, 'እርሱን የሚነቅፈው የለም፤ እርሱ ግን ሁሉን ይነቅፋል።'),
  ('393ce82a-8104-5bdc-a8b5-8ae9604b69ca', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 37, 37, 'እርሱን የሚያተጋው የለም፤ እርሱ ግን ሁሉን ያተጋል፤ የሰማይና የምድር ሥልጣን የእርሱ ነውና ከእጁ የሚያመልጥ የለም፤ በእርሱ ዘንድ ሁሉ የተገለጠ ነው እንጂ ከዐይኑ የተሰወረ የለም።'),
  ('7563fe4b-900e-5403-a7bb-a7b82df4ad6c', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 38, 38, 'ሁሉንም ያያል፤ እርሱን ግን የሚያየው የለም፤ ወደ እርሱ የሚጸልየውን ጸሎቱን ይሰማዋል፤ ጸሎቱንም ይቀበለዋል፤ ሰውን በአምሳሉና በአርኣያው ፈጥሮታልና።'),
  ('48b2cf11-d158-52dd-abc8-ddbf23b7d046', '5c6d58d3-3fff-5a31-a62e-a1fc0613f341', 'b0ad0ebb-52f0-5445-ad63-33fcd4e597aa', 39, 39, 'ከማይጐድል መዝገቡም ሁሉን ይመግባል። ለዘለዓለም የሚኖር ንጉሥ ነውና።'),
  ('7279cfab-f753-5c50-a6ac-d525bab9a404', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 1, 1, '“ፈቃዱን የሚያደርጉ ነገሥታቱን በእውነት ያነግሣቸዋልና ነገሥታቱ ስለ እርሱ የቀና ነገርን ጻፉ።'),
  ('8f6f8a16-5ea8-536b-a7cc-9761c6db5039', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 2, 2, 'አብርሃምና ይስሐቅ፥ ያዕቆብም፥ ዳዊትና ሰሎሞን፥ ሕዝቅያስም፥ ማደሪያቸው ብርሃን የሆነች ደጋጉ ነገሥታትም ሁሉ ባሉበት ማደሪያቸውን በማይመረመር ብርሃን ያበራል፤ የእግዚአብሔርን ፈቃድ አድርገዋልና።'),
  ('df34af01-4f49-5f31-a046-cad229f7e3cb', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 3, 3, 'በምድር እንደ አለ አዳራሽም አይደለም፤ ነገር ግን ፈጽሞ ብሩህ የሆነ በሰማይ ያለ አዳራሽ ነው፤ የወርቅ፥ የብርና የዕንቍ የሆነ ወለሉም ንጹሕ ነው።'),
  ('979838ba-a134-5aa4-a003-b7d4c6eb575a', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 4, 4, 'ፈጽሞ የሚያበራ መልኩም ከሰው ልቡና የራቀ ነው፤ የመንግሥተ ሰማያት አዳራሽ በጳዝዮንና በመረግድ፥ በጠልማና በወራውሬ የሚያበራ ነው።'),
  ('d0af7265-902d-5c93-abd6-09548fb88c70', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 5, 5, 'ከሰው ሕሊና ባለፈ በከበረ ዕንቍ እጅግ የሚያበራ የመንግሥት አዳራሽ ነው። እርሱ ራሱ እግዚአብሔር እንደሚያውቅ የሠራው የመንግሥተ ሰማያት አዳራሽ ነው። የወርቅና የብር፥ የሰማያዊ ዕንቍና የአረንጓዴ ዕንቍ፥ የብጫ ዕንቍና የነጭ ሐር መልክ ያለው ወለሉም ንጹሕ ነው።'),
  ('537d4310-61a1-5610-aff8-31bf1f1074c8', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 6, 6, 'እንደዚህ እጅግ ፈጽሞ ያማረ ነው፤ ንጹሕና ብሩህ ነው።'),
  ('cfb7ce87-770e-5017-ac81-a55c5a11c678', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 7, 7, 'በጽድቅና በእውነት የተታታ ነው፤ በይቅርታና በምሕረትም የተሠራ ነው።'),
  ('3c03546b-f0e5-5be8-a575-f05e71a80703', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 8, 8, 'ከእርሱም የሚፈስስ የሕይወት ውኃ አለ፤ እንደ ፀሐይም እጅግ የነጻ ነው፤ የብርሃን ድንኳንም አለ፤ በኤርሞን ሽቱም የተከበበ ነው።'),
  ('63a602e7-75d9-51af-abd3-0d0495a372ff', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 9, 9, 'በቤቱም ዙሪያ መልኩና መዓዛው ልዩ የሆነ ጣፋጭ የገነት ፍሬ ተተክሏል። በዚያም የወይንና የዘይት ቦታ አለ፤ ፈጽሞም ያማረ ነው፤ የፍሬውም መዓዛ የጣፈጠ ነው።'),
  ('e9d5bc2f-3a04-5b93-a337-a96f939fb420', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 10, 10, 'ሥጋዊ ሰው ወደ እርሱ ቢገባ፥ ከመዓዛውም ጣዕም የተነሣ ከደስታው ብዛት ነፍሱ ከሥጋው በተለየች ነበር።'),
  ('ede92920-0c84-5e63-a684-207a9127b8f7', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 11, 11, '“በዚያም የእግዚአብሔርን ፈቃድ ያደረጉ ደጋግ ነገሥታት ደስ ይላቸዋል፤ ሥራቸውም ቦታቸውም በመንግሥተ ሰማያት በዘለዓለም ሕይወት ቦታ የታወቀ ነው።'),
  ('d43972b1-477d-5722-a576-50a61758683e', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 12, 12, 'በምድር እንደ አለ የመንግሥታቸው ክብር በሰማይ እንደ አለ እንዲሁ በምድር አሳየ፤ በምድርም እንደሚያከብሯቸውና እንደሚሰግዱላቸው በሰማይ ይከብራሉ፤ ከፍ ከፍም ይላሉ፤ በዚህ ዓለምም በጎ ሥራ ቢሠሩ ደስ ይላቸዋል።'),
  ('9c5feeba-ef2f-5da3-a36d-f37a5e071445', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 13, 13, 'እግዚአብሔር በሰጣቸው መንግሥታቸውና ግዛታቸው ክፉ የሆኑ ነገሥታት ግን በእውነትና በሚገባ አይፈርዱም፤ የድሆችንና የጦም አዳሪዎችን ጩኸት ቸል ብለዋልና፥ የተገፋውንና መጻተኛውን፥ አባትና እናት የሞቱበትንም አያድኑም።'),
  ('ee0179a5-738c-57e6-a055-47eba7954f35', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 14, 14, 'ድሆችንና ጦም አዳሪዎችን ከሚቀማቸው እጅ አያድኑአቸውም፤ ከምግባቸው የተራቡትን አያጠግቡም፤ ከመጠጣቸውም የተጠሙትን አያጠጡም፤ ጆሯቸውንም ወደ ድሃው ጩኸት አልመለሱም።'),
  ('723b2d0d-3188-543c-a608-3f703e90d41e', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 15, 15, 'እነርሱንም የጨለማ መጨረሻ ወደ ሆነ ወደ ሲኦል ማደሪያ ይወስዷቸዋል፤ እግዚአብሔር የፈጠራት ታላቋ ዕለት፥ ቍጣውም በደረሰችባቸው ጊዜ ዳዊት በመዝሙሩ “አቤቱ በቍጣህ አትቅሠፈኝ፤ በመቅሠፍትህም አትገሥጸኝ” ብሎ እንደ ተናገረው እንደ ገናንነታቸው ብዛት መጠን ችግራቸውና ውርደታቸው ይበዛል።'),
  ('48448d2f-8e18-5ec6-a630-80c16713d74d', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 16, 16, '“ነገሥታትና መኳንንት በምድር ይህን ዓለም የሚገዙ ሲሆኑ ሕግህን ያልጠበቁ ሰዎችን ይወስዱአቸዋል።'),
  ('13a2c664-9bb7-5da1-aff8-8b4b320182b6', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 17, 17, 'በሰማይ ግን ሁሉን የሚገዛ እግዚአብሔር አለ፤ የሁሉ ነፍስ በእጁ ነው፤ የሁሉም ሕይወት በአፉ ነው፤ ለሚያከብሩት ሰዎችም ክብርን የሚሰጣቸው እርሱ ነው፤ ሁሉን የሚችል ነውና፥ ሁሉንም ይገዛልና የሚወዱትንም ይወድዳቸዋል።'),
  ('90595731-febf-57ab-a381-6b9ecb122ae9', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 18, 18, 'እርሱ የሰማይና የምድር ንጉሥ ልብንና ኵላሊትን ይመረምራል፤ ወደ እርሱም በንጹሕ ልቡ የጸለየውን የጸሎቱን ዋጋ ይሰጠዋል።'),
  ('9df3e1fc-265a-5500-a0b6-316d66f5eee6', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 19, 19, 'በባልቴቶችና በሙት ልጅ ክፉ የሚሠሩ የኀይለኞች ትዕቢትን ያጠፋል።'),
  ('c54dad27-b915-5cea-ae2a-f4a48520ddc0', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 20, 20, 'ይህን መንግሥት የያዝኸው በኀይልህ አይደለም፤ በዚህም ዙፋን ላይ የተቀመጥህ በችሎታህ አይደለም፤ ነገር ግን ሕዝቡን መግዛት ትችል እንደ ሆነ፥ በዚያ ወራት ወገኖቹን ሲገዛ የእግዚአብሔርን ቃልና የሳሙኤልን ቃል ቸል እንደ አለና የአማሌቅን ንጉሥና ሠራዊቱን እንደ አልገደለ እንደ ሳኦል ይፈትንህ ዘንድ ፈቅዶ በመንግሥት ዙፋን ላይ አስቀመጠህ።'),
  ('8babc386-44ca-5644-a8aa-aa8dc707a20c', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 21, 21, 'እግዚአብሔርም ነቢዩ ሳሙኤልን ሔደህ ሕግ በማፍረስና ጣዖቶቹን በማምለክ፥ ለጣዖቱም በመስገጃዎቹ ውስጥ በመስገድ፥ ጥቅም በሌለው በረከሰ ሥራቸውም ሁሉ አሳዝነውኛልና ሳኦልን ወደ አማሌቅ ሀገር ሔደህ ከሰው ጀምሮ እስከ ከብት ድረስ ነገሥታቱንና ሠራዊቶቻቸውን ሁሉ አጥፋ በለው ብሎት ነበርና።'),
  ('795019da-29a3-5e2e-a31f-d4818ebab1aa', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 22, 22, 'ስለዚህም እግዚአብሔርን ባሳዘኑት ጊዜ ያጠፋቸው ዘንድ ላከው።'),
  ('d3f22aff-1a80-5192-a81a-f3e231097eda', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 23, 23, 'እርሱ ግን ንጉሣቸውን አዳነው፤ ብዙ ከብትንም፥ ሴቶችንና ደናግልን፥ ከጐልማሳዎችም መልካማዎችን አዳነ፤ ስለዚህ እግዚአብሔር ነቢዩ ሳሙኤልን እንዲህ አለው፦ ቃሌን አቃሎአልና፥ ትእዛዜንም አልሰማምና ሔደህ መንግሥቱን ክፈላት።'),
  ('44fbeddc-156f-5233-a9eb-70870b4c782a', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 24, 24, 'በእርሱ ፋንታ በእስራኤል ላይ ይነግሥ ዘንድ የዕሤይን ልጅ ዳዊትን ቅባው።'),
  ('a212c854-b6bd-587a-a9aa-92f3842b1caa', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 25, 25, 'በእርሱ ግን አንቆ የሚጥለው ጋኔንን አሠልጥንበት።'),
  ('dcdabc93-9132-5a89-af31-b7a967c0f81b', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 26, 26, 'ፈቃዴን ያደርግ ዘንድ መንግሥትን ብሰጠው እንቢ ብሏልና ፈቃዴን ማድረግ እንቢ ባለም ጊዜ ከክብሩ ሻርሁት፤ አንተ ግን ሄደህ ንገረው፤ እንዲህም በለው፦ በወገኖቹ በእስራኤል ላይ ያነገሠህን፥ በመንግሥት ዙፋን ላይም ያስቀመጠህን እግዚአብሔርን እንዲህ ቸል ትለዋለህን?'),
  ('eeedb24c-69df-5a16-a21b-577b45939cf5', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 27, 27, 'አንተ ግን ይህን ያህል ታላቅ ክብርንና ገናንነትን የሰጠህን እግዚአብሔርን አላወቅህም።'),
  ('b9f82fd2-7d9b-50ad-a100-e7f1f9629a2f', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 28, 28, '“ነቢዩ ሳሙኤልም ወደ ንጉሡ ወደ ሳኦል ሄደ። በማዕድ ተቀምጦ፥ የአማሌቅ ንጉሥ አጋግም በግራው ተቀምጦ ሳለ ወደ እርሱ ገባ።'),
  ('8305530e-aba9-581a-ac9f-7d3cfa71d7dc', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 29, 29, 'ሰውንና እንስሳን ታጠፋ ዘንድ ያዘዘህን እግዚአብሔርን ፈጽመህ ለምን ቸል አልኸው? አለው።'),
  ('fb603a40-750e-5006-af61-8b9b0bf61f52', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 30, 30, 'የዚያን ጊዜም ንጉሡ ፈርቶ ከዙፋኑ ተነሣ፤ የሳሙኤልንም ልብስ ያዘው፤ ሳሙኤልም መመለስን እንቢ አለ፤ የሳሙኤልም ልብስ ተቀደደ።'),
  ('5f7dccfe-8504-5832-a310-a1009fc55608', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 31, 31, 'ሳሙኤልም ሳኦልን፦ እግዚአብሔር መንግሥትህን ከፈላት አለው።'),
  ('05547793-f9d6-5573-a5a9-8ef584fe0551', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 32, 32, 'ዳግመኛም ሳኦል ሳሙኤልን፦ በሕዝቡ ፊት አክብረኝ፤ ይቅር ይለኝም ዘንድ በእግዚአብሔር ፊት ኀጢአቴን አስተስርይልኝ አለው፤ ሳሙኤልም ቃሉን ለመለወጥ እንቢ አለ። የፈጣሪውን እግዚአብሔርን ቃል ፈርትዋልና፥ የሚሞት ንጉሥን ግን አልፈራውምና።'),
  ('7e2235e3-1f43-54a2-a6b9-50ebddc17038', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 33, 33, 'ስለዚህም ነገር ያላመጠውን ሳይውጠው የአማሌቅ ንጉሥ አጋግን ወጋው።'),
  ('07a51cea-fb87-5d7a-a582-72a27f342019', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 34, 34, 'የእግዚአብሔርን ቃል ያፈረሰ ያንም ዝንጉ ርኩስ መንፈስ ያዘው፤ ራሱንም መታው፤ እርሱ ሁሉን የሚያዝዝ ንጉሠ ነገሥት ስለሆነ እግዚአብሔር ዐመፅን ያደረገ ንጉሥን አያፍረውምና።'),
  ('08c24f97-5b9c-575b-a815-be2e63648ad4', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 35, 35, 'የማይፈሩት የነገሥታቱንና የመኳንንቱን ሥልጣን ሁሉ የሚሽር እርሱ የፍጥረቱ ሁሉ ጌታ ነውና እርሱን የሚያዝዘው የለም።'),
  ('3a92898b-6ee4-5adb-a139-492fbda26690', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 36, 36, 'የዳዊት ወገን እየገነነ ይሄዳል፤ የሳኦል ወገን ግን እየተዋረደ ይሄዳል ብሎ እንደ ተናገረ ከሳኦልና ከልጁ መንግሥትን አጠፋ።'),
  ('b7affb78-5966-5599-abf0-7543c0283a8d', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 37, 37, 'ስላሳዘነውና በክፉ ሥራቸው ያሳዘኑትን ወንጀለኞችን ስለ አላጠፋ እግዚአብሔር ተበቅሎ የሳኦልን ወገን አጠፋ። የእግዚአብሔርን ጠላት የማይበቀል ሰው እርሱ የእግዚአብሔር ጠላት ነውና።'),
  ('1bd033c7-a1f8-55b1-adbc-1b05ed10fd39', 'cb434eb7-c4d9-5aea-ae31-36880505412f', '6cbb4f0e-aaf5-5fa5-a94e-3af80ad32d7f', 38, 38, 'መበቀል ሲቻለው፥ ሥልጣንም ሳለው ኀጢአተኛውን የማይበቀል፥ የእግዚአብሔር ሕግ የሌለውንም የማይበቀል ሰው እርሱ በእውነት የእግዚአብሔር ጠላት ነው።'),
  ('571fc8a9-5731-523c-adaa-508ab3f49e38', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 1, 1, '“አንተ ንጉሥም ብትሆን፥ ገዥም ብትሆን አንተ ምንድን ነህ? የፈጠረህ እግዚአብሔር አይደለምን'),
  ('3b3d88ff-4d55-588c-a26d-432fc8428506', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 2, 2, 'ፈቃዱን ታደርግ ዘንድ፥ በትእዛዙም ትሔድ ዘንድ፥ ፍርዱንም ትፈራ ዘንድ ካለመኖር ወደ መኖር አመጣህ፤ አንተ ባሮችህን እንደምትቈጣቸው፥ በላያቸውም እንደ ሠለጠንህ እንደዚሁም ሁሉ አንተንም የሚቈጣህ፥ በላይህም የሠለጠነ አለ።'),
  ('94f5176b-2678-5bb7-ab3b-99eba465a527', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 3, 3, 'አንተ ኀጢአት የሠሩ ሰዎችን ያለ ርኅራኄ እንደምትመታ እንደዚሁም ሁሉ አንተንም የሚመታህ፥ እስከ ዘለዓለም ድረስ መውጫ ወደሌለበት ፍርድም የሚጨምርህ እግዚአብሔር አለ።'),
  ('8a84ff3e-6dd1-5051-acec-1f27fa723d9f', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 4, 4, 'ያልተገዛልህን፥ እጅ መንሻም ያላመጣልህን አንተ እንደምትገርፈው አንተ ለእግዚአብሔር ለምን እጅ መንሻ አታገባም?'),
  ('7ab195b0-1a3b-5320-a57e-1fcc38d86804', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 5, 5, 'አንተን ይፈሩህ ዘንድ እንደምትወድ አምላክህን እግዚአብሔርን ለምን አትፈራውም? ሕዝቡንና መንጋውን በእውነት ትጠብቅ ዘንድ የፈጠረህና በፍጥረቱ ሁሉ ላይ ያነገሠህ እርሱ ነውና።'),
  ('d22bac49-4f7a-5318-a86f-ab9075783aa7', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 6, 6, '“እግዚአብሔር እንደ ሾመህ በሚገባና በእውነት ፍረድ እንጂ ለታላቅና ለታናሽ ፊት አታድላ፤ ያለ እርሱ ማንን ትፈራለህ? መንገዱንና ትእዛዙን ጠብቅ።'),
  ('3505ec73-a6f5-5543-a1fc-aae0be05833b', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 7, 7, 'እሳትንና ውኃን አቀረብኩልህ፤ እጅህን ወደ ወደድኸው ጨምር ብሎ ሙሴ የእስራኤልን ልጆች እንዳዘዛቸው ወደ ቀኝም ወደ ግራም ፈቀቅ አትበል።'),
  ('881e6e86-83e6-5a0d-ad6d-f1f01fdf2a43', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 8, 8, 'ቃሉን ትሰማ ዘንድ፥ ትእዛዙንም ታደርግ ዘንድ የምነግርህን ቃሉን ስማ፤ በባሕር ማዶ፥ ወይም በጥልቁ ማዶ፥ ወይም በወንዙ ማዶ ቃሉ አለች፤ አያት ዘንድ፥ ቃሉንም እሰማ ዘንድ፥ የእግዚአብሔርንም ትእዛዙን አደርግ ዘንድ ማን ያመጣልኛል? እንዳትል፥'),
  ('a3927f75-e7cb-5985-a01a-53f76679c209', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 9, 9, 'ዳግመኛም ሰምቼ አደርጋት ዘንድ ወደ ሰማይ ወጥቶ ያቺን የእግዚአብሔርን ቃል ማን ያወርድልኛል? እንዳትል እነሆ ቃሉ በአፍህ ቅርብ ነው። በእጅህም ውስጥ ነው።'),
  ('d679bcfa-ec29-52e8-a715-d6e012730b4b', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 10, 10, 'መጽሐፉንም ካልሰማኸው አምላክህ እግዚአብሔርን አልሰማኸውም፤ ቃሉንም ካልጠበቅህ እርሱን አልወደድኸውም፤ ትእዛዙንም አላደረግህም።'),
  ('da35d9f8-4db1-56ef-a08b-d133699837f7', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 11, 11, 'አንተም ትእዛዙን ካልወደድህ በእውነትም ትጠብቃቸው ዘንድ ከወገኖችህ ሁሉ ለይቶ ያከበረህንና ያገነነህን ፈቃድ ካላደረግህ ለዘለዓለም ወደ ፍርድ ትገባለህ።'),
  ('f27f39da-f4ff-58d0-a335-ef062d112a8b', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 12, 12, 'የፈጠረህን የአምላክህን ስም እንድታስብ በሕዝቡ ሁሉ ላይ የበላይና አለቃ አደረገህ። በእውነትና በሚገባም ወገኖቹን ትገዛ ዘንድ ሰጠህ'),
  ('39b3e8ce-61ad-5ba2-a47e-7ddbe05e50c3', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 13, 13, 'አንተን ከበደሉህ ሰዎችም የምትቀጣቸው አሉ፤ የእግዚአብሔርን መንገድ እያሰብህ፥ ልቡናህንም እያቀናህና በሚገባ እየፈረድህ የምትምረውም አለ።'),
  ('57b41e85-d36d-5f5f-a214-eca4ebce989d', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 14, 14, 'በፊትህም በተከራከሩ ጊዜ ፊት አይተህ አታድላ፤ ምድር ሁለንተናዋ ያንተ ገንዘብ ናትና ኀጢአተኛውን ሰው ትምረው፥ ንጹሑንም ሰው ትበድለው ዘንድ መማለጃ አትቀበል።'),
  ('98ccfaa2-15b7-565b-a164-fd42bc491b6b', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 15, 15, '“ፈቃዱንም ካደረግህ በምድር ላይ ዕድሜህን ያበዛልሃል፤ ብታሳዝነው ግን ዕድሜህን ያሳንሰዋል።'),
  ('5d129394-bc5f-55b7-a514-e43f264e6def', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 16, 16, 'ከሞት እንደምትነሣ፥ በጎም ቢሆን፥ ክፉም ቢሆን በሠራኸው ሥራ ሁሉ በፊቱ ቁመህ እንደምትመረመር አስብ።'),
  ('76361c46-c125-50ac-adf4-029fd2b7bee9', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 17, 17, 'በጎ ሥራ ብትሠራ በደጋግ ነገሥታት ማደሪያ በብርሃን ቤቶች ትኖራለህ። ክፉ ሥራ ብትሠራ ግን በክፉዎች ነገሥታት ማደሪያ ትኖራለህ።'),
  ('e7231ba2-faf6-59e5-a52f-682b419cac2c', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 18, 18, 'እግዚአብሔር የጌትነትህን ሥልጣን አያፍርም፤ አንተ ግን የመፈራትህን ገናንነት፥ የአርበኞችህንም ሽልማት፥ የተሰቀለ የጦር መሣሪያህንም ባየህ ጊዜ፥ ፈረሶችህንም፥ ከሥልጣንህ በታች ያሉ ጭፍሮችህንም፥ መለከት የሚነፉትንና በፊትህም በበገና የሚጫወቱትን ሰዎች በአየህ ጊዜ፥'),
  ('1c4d213f-cb33-5895-aa2c-6fb9393c7c33', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 19, 19, 'አንተ ይኽንን ሁሉ በአየህ ጊዜ ሕሊናህን ከፍ ከፍ ታደርጋለህ፤ አንገትህንም ታደነድናለህ፤ ይኽን ሁሉ ክብር የሰጠህንም አታስበውም፤ ተው ባለህ ጊዜ አንተ የምትተወው አይደለህምን?'),
  ('92b0bc98-3df5-5e3d-a2dd-437ce683449d', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 20, 20, 'የሾመህን ሹመትም ፈጽመህ ቸል ብለሃልና ክብርህን ለሌላ ይሰጠዋል።'),
  ('9c05e1bd-e12a-5db2-af2f-009419f7357c', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 21, 21, 'ድንገት ሞት ይመጣብሃልና፥ በትንሣኤም ጊዜ ፍርድ ይደረጋልና፥ የሰውም ሥራ ሁሉ ይመረመራልና በዚያ ይመራመርሃል፤ ይቈጣጠርሃልም፤ ይፈርድብሃልም።'),
  ('c8bc5520-8f4e-5ddf-af0d-c0080b03b7a9', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 22, 22, 'የምድርን ነገሥታትም የሚያከብራቸው የለም፤ እርሱ የእውነት ዳኛ ስለሆነ በፍርድ ጊዜ ድሃና ባለጸጋ በአንድነት ይቆማሉና። የምድር መኳንንት የሚመኩበት ዘውዳቸው ይወድቃል።'),
  ('9e2a70a1-878b-5fe4-a723-722494d5d458', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 23, 23, '“ፍርድ የተዘጋጀ ነው፤ ነፍስም ትንቀጠቀጣለች፤ መጻሕፍትም ይገለጣሉ፤ የሰዎችም ሥራ ይገለጣል፤ የሚሰወርም የለም።'),
  ('9dc58122-6de4-5f7e-ac34-0bfea63b3f8f', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 24, 24, 'ሴት ለመውለድ በደረሰች ጊዜ፥ በሆዷም ያለ ፅንስ ለመወለድ በደረሰ ጊዜ ማኅፀኗን ለመከልከል እንደማትችል ምድር በሙታን ትንሣኤ ጊዜ በርሷ ላይ ያለ አደራዋን ትመልሳለች።'),
  ('573cc0e8-b6e3-58a7-a0d9-22a30384f957', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 25, 25, 'ወይስ ደመናዎች እግዚአብሔር ወዳዘዛቸው ቦታ ወስደው እንዳያዘንሙ ዝናምን መቋጠር ይችላሉን? እንደዚሁም የእግዚአብሔር ቃል ሁሉን ካለመኖር ወደ መኖር አምጥቶ ፈጥሮታልና፥ ዳግመኛም የእግዚአብሔር ቃል ሁሉን ወደ መቃብር አግብቶታልና የትንሣኤ ጊዜ ከደረሰ በኋላ የሞቱ ሰዎች እንዳይነሡ ማድረግ አይቻልም።'),
  ('48b83260-042f-5543-a706-2cf463a1cb68', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 26, 26, 'ዳግመኛም ከእግዚአብሔር አፍ በሚወጣ ቃል ነው እንጂ ሰው የሚድን በእህል ብቻ አይደለም ብሎ ሙሴን እንደ ተናገረ የእግዚአብሔር ቃል ሰውን ሁሉ ከመቃብር ያስነሣዋል።'),
  ('89a1135d-b0a9-54a4-ab23-275aa657bdc6', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 27, 27, 'እነሆ የሞቱ ሰዎች በእግዚአብሔር ቃል ሕያዋን እንደሚሆኑ ታወቀ።'),
  ('f3e6ecb9-237c-5ecb-a3d1-f48476e70582', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 28, 28, 'ዳግመኛም ስለ ነገሥታትና መኳንንት፥ ፈቃዱንም ስለሚያደርጉ ሰዎች እግዚአብሔር በዳግም ሕግ እንዲህ አለ፦ የሚቈጠሩበት ቀን ደርሷልና በፍርድ ቀን እግራቸው በሚሰናከልበት ጊዜ እበቀላቸዋለሁ።'),
  ('8029c279-49ed-515f-a6c7-03b2c0d4bf57', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 29, 29, '“ዳግመኛም የእግዚአብሔርን ፍርድ የማያውቁ ሰዎችን እግዚአብሔር እንዲህ አላቸው፦ እኔ እግዚአብሔር እንደ ሆንሁ ዕወቁ፤ እኔ እገድላለሁ፥ አድናለሁም።'),
  ('46158ebd-91c4-5589-a5ae-76dde490a83d', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 30, 30, 'እቀሥፋለሁ፤ ይቅርም እላለሁ፤ ወደ ሲኦል አወርዳለሁ፤ ዳግመኛም ወደ ሰማይ አወጣለሁ፤ ከእጄም የሚያመልጥ የለም።'),
  ('308acca7-7332-56fd-aa04-bed41193cf19', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 31, 31, 'ሕጉን ስላልጠበቁ ነገሥታትና መኳንንት እግዚአብሔር እንዲህ አለ፦ ምድራዊ መንግሥት ኀላፊ ነውና፥ ከጧት እስከ ማታም ድረስ ያልፋልና ወደ ዘለዓለማዊው መንግሥቴ ትገቡ ዘንድ ሕጌንና ሥርዐቴን ጠብቁ።'),
  ('8c1e5752-1a45-5d95-a576-d271d0679116', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 32, 32, 'የእግዚአብሔር ጥሪው ለክብርም፥ ለአሣርም ነውና ይህን ያዋርዳል፤ ያንም ያከብራል።'),
  ('2c710ee2-417d-5be2-a86b-cafb89f57d7a', '475d609a-e32e-5002-a274-a4eeb407d5b6', '08be3b6b-76e1-55d8-a9d8-705375b4b1f0', 33, 33, 'ፈቃዱን ያላደረገውን ይሽረዋል፤ ፈቃዱን ያደረገውንም ይሾመዋል።'),
  ('5a839157-81ac-5247-a7b9-b1994b63d8f4', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 1, 1, '“ስለ ሙታን ትንሣኤም ስማኝ ልንገርህ፤ ዛፎች ይተከላሉ፤ ቅርንጫፎችንም ያወጣሉ፤ ወይንም ሐረግ ያወጣል፤ እግዚአብሔር ፍሬውን ካለመኖር ያመጣዋልና ከእርሱ የወይን ጠጅ ይጥላሉ።'),
  ('4bb36af9-30b4-5ae6-ae17-b3053bf05e5a', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 2, 2, 'እስኪ ተመልከት፤ ያች የተከልሃት ዛፍ ታናሽ ነበረች። ዛሬ ግን ጫፎችን፥ ቅጠልንና ፍሬን አውጥታለች።'),
  ('e957824d-c118-5ace-a11b-a9feb2ebcd6b', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 3, 3, 'እግዚአብሔርም ከሁለት ጡቶች ከውኃና ከመሬት ሥርዋን ያጠጣል።'),
  ('a7b11f46-1a87-512c-a163-1f2d5f68cd5b', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 4, 4, 'እንጨቶችዋን ግን ከነፋስና ከፀሐይ ይመግባቸዋል፤ ሥር ለቅጠል ውኃ ታጠጣለች፤ መሬትም ለእንጨቶች ጽናትን ትሰጣለች።'),
  ('e4a92f8e-6a16-5489-a2fa-bd1fa9ca3012', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 5, 5, 'እግዚአብሔር የፈጠረው ነፋስም በመካከላቸው ፍሬን ይሰጣል። የሞቱ ሰዎችም ትንሣኤ እንደዚሁ ነው።'),
  ('257f24f9-d355-5df6-aa7f-6f08a7f9e110', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 6, 6, '“ነፍስ ከሥጋ በተለየች ጊዜ እየራሱ ሂዷልና ከውኃና ከመሬት፥ ከእሳትና ከነፋስ፥ ከአራቱ ማዕዘናት ነፍሳትን ሰብስብ አለ።'),
  ('a04b3f32-880b-5ea8-a7eb-40d29ff0d5f5', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 7, 7, 'የመሬት ባሕርይ ግን በራስዋ ጸናች፤ ዐመድም ሆነች፤ የውኃ ባሕርይም በራሷ ጸናች፤ ጠልም ሆነች።'),
  ('11fb090b-a518-542d-abe9-d6d5aa87af2d', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 8, 8, 'የነፋስ ባሕርይም በራስዋ ጸናች፤ ነፋስም ሆነች፤ የእሳት ባሕርይም በራስዋ ጸናች፤ የሚሞቅ እሳትም ሆነች።'),
  ('c2e4411c-b522-5655-ac3d-847e2fdac5e2', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 9, 9, 'እግዚአብሔር የፈጠራት ነፍስ ግን ወደ ፈጣሪዋ እጅ ተመለሰች፤ በወደደም ጊዜ ይመልሳታልና በወደደው ቦታ ያኖራታል።'),
  ('e4a03ab8-3b29-52d9-ae37-b9cf84904743', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 10, 10, 'የጻድቃንን ነፍሳት በብርሃን ቤት ያኖራቸዋል፤ የኃጥኣንን ነፍሳት ግን ያወጣቸው ዘንድ እስከ ወደደበት ጊዜ ድረስ በጨለማ ቤት ያኖራቸዋል።'),
  ('a80db303-edbb-5a48-abf1-99cef5057d55', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 11, 11, '“ነቢዩ ሕዝቅኤልንም እንዲህ አለው፦ ይሰበሰቡና አንድ አካል ይሆኑ ዘንድ ከአራቱ ማዕዘን ጥራ።'),
  ('0c25026a-7a93-5d4c-a57b-a49dc6a708a0', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 12, 12, 'እንዲህም ብሎ ባንድ ቃል በተናገረ ጊዜ ከአራቱ ማዕዘን ተሰበሰቡ።'),
  ('89c2d52e-a3b7-5bbc-aad8-7ae7193c8b38', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 13, 13, 'የውኃ ባሕርይም ጠልን አመጣ፤ ዳግመኛም የእሳት ባሕርይ ሙቀትን አመጣ።'),
  ('95947e46-77fc-54b3-af8e-0addffd4922c', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 14, 14, 'የመሬት ባሕርይም ዳግመኛ መሬትን አመጣ፤ የነፋስ ባሕርይም እስትንፋስን አመጣ።'),
  ('e3de1462-4a90-5ee0-a1c4-d7f54739cf70', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 15, 15, 'እግዚአብሔርም ነፍስን ካኖረበት ከማደሪያዋ አመጣ፤ በአንድ ቃል ተሰበሰቡ፤ ትንሣኤም ሆነ።'),
  ('1d8373c6-5767-57ee-a699-7be5e771f4d9', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 16, 16, '“ዳግመኛም በአንተ ዘንድ ያለ ምሳሌን አሳይሃለሁ፤ ቀኑ ይመሻል፤ ትተኛለህም፤ ሌሊቱ ይነጋል፤ ከመኝታህም ትነሣለህ፤ አንተ ግን በተኛህ ጊዜ የሞትህ ነህ።'),
  ('fcaec7be-488b-5ac0-a0b4-553564a0dc51', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 17, 17, 'በነቃህም ጊዜ የትንሣኤ ምሳሌ ነው፤ ሌሊቱ ግን ሁለንተናው ጨለማ የሆነ የዚህ ዓለም ምሳሌ ነው። ዓለም ሁሉ ይተኛበታል፤ የሌሊት ጨለማ ሸፍኖአቸዋልና።'),
  ('9b69130d-bbc7-57df-ada8-f7c6b3158db8', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 18, 18, 'ጨለማ የሚወገድበት፥ በዓለሙም ሁሉ ብርሃን የሚሆንበት፥ ሰውም ተነሥቶ ወደ ሥራው የሚሠማራበት የጧት ብርሃን ግን የሙታን ትንሣኤ ምሳሌ ነው።'),
  ('e5fd2581-7637-5bbf-ac37-46846d79bcde', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 19, 19, 'ይቺ የዓለም መታደስና የሙታን ትንሣኤ እንደዚህ ናት፤ ይህ ዓለም በዚህ ሌሊት አምሳል ኀላፊ ነውና።'),
  ('2be501be-942e-5cbe-a2f9-0e97a7e78193', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 20, 20, '“ዳዊትም ምሳሌውን በፀሐይ አኖረ ብሎ እንደ ተናገረ ፀሐይ በወጣና በአበራ ጊዜ የዚህ ዓለም ምሳሌው ነው።'),
  ('d821649a-f7f3-5867-a5be-02552db0522e', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 21, 21, 'ዛሬ በዚህ ዓለም እንደሚያበራው ፀሐይ እርሱ እግዚአብሔር በሚመጣ ጊዜ ለሐዲሲቱ ዓለም ያበራላታል፤ እንደ ፀሐይ ያበራል፤ የማይጠልቅ ፀሐይ፥ የማይጠፋም ፋና እኔ ነኝ ብሏልና እርሱ እግዚአብሔር ብርሃንዋ ነው።'),
  ('2cc0fd96-566c-5fbc-a493-284471befbc7', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 22, 22, 'ዳግመኛም የሞቱትን ሰዎች እንደ ዐይን ጥቅሻ ያስነሣቸዋል፤ ዳግመኛም ከምትዘራው፥ አንተም በሕይወት ከምትኖርበት ከምግብህ አንዲት ምሳሌ አመጣልሃለሁ፤ የስንዴም ቅንጣት ቢሆን፥ የገብስም ቅንጣት ቢሆን፥ የምስርም ቅንጣት ቢሆን በምድር የሚዘራ የሰው ተግባር ሁሉ ካልፈረሰ የሚበቅል የለም።'),
  ('52d2b938-ffd4-518a-a4e5-688b9dd51e30', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 23, 23, 'እንደምታየው እንደ ሰው ሥጋ ሁሉ በሚፈርስበት ጊዜ ፍሬው ከገለባው ጋር በመሬት ይበላል።'),
  ('1c597f7b-fce2-5966-ab06-095a12fe6d7b', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 24, 24, 'ፍሬውም በተበላ ጊዜ የቅንጣት ሰባተኛ እጅ ያህል ሆኖ ይበቅላል፤ እግዚአብሔርም እንደ ወደደ የሕይወት ነፋስን ይሰጣል፤ ሥርም በምድር ውስጥ ትበቅላለች፤ ቅጠልንም በምድር ላይ ታወጣለች።'),
  ('7111ffe3-1fe9-5b92-a1d2-26940804b635', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 25, 25, 'እስቲ ተመልከት፤ እርሷ ካልፈረሰች መብቀል አትችልም፤ ከበቀለች በኋላ ግን ብዙ ዝርዝር ታወጣለች።'),
  ('cd1562c7-ca17-5961-a099-68e62091c140', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 26, 26, 'ላደገው ለዚያ ለዝርዝሩም ከእግዚአብሔር ፍሬ ይሰጠዋል፤ ፍሬውንም ገለባ ያለብሰዋል።'),
  ('b82b1a07-1bc5-5335-a699-34e7eb58839c', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 27, 27, 'የዘራኸው ዘር ቅንጣቱ እንደበዛ መጠን እይ እንጂ ቅጠሉ፥ ብርዑ፥ ገለባውና ምርቁ ግን አይቈጠርልህም።'),
  ('31e33428-408b-5eef-ae09-f43edefab4c6', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 28, 28, '“ሰነፍ አትሁን፤ ዘርህንም እንደ በዛ እይ፤ እንደዚሁም ሁሉ የሙታንን ትንሣኤ፥ እንደ ሥራቸውም እንደሚከፈላቸው አስብ።'),
  ('874cad88-169a-52ae-a126-59371d7575cc', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 29, 29, 'ዳግመኛም ዘር ወደ ሌላ ዘር እንደማይለወጥ ስማኝ፤ ልንገርህ፤ ስንዴ ብትዘራ ገብስ ትሰበስባለህን? ከሙን ብትዘራ ተልባ ትሰበስባለህን?'),
  ('c3152183-cd8e-5114-a374-1bb1c4ea0d38', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 30, 30, 'ከተክልስ ወገን በለስ ብትተክል በውኑ ለውዝ ሆኖ ይበቅልልሃልን? ገውዝስ ብትተክል ወይን ሆኖ ይበቅልልሃልን።'),
  ('dc3b7570-17ad-574d-a026-eb560e84a879', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 31, 31, 'ጣፋጭ ፍሬ ብትተክል የመረረ ሆኖ ይበቅልልሃልን? የመረረውንስ ፍሬ ብትተክል የጣፈጠ ሆኖ ይበቅልልሃልን።'),
  ('5ffcce71-c56d-5468-aab9-d42ac1f9e234', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 32, 32, 'እንደዚሁስ ሁሉ ኀጢአተኛ ቢሞት በትንሣኤ ጊዜ ጻድቅ መሆን ይችላልን? ጻድቅስ ቢሞት በትንሣኤ ጊዜ ኃጥእ መሆን ይችላልን? ሁሉም እንደ ሥራው ይከፈለዋል፤ እንደ ሥራው ፍሬ፥ እንደ እጁም ሥራ ይከፈለዋል እንጂ፥ በሌላ ኀጢአት የሚፈረድበት የለም።'),
  ('81a89980-166e-522b-aff4-1b35be071a18', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 33, 33, 'የሊባኖስ ዛፍ ይተከላል፤ ረጃጅምና ታላላቅ ቅርንጫፎችንም ያወጣል፤ ይደርቅና ይረግፋል እንጂ፥ የአርሞንኤም ጠል ካልዘነመበት ቅጠሉ አይለመልምም።'),
  ('5723c74e-54d4-5469-acdd-5b888c61ec46', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 34, 34, 'ዝግባውም የክረምት ዝናም በእርሱ ካልወረደ ከሥሩ ይነቀላል።'),
  ('9f968446-91f0-5167-ae47-a777840ad2e9', '94823614-3fe0-553d-a049-1829c391e03c', '250291a0-e35f-5225-a2ab-c6bc433aba1e', 35, 35, 'እንደዚሁም ሁሉ ከእግዚአብሔር የሕይወት ጠል ካልወረደላቸው ሙታን አይነሡም።'),
  ('a789bc96-19b8-5229-acf0-7d07dfe9ae90', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 1, 1, '“የጌላቡሄ ሸለቆዎችና የሊባኖስ ተራሮች ከእግዚአብሔር ዘንድ የምሕረት ዝናም ካልዘነመላቸው ለእንስሳዎችና ለአውሬዎች ሣርን አያበቅሉም።'),
  ('560568ef-b861-5d39-a4d1-05a2ed7b112b', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 2, 2, 'የገለዓድ ተራራዎችና የኤላም ሸለቆዎች ለሚሠማሩ ለፍየሎችና ለበጎች፥ ለዱር እንስሳት ለፌቆና ለቶራትም፥ ለዋሊያዎችም ልምላሜን አይሰጡም።'),
  ('975aa96b-d09b-5f4d-a2f1-171afe4deb03', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 3, 3, 'እንደዚሁም ክሕደትንና ስሕተትን አስቀድሞ ገንዘብ ያደረጓት ከሓዲዎችና መናፍቃን ከእግዚአብሔር የምሕረት ጠል ካልወረደላቸው ሙታን አይነሡም፤ ጣዖት የሚያመልኩና ሥር የሚምሱ፥ ነገር ሠርተው የሚያጣሉ፥ ቆጵሮስና ዲማሶ፥'),
  ('301907d4-f596-5809-a93f-7d750c19dbb6', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 4, 4, 'ሥር የሚምሱ፥ ጥንቆላንና ሥራይን የሚያደርጉ፥ ሰውንም የሚያጋድሉ፥'),
  ('090ad6e2-f149-5b6e-ade3-7574f8a8e772', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 5, 5, 'ከሕግም ወጥተው የሚሰስኑ፥ በጣዖታቸውም የሚታመኑ የአቴናና የሜዶን ሰዎች፥ በመሰንቆና በከበሮ፥ በበገናም የሚጫወቱላቸውና የሚዘፍኑላቸውም፥'),
  ('95292961-8b91-58dd-a30d-ffed36c858b2', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 6, 6, 'በጣዖታቸው የሚስቱ፥ በእጃቸውም ሥራ የሚሰስኑ፥ በትንሣኤ ጊዜ በፍርድ ቀን ራሳቸውን የማያድኑና የሚፈረድባቸው እነዚህ ናቸው።'),
  ('6a2d6883-165e-5c42-ac3f-2d8bd43caeaa', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 7, 7, '“አንተ ሰነፍና ልበ ባካና ሙታን የማይነሡ ይመስልሃልን?'),
  ('aafd187f-1384-5682-a07c-042e5ba97f90', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 8, 8, 'በሙታን ትንሣኤ በመላእክት አለቃ በቅዱስ ሚካኤል አፍ መለከት በሚነፋ ጊዜ በዚያ እንደ አንቀላፋህ አትቀርምና እንዲህ አታስብ።'),
  ('5b71d647-ec68-5971-a33c-def3c1591dd9', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 9, 9, 'ተራሮችና ኮረብቶች ዝቅ ይላሉ፤ ወንዞችና ጥልቆች ይስተካከላሉ፤ ጥርጊያ ጎዳናም ይሆናሉ።'),
  ('3b66c1c9-701a-5d46-acdc-a6e847f1a30e', '0cd471bd-ac65-5a6d-a82b-60532b593e02', '3f65b409-0482-508d-a66a-557ba001197e', 10, 10, 'ለሥጋ ለባሽም ሁሉ ትንሣኤ ይሆናል።'),
  ('00a58153-c53f-5081-af75-c46e82c00f80', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 1, 1, '“እንዲህ ካልሆነ ግን የቀደሙ አባቶች ከአዳም ጀምሮ ከአቤልና ከሴት፥ ከኖኅና ከሴም፥ ከአብርሃምና ከይስሐቅ፥ ከያዕቆብና ከዮሴፍ፥ ከሙሴና ከአሮን ጀምሮ ከአባቶቻቸው መቃብር ውጭ ይቀበሩ ዘንድ ያልወደዱ ለምንድን ነው?'),
  ('9f6076c2-1bd4-5d8f-ae3a-30c89d0d0eaa', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 2, 2, 'በትንሣኤ ጊዜ ከዘመዶቻቸው ጋር በአንድነት እንዲነሡ አይደለምን? አጥንታቸውስ ጣዖት ከሚያመልኩ ከክፉዎች፥ ከጣዖት አምላኪዎችና ከአረማውያንም አጥንቶች ጋራ እንዳይቈጠሩ አይደለምን?'),
  ('c42098c1-fef4-56b8-a527-fabac07d91e4', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 3, 3, 'አንተ ግን እልፍ እልፍ ሆነው በአንድ መቃብር የሚቀበሩ፥ አጥንታቸው የሚበሰብስ ሙታን ከሞቱ በኋላ እንዴት ይነሣሉ? እያልህ ልቡናህን አታስት።'),
  ('5886d6a6-226a-5bde-a7da-7f7110db06f1', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 4, 4, '“ወደ መቃብርም በምታይ ጊዜ እፍኝ ሙሉ መሬት አይገኝም፤ የሞቱ ሰዎች እንዴት ይነሣሉ? እያልህ በልቡናህ ስንፍና ይህን ትናገራለህ።'),
  ('0cab5e35-e490-5bc9-aa7a-94c21839eebc', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 5, 5, 'አንተ የዘራኸው ዘር አይበቅልም ትላለህን? አንተ የዘራኸው ዘር ስንኳ ይበቅላል።'),
  ('fb55fc49-3119-5296-a174-42837861728f', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 6, 6, 'እንደዚሁም ሁሉ እግዚአብሔር የዘራቸው ነፍሳት ፈጥነው ይነሣሉ፤ እርሱ ሰውን በእውነቱ ካለመኖር ወደ መኖር አምጥቶታልና በሕይወት ሰጪ ቃሉ እነርሱን ማስነሣቱን አያዘገይም።'),
  ('740acab6-0b85-5cf3-a7a1-00a7464ee53d', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 7, 7, 'ዳግመኛም ከመኖር ወደ ሞት ይመልሰዋል፤ ዳግመኛም ከሞት ወደ መኖር ይመልሰዋል።'),
  ('5d3d22e3-5dfe-5d49-a772-6653659752c6', 'e7ad7683-1289-521f-a6bc-a82c75d70b3d', '65c4984f-da1e-5e57-a3c4-0cbb45a5851f', 8, 8, 'እግዚአብሔር ሕይወት መስጠትና ማስነሣት ይችላል።”'),
  ('a7be08af-d424-58a5-a087-67c474cd32d0', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 1, 1, 'አርሞንና ቅጥሮችዋ ወደቁ፤ እግዚአብሔርም እንደ ክፋታቸውና በእጃቸው እንደ ሠሩት ሥራ ከፍሎአቸዋልና በዛብሎንና በኤዶምያስ ጣዖቶችን የሚያመልኩ ያንጊዜ ይዋረዳሉ፤ በሕፃንነታቸው በሠሩት እስከ እርጅናም ድረስ ባልተዉት ስለ ጣዖታቸውና ስለ ክፋታቸው የሚፈርድባቸው ቀርቧልና ጢሮስና ሲዶና ያለቅሳሉ።'),
  ('4edb1cdb-95d6-5f7a-a5cf-690f7c20fa1d', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 2, 2, 'ስለዚህም መዳራትንና ርኩሰትን፥ ዝሙትንም ስለ ሠሩ፥ ጣዖትንም ስለ አመለኩ እግዚአብሔር ይበቀላቸዋል። የይሁዳም ሴቶች ልጆች በፈጣሪያቸው በእግዚአብሔር ትእዛዝ አልጸኑምና ይዋረዳሉ።'),
  ('302b1d9a-0cba-5d29-a186-a0bf8b270a82', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 3, 3, 'እንደ እርሷም በትንሣኤ ጊዜ የኢየሩሳሌም ውርደቷ ይገለጣል፤ በእግዚአብሔር ሕግና ፍርድ አልሔደችምና፤ ነገር ግን በደስታና ጻድቃንን በመግደል ኖረች።'),
  ('e443783d-c400-5e6e-a5ec-1661ea1ccf4f', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 4, 4, 'ያንጊዜ እግዚአብሔር በጥበቡ ብርሃን ይመራመራታል፥ በሕፃንነትዋ ወራት በሠራችው ሁሉ፥ በወጣትነቷም ወራት እስከ እርጅናዋ በአልተወችው ክፋቷ ሁሉ ይበቀላታል።'),
  ('6708968a-5a11-5a24-a83e-1d742677e2b9', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 5, 5, 'በልማዳቸው እንደ ኖሩና የእግዚአብሔርን ትእዛዝ እንቢ እንደ አሉ፥ በትንሣኤም ጊዜ እንደሚበቀላቸው፥ እንደ ቀደሙት አባቶችዋ ወደ መቃብር ትገባለች፤ ዐመድም ትሆናለች።'),
  ('491bcd9c-fc65-5f10-a594-91a1bb6b7870', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 6, 6, 'ሙሴ ስለ እነርሱ እንዲህ ብሎአልና፥ “የወይናቸው ቦታ እንደ ሰዶም የወይን ቦታ ሆነ።'),
  ('9dbcf8d7-d424-57a2-a3f2-5eea97e3f9a4', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 7, 7, 'ሐረጋቸውም ከገሞራ ነው፤ ዘለላቸውም የሐሞት ዘለላ ነው፤ ፍሬያቸውም መራራ ነው።'),
  ('c320fef2-a372-53de-ac0b-aa0582316dd3', '15e57032-f083-5989-a1fd-d5f84e9062ba', 'a5d68612-c5c1-57c7-a7b3-ac0e6e2c2a4e', 8, 8, 'ወይናቸውም የዕባብ መርዝ ነው፥ ያውም የሚገድል የእፉኝት መርዝ ነው።”'),
  ('227bde03-b756-5a87-a8ac-571607e0a599', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 1, 1, 'የኢየሩሳሌም ልጅ! በነቢዩ የተጻፈው ውርደትሽ ይህ ነው፤ የኢየሩሳሌም ልጅ! ሥራሽና በደልሽ እንደ ሰዶምና ገሞራ ሰዎች ሥራና በደል ነውና።'),
  ('1e920c8d-c7b4-5666-ab79-b06992f789b6', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 2, 2, 'ውርደትሽም እንደ ገሞራና እንደ ሰዶም ነው፤ የወይናቸው ቦታ በዝሙትና በትዕቢት ተተከለ።'),
  ('ed913819-536b-50f9-a5a0-ee7c6503dd8c', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 3, 3, 'ከዝሙትና ትዕቢት፥ ከዐመፅና በደል፥ ከቅሚያና ደም ከማፍሰስ፥ የፈጣሪያቸው የእግዚአብሔርንም ስም ከመርሳት በቀር የትሕትናና የምሕረት ዝናም አልዘነመላቸውም።'),
  ('d591bd19-ea8e-5486-ad98-eab7132302d9', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 4, 4, 'ከክፉ ሥራቸውና ከጣዖታቸው በቀር ፈጣሪያቸውን እግዚአብሔርንም አላወቁትም፤ በእጃቸውም ሥራ ደስ ይላቸዋል፤ ከከብትና ከወንድ ጋር ይሰስናሉ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('42c9ae74-5a36-508f-a9cd-189385c5ff8e', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 5, 5, 'እንዳያዩ ዐይኖቻቸው ታውረዋልና፥ እንዳይሰሙም የእግዚአብሔርን ፈቃዱንና የሚወደውን እንዳያደርጉ ጆሯቸው ደንቁሯልና፥ በሥራቸው እግዚአብሔርን አያውቁትም፤ እነርሱ የሰዶም የወይን ቦታ ናቸው። ወገናቸው የጣፈጠ ፍሬን የማያፈሩ የገሞራ ወይን ሐረግም ናቸው።'),
  ('a8d83a71-d45c-5eb8-a162-c581969c5336', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 6, 6, 'ከተተከለበት ቀን ጀምሮ በርግማን ተተክሎአልና፥ አበቃቀሉም በጥፋት ዘመን ሆኗልና ወይናቸውን በጨመቁት ጊዜ የሚገድል መርዝ ይሆናል።'),
  ('39fb863e-eeeb-576a-a8f9-526656be2f03', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 7, 7, 'የወይናቸው ተክል የሲዖልን ውኃ ጠጥቶአልና፥ ሐረጋቸውም በሐሩር ነፋስ ጸንቶአልና ሁልጊዜ ለወይናቸው ሐረግ መልካምነት የለውም።'),
  ('0c36443d-9066-561a-af1f-fe01dea260ca', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 8, 8, 'አፍርቶም በተጨመቀ ጊዜ ለመቅሠፍትና ለጥፋት ሆነ፥ የጠጡትንም ሰዎች ልቡናቸውን ያጸናዋል፤ የሚያጸይፉና ከእግዚአብሔር የሚርቁ ያደርጋቸዋል።'),
  ('6674229e-d7cd-5ebb-aa8b-01cf43b5c304', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 9, 9, 'በክፉ ሥራውም ይኖራሉና የዲያብሎስ ማደሪያ ያደርጋቸዋል፤ የሰዶም ሐረግም መብላት ትጀምራለች፤ ወደ ተራራዎቹም፥ ወደ ዛፎቹም ትወጣለች።'),
  ('b56e7307-2fbe-5aea-ab8e-9636fa1efcf3', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 10, 10, 'በዙሪያዋ ያሉ የሚያመልኩትን ጣዖቱንም ትጋርደዋለች፤ ክፉና በጎን ለማያውቁ አጋንንትም ሴቶች ልጆችዋንና ወንዶች ልጆችዋን ትሠዋለች።'),
  ('07f986c1-9541-5ff5-a6af-8dbab1532c9b', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 11, 11, 'ንጹሕ ደምንም ያፈስሳሉ፤ ከሰዶም ወይን ዘለዓለም ፍልቅ አድርገው ለጣዖቱ ያፈስሳሉ።'),
  ('f0330179-da92-57c9-a08b-042337eef816', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 12, 12, 'ኢሎፍላውያን የሚያመልኩትን ዳጎንንም አክብራ ታመልካለች።'),
  ('5f7362f0-461e-50f1-a5ac-696b981fe41c', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 13, 13, 'ትሠዋላቸው ዘንድ፥ ፈቃዳቸውንም ታደርግ ዘንድ፥ ከሕፃንነቷ ጀምሮ እስከ ወጣትነቷ ድረስ፥ ዳግመኛም እስከ እርጅናዋ ወራትና እስከ ዕለተ ሞቷ ድረስ ሁልጊዜ የሚመግባትና የሚንከባከባት ፈጣሪዋ እግዚአብሔርንም እንዳታውቅ አጋንንት በአስተማሩአት መጠጣቸውና ስንፍናቸው ደስ ይላት ዘንድ ከመንጋዎችዋ የሰቡትን ትሠዋለታለች።'),
  ('0540ab8f-2bd4-5601-a57b-7c062e69a280', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 14, 14, 'ዳግመኛም በትንሣኤ ጊዜ እበቀላታለሁ፤ ወደ ሕጌ አልተመለሰችምና፥ በትእዛዜም ጸንታ አልኖረችምና ጊዜዋ እስከ ዘለዓለም ድረስ ይሆናል።'),
  ('2421adab-d9dd-531a-adec-2e9b89b6f273', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 15, 15, 'አምላኮችዋ በእውነት ፈጣሪዎች ከሆኑ በቍጣዬ በተቈጣኋት ጊዜ፥ ከእርስዋም ጋር የሚሰስኑ ወዳጆችዋን በአራቅሁ ጊዜ ተነሥተው ወደ ገሃነም ሮጠው ያድኑአት።'),
  ('57233b2a-20fc-51d1-a991-c3293ed052dc', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 16, 16, 'በቤቴና በንዋየ ቅድሳቴ ላይ ስድብንና ውርደትን እንደ አደረገች ሁሉ በሁሉ ዘንድ ጐስቋላ አደረግኋት።'),
  ('8e3044e4-b771-5fd5-acee-7d1af7d21a6f', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 17, 17, 'እነሆ ይህች የእግዚአብሔር ወገን ናት፤ የእስራኤል ፈጣሪ የእግዚአብሔር ቤት ናት፤ የልዑልም የስሙ ማደሪያ ናት፤ ከተለዩ የተለየች የገናናው ንጉሥም ከተማ ኢየሩሳሌም ሲሏት በእርሷ የተጠራ ስሜን አሳዘነች።'),
  ('d300cd96-2387-54b3-a012-e53cb818b6bb', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 18, 18, 'እርሷ ባርያዬ እንደ ሆነች፥ እኔም ጌታዋ እንደ ሆንሁ በእኔ ትመካለች፤ እንደ ወንጀለኛ ትጠቃቀስብኛለች እንጂ ጌታዋ እንደ መሆኔ የምትፈራኝ፥ ፈቃዴንም የምታደርግ አይደለችም።'),
  ('92935233-08c7-5ea2-aa85-ce45c52163c6', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 19, 19, 'ከእኔ ያርቋት ዘንድ ለማሳት መሰናክል ሆኑባት እንጂ ለማይመግቧትና ለማያሳድጓት፥ ለማያለብሷትም ለሌሎች አማልክት ትገዛለች።'),
  ('0ae0235f-0203-510b-a1e7-03cbe2a73bb7', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 20, 20, 'መሥዋዕት ትሠዋላቸዋለች፤ መሥዋዕታቸውንም ትበላለች፤ የመጠጡንም ቍርባን ታፈስላቸዋለች፤ የመጠጡንም ቍርባን ትጠጣለች፤ ዕጣን ታጥንላቸዋለች፤ የዕጣኑንም መዓዛ ታሸትላቸዋለች፤ ያዝዟታል፤ እርሷም ትታዘዝላቸዋለች።'),
  ('2cf74e57-0e06-5999-ac7a-d2edd0677d0f', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 21, 21, 'ዳግመኛም ወንዶች ልጆችዋንና ሴቶች ልጆችዋን ትሠዋላቸዋለች፤ ስለ ፍቅራቸውም ዕልል ትላለችና በእጅዋ ሥራና በከንፈርዋ ንግግር ደስ ይላታል።'),
  ('277dd2dd-ab15-54a7-a1c9-395593cbad6a', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 22, 22, 'በፍርድ ቀን ለእርሷ ወዮላት፤ ለምትወዳቸውና ለምታቅፋቸው አማልክቶችዋ ወዮላቸው፤ ከእነርሱ ጋር ትሉ ወዳማያንቀላፋበት፥ እሳቱም ወደማይጠፋበት የታች ታች ወደ ሆነው ሲዖል ትወርዳለች።'),
  ('fc5a2031-113a-5072-aff5-3d6fa9ceac4e', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 23, 23, 'የፈጠርሁሽን እኔን ትተሽ ሌሎች አማልክትን አምልከሻልና ጐስቋላ የኢየሩሳሌም ልጅ ወዮልሽ።'),
  ('5bb634bf-ae15-579c-a792-d4b5dddd8aea', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 24, 24, 'እኔም እንደ ሥራሽ ፍዳውን አመጣብሻለሁ፤ አሳዝነሽኛልና፥ ቃሌንም ቸል ብለሽዋልና፥ ሥራሽንም አላሣመርሽምና እንደ ተግዳሮትሽ እበቀልሻለሁ።'),
  ('00773b33-44b8-5ad6-a588-87b00358e30d', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 25, 25, 'አንቺ ቃሌን አሳዝነሽዋልና ትእዛዜን ትጠብቂ ዘንድ፥ እኔም ከአንቺ ጋራ እኖር ዘንድ፥ ከሚጣሉሽም ሁሉ አድንሽ ዘንድ፥ አንቺም ያዘዝሁሽን ትእዛዜንና ሥርዐቴን ትጠብቂ ዘንድ፥ ከኔ ጋራ በተማማልሽበት ቃል ኪዳኔ አልጸናሽምና እኔ ቸል እልሻለሁ፤ ፈጥኜም አላድንሽም።'),
  ('365dcf3d-a194-5fb2-a763-0627de264c10', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 26, 26, 'ይህንም ሁሉ አልጠበቅሽም፤ እኔም ቸል አልሁሽ፤ በፍርድ ጊዜም እበቀልሻለሁ፤ እኔ የፈጠርሁሽ አይደለምን? ቃሌንና ትእዛዜንም አልጠበቅሽም፤ የእኔም ወገን ትሆኚ ዘንድ አከበርሁሽ።'),
  ('5a208006-929c-5d33-a0a6-009a7a3e0f77', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 27, 27, 'ሰዶምና ገሞራ እንደ ተለዩ አንቺም ከእኔ ተለየሽ።'),
  ('b0d7fe83-42d4-52c7-a968-cd83274f037a', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 28, 28, 'እኔ በቍጣዬ አጠፋኋቸው፤ እኔ ካጠፋኋቸው ከሰዶምና ከገሞራ ወገን ነሽና፥ ወደ ጐልማሳ ሚስት በመሔድ፥ ከሴቶች ጋር እንደ መድረስ ከእንስሳና ከወንድ ጋራ ያለ ሕግ በመሰሰን፥ የፈጠርኋቸው እኔን አሳዝነውኛልና፥ በደስታቸው እንዳይኖሩ ስም አጠራራቸውን ከምድር አጠፋሁ።'),
  ('47c83918-0238-5e17-a70c-6c08a972b3df', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 29, 29, 'ከታናናሾቻቸው ጀምሮ እስከ ታላላቆቻቸው ድረስ በፊታቸው እግዚአብሔርን መፍራት የለም፤ በክፉ ሥራ ሁሉ ይረዱታል እንጂ እርሷን መሥራት ይተዉ ዘንድ አንዱ ሌላውን አይቈጣውም፤ ሥራቸው ክፉ ነውና ዐመፅንና በደልን የጠገቡ ናቸው።'),
  ('2a27a5e5-268f-50b2-a712-e9c954e2bfae', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 30, 30, 'ክፉ ሥራ ሁሉ ቅሚያና ትዕቢት፥ ስስትም በአሳባቸው የተዘጋጀ ነው።'),
  ('ed2d59e7-a9c8-548d-ad1e-16302d331bea', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 31, 31, 'ስለዚህም እግዚአብሔር ቸል አላቸው፤ ከተሞቻቸውንም ገለበጣቸው፤ እስከ መሠረታቸው ድረስ በእሳት ያቃጠላቸውም አሉ፤ እስከ ዘለዓለም ድረስ ፈጽመው ጠፉ እንጂ ከእነርሱ አንድ ስንኳ አልቀረም።'),
  ('339ec236-9718-56d1-a911-7c7d76a629a7', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 32, 32, 'በኀጢአት ታስረዋልና የዘለዓለም ፍርድ እስከሚሰጥባት እስከ ታላቋ የፍርድ ቀን ድረስ ይቈያሉ፤ በክፉ ሥራቸውም አሳዝነውኛልና አልምራቸውም፤ ይቅርም አልላቸውም።'),
  ('37460f79-8471-52d6-a2bb-48e5726c4acf', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 33, 33, 'እኔም ቸል አልኋቸው፤ እንደዚሁም አንቺ ጐስቋላ የኢየሩሳሌም ልጅ፥ በፍርድ ቀን እንደ እነርሱ ትታሰሪያለሽ፤ ሥራሽ ሁሉ ቅሚያና ኀጢአት፥ ዝሙትና ስስት፥ ሐሰት መናገርም፥ እኔም የማልወደው የስሕተትና የድጥ መንገድ ስለ ሆነ ተቈጥቼ በያዝሁሽ ጊዜ ምክንያት አታገኝምና።'),
  ('46b15183-b8cf-529c-a366-4a4617809a5e', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 34, 34, 'እኔ ለክብር አድርጌሽ ነበር፤ አንቺ ግን ራስሽን ለውርደት አደረግሽ፤ እኔ ለእኔ ብዬሽ ነበር፤ አንቺ ግን ለሌላ ሆንሽ።'),
  ('69a6363a-55e7-5d7e-ac45-b19c9de236f2', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 35, 35, 'እኔ ለቅድስና አጭችሽ ነበር፤ አንቺ ግን ለዲያብሎስ ሆንሽ፤ እኔም እንደ ሥራሽ ክፋት እበቀልሻለሁ።'),
  ('39a1d016-70dc-5bd3-a852-debfb1a129e7', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 36, 36, 'ቃሌን ሁሉ ስላልሰማሽ፥ በወደድሁሽም ጊዜ ያዘዝሁሽን ትእዛዝ ስላልጠበቅሽ የፈጠርሁሽ እግዚአብሔር እኔ ነኝና ክፉ በቀልን አበዛብሻለሁ፤ እንደ አንቺ ባሉ በኃጥኣንም ሁሉ ላይ እቈጣለሁ፤ እንደ ክፋታቸውም በፍርድ ቀን እከፍላቸዋለሁ።'),
  ('e03e2d02-3b7a-5450-a619-fa1af00efd35', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 37, 37, 'ቃሌንም አልጠበቅሽምና፥ ፍርዴንም ቸል ብለሻልና አንቺንም ከእነርሱ ጋር እቀጣሻለሁ።'),
  ('bb9f8a3c-90d3-57ca-a470-e657655b5bad', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 38, 38, 'በልቡናችሁ እግዚአብሔርን መፍራት የሌላችሁ፥ ሰዶምና ገሞራ፥ ወዮላችሁ።'),
  ('27d0eb1e-5dc6-5aa1-aedc-1b15884efd35', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 39, 39, 'በእሳተ ገሃነም ካንቺ ጋራ በአንድነት የሚፈረድባት እኅትሽ የኢየሩሳሌም ልጅ እንደዚሁ ወዮላት! ለዘለዓለሙ መውጫ ወደሌለበት ወደ ተዘጋጀው ወደ ገሃነም በአንድነት ትወርዳላችሁና ያንቺን ሥራ የሠሩ ሁሉ ወዮላቸው።'),
  ('e45516c7-847e-58eb-ae66-2dd82e7dca0b', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 40, 40, 'ቃሌንና ትእዛዜን አልጠበቃችሁምና ቃሌንና ትእዛዜን ያልጠበቃችሁ አንቺና እርሷ በፍርድ ቀን በአንድነት ወደ ሲዖል ትወርዳላችሁ።'),
  ('caa1911a-d9c9-5792-a398-17fc7d38e520', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 41, 41, 'ቃሌንና ትእዛዜን የጠበቁ ጻድቃን ግን ኃጥኣን ያደለቡትን ይበላሉ፤ ክፉዎች ሰዎች የማረኩትንም ምርኮ እግዚአብሔር እንደ አዘዘ ደጋጎች ይካፈላሉ፤ ጻድቃንና ደጋጎችም ደስ ይላቸዋል። ሐሤትንም ያደርጋሉ።'),
  ('3ffd950a-88ca-5357-a195-853dc56b58dc', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 42, 42, 'በደለኞችና ኃጥኣን ግን ያለቅሳሉ፤ ከትእዛዜ ወጥተው ስለ በደሉት በደላቸው ሁሉ ያዝናሉ።'),
  ('215aca3b-c414-5e44-aa74-7329c5f02a7f', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 43, 43, 'ቃሌን የሚጠብቅ፥ በትእዛዜም የሚሔድ በረከቴን የሚያገኝ፥ በእኔ ዘንድም የሚከብር እርሱ ነው።'),
  ('518dd80e-53d0-5c1d-ab78-762966a664d6', 'c4a8df62-709b-5507-ae2c-f3a9a742a6dc', 'd70c3e77-52f2-56e0-a3ba-ae0b1c5100ae', 44, 44, 'ቃሌን የሚጠብቅ፥ ትእዛዜንም የሚያደርግ የምድርን በረከት ይበላል፤ ደጋጎችና ቅኖች ነገሥታት ወደሚገቡበትም ገብቶ ይኖራል።'),
  ('03e8b3b9-f43e-5a91-af62-2abc0650a204', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 1, 1, 'በቍጣዬ በያዝኋቸው ጊዜ ይዋረዳሉና፥ ይቀሠፋሉምና ዛሬ ራሳቸውን ለሚያስታብዩ ለጢሮስና ለሲዶና፥ ለይሁዳ ሀገር አውራጃዎችም ሁሉ ወዮላቸው።'),
  ('81e1f62b-de79-5733-a643-6f85b3b3a3cc', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 2, 2, 'እግዚአብሔር እንዲህ አለ፥ “ትዕቢተኛና ኵራተኛ የጥፋት ልጅ፥ የጽድቅ ጠላት አንገቱን የሚያደነድን፥ የሚመካና ፈጣሪውን የማያውቅ ከእነርሱ ይወጣልና፥ ሁሉን የሚገዛ እግዚአብሔር በእርሱ ላይ ኀይሌን እገልጽ ዘንድ ለቍጣዬ አምሳል አደረግሁት” ብሎአልና።'),
  ('6436a917-b34a-50e7-aeb1-265175d00fcd', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 3, 3, 'ይህቺም ቅፍርናሆም፥ ሰማርያና ገሊላ፥ ሶርያና ደማስቆ፥ ቆጵሮስና አካይያ፥ የዮርዳኖስም አውራጃ አሕዛብ ሁሉ፥ አንገታቸውን ያደነደኑ፥ በልማዳቸው የሚሄዱ፥ የሞት ጥላና ጨለማም የሸፈናቸው ናቸው፤ ዲያብሎስ ልቡናቸውን ሸፍኖታልና፥ ለዚያም ለትዕቢተኛ ይታዘዙለታልና እግዚአብሔርን ወደ መፍራት አይመለሱም።'),
  ('21f02a25-3eca-519a-a5b5-ac9bef941153', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 4, 4, 'ለርኩሳን ለሚታዘዙላቸው፥ በስማቸውም መሥዋዕት ለሚሠዉላቸው ያንጊዜ ወዮላቸው! የፈጠራቸው እግዚአብሔርን ክደውታልና፥ አእምሮ የሌላቸው እንስሳትን ይመስላሉ፤ ያ ዝንጉ የጥፋት ልጅ በቦታው ሁሉ ምስሉን ያቆማልና በእጁ ሥራና በልቡ ፍላጎት፥ በቅሚያና በኀጢአትም ሁሉ፥ በክዳትና በበደልም፥ በቅሚያና ሰው በሚሠራው ዝሙት ሁሉ፥ በሐሰት ነገርም ደስ ይለዋል።'),
  ('a7bb523f-ae11-51a6-a6fc-da561809f896', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 5, 5, 'ይህን እንዲሠራው በእግዚአብሔር ዘንድ የተቈጠረ ስለ ሆነ እንዲህ እንዲያደርግ በዘመኑ ይታወቃልና።'),
  ('8c8f087c-87f4-5ada-a748-8d15eedf513d', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 6, 6, 'ፀሐይ ትጨልማለች፤ ጨረቃም ደም ትሆናለች፤ ከዋክብትም ከሰማይ ይወድቃሉ፤ በውስጥዋ በሚኖሩ ሰዎች በእጃቸው ሥራ መጠን ምድርንና በውስጧም ያለውን ሁሉ ያሳልፍ ዘንድ በኋለኛው ዘመን በሚመጣው ተአምር ሥራው ሁሉ ይጠፋል፤'),
  ('2f198f81-352e-5702-a8fa-91da88410bce', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 7, 7, 'እግዚአብሔር በፈጠረው ፍጥረት ላይ ኰርትዋልና፥ በአንድ ሰዓትም እንደ ወደደ አድርጓልና፥ የኋለኛውን ጠላት ሞት ይሽረዋል።'),
  ('c6c763c6-ef8c-5376-a170-890188adab38', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 8, 8, 'ሁሉን የሚገዛ እግዚአብሔር “እኔ እበቀላለሁ” ብሏልና ከዚያ በኋላ ሥልጣን የለውም።'),
  ('e83c7b28-9e86-54b5-a648-fe54f14da583', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 9, 9, 'እርሱም በቍጣዬ በተያዘበት ቀን ተጠብቆለት ወደ አለ ወደ መቅሠፍትና ወደ ፍርድም ይወርዳል፤ ከእርሱ ጋር ያሉትን ሁሉ ወደ ጥፋት፥ ወደ መከራና ወደ ክሕደት ይስባልና፥ ከገሃነም ፍርድ የማወጣና የማገባ እኔ ነኝና፥'),
  ('a811a75a-ffcf-56c6-af10-f740fded20b2', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 10, 10, 'እርሱ ለደከሙ ሰዎች ጽናትንና ኀይልን ይሰጣልና፥ ዳግመኛም ለኀይለኞችና ለጽኑዓን ሰዎች ድካምን ይሰጣልና ኀይለኛ በኀይሉ አይመካ።'),
  ('ab3c32fb-1738-5955-a538-5811b8f2ddf1', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 11, 11, 'እርሱ እግዚአብሔር ገዢ ነውና፥ የሚበድሉትንም ሰዎች ከሚበድሏቸው ሰዎች እጅ ፈርዶ ያድናቸዋልና የባልቴቶችንና የሙት ልጆችን በቀል ይመልሳል።'),
  ('51c27952-df0e-522a-aa5d-b0cbf255ae7a', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 12, 12, 'ለምትመኪ፥ አንገትሽንም ለምታደነድኚ ለአንቺ ወዮልሽ፤ በቍጣዬ የማልይዝሽና የማልበቀልሽ፥ ይመስልሻል፤ እንዲህ ተብሎ እንደ ተነገረ፥ “በጧት የሚወጣ የአጥቢያ ኮከብ ከሰማይ ለምን ወደቀ?'),
  ('ef7704ee-3938-5283-ae18-bbb550f695f6', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 13, 13, 'በትዕቢቱና በትምክሕቱ ዙፋኔን በሰማያትና በከዋክብት ላይ እዘረጋለሁ፤ እንደ ልዑልም እሆናለሁ” ብሏልና።'),
  ('db0e8271-1297-5cff-a793-2aa57cf27c26', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 14, 14, 'ይኸንም በትዕቢትህ ደፍረህ ተናገርህ፤ በእጁ የፈጠረህንና የሠራህን እግዚአብሔርንም አላሰብኸውም፤ በልቡናህ ጽናት ወደ ገሃነም ትወርድ ዘንድ አንተ ራስህን ለምን ከፍ ከፍ አደረግህ?'),
  ('d7496480-3875-5fa9-aed2-e9693ba38e34', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 15, 15, 'እንደ አንተም ከአሉ መላእክት ሁሉ በትዕቢትህ ተዋረድህ፤ እነርሱ በልብ ትሕትና ፈጣሪያቸውን ያመሰግኑታልና፥ ከትእዛዙም አይወጡምና የፈጠራቸውና የሠራቸውም እርሱ እንደ ሆነ አውቀዋልና፥ ከትእዛዙም እንዳይወጡና እንዳይተላለፉ ሕሊናቸውን ጠበቁ።'),
  ('b7c61e8f-2dd1-597e-a1f4-ccd0dc2b4a1a', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 16, 16, 'አንተ ግን በልቡናህ ትዕቢት ክፉን አደረግህ፤ ከጓደኞችህም ተለይተህ የተዋረድህ ሆንህ፤ እንደ አንተ ያሉ ኃጥኣንና ከአንተ ፍጥረት ወገን የሆኑ፥ እንደ አንተም የሚክዱ ዝንጉዎች ለሚኖሩበት ኀጢአትና በደል፥ ሽንገላና ቅሚያ ሁሉ አንተ ጠባቂው ነህና ክፋትን የምታስተምራቸው፥ በፈቃድህና በትእዛዝህ ይሔዳሉ።'),
  ('c5ea3162-a724-5220-a68b-1c3f815cfd51', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 17, 17, 'አንተና በተንኰልህ ያሳትሃቸው በአንድነት ወደ ገሃነም ትወርዳላችሁና ወዮልህ።'),
  ('cbef0f31-dc9f-5140-aad4-3275c02bbdeb', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 18, 18, 'በሚያስት በዚያ በወንጀለኛ የሳታችሁ የእግዚአብሔር ልጆች ሆይ፥ ወዮላችሁ! እርሱና አጋንንቱ በአስተማሯችሁ እንደ እርሱ ስታችኋልና ለዘለዓለም መውጫ ወደሌለበት መቅሠፍት በአድነት ትወርዳላችሁ።'),
  ('9d6bef0b-c99d-5885-afe5-6ca2e6e35c9b', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 19, 19, 'ቀድሞም የእግዚአብሔር ባሪያ ሙሴ ሳለ በኮሬብና በክርክር ውኃ፥ በደብረ ሲናና በአማሌቅ አሳዘናችሁት።'),
  ('03cb0721-ce94-549a-a9d0-a5adf6930d50', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 20, 20, 'ዳግመኛም ወደ ከነዓን ጕበኛ በላካችሁ ጊዜ ጎዳናው ሩቅ ነው፤ እስከ ሰማይ የሚደርስ ቅጽራቸውም፥ አንባቸውም ጽኑ ነው፤ አርበኞችም በዚያ ይኖራሉ ብለው ይህን በነገሩአችሁ ጊዜ የሚያስጨንቅ ሥራ ወደምትሠሩበት ወደ ግብፅ ሀገር ትመለሱ ዘንድ ተቈጥታችሁ በእግዚአብሔር ቃል ዐመፃችሁ።'),
  ('c8621241-0176-5884-a818-408a367d587a', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 21, 21, 'ከመከራው ያዳናችሁን፥ በግብፅም ታላላቅ ተአምራትን አድርጎ በመልአኩ እጅ የመራችሁን እግዚአብሔርን አላሰባችሁትም። ፀሐይ እንዳያቃጥላችሁ ቀን በደመና ይጋርዳችሁ ነበር፥ እግራችሁም በጨለማ እንዳይሰናከል ዐምደ እሳት በሌሊት ያበራላችሁ ነበር።'),
  ('fd741ac7-12e5-5d91-afcb-fa680442fa36', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 22, 22, 'ሠራዊቱና ፈርዖንም ባስፈሯችሁ ጊዜ ፈጽማችሁ ወደ ሙሴ ጮኻችሁ፤ ሙሴም ፈጽሞ ወደ እግዚአብሔር ጮኸ፤ ከፈርዖንም ሠራዊት ጋር እንዳትገናኙ በመልአኩ ጠበቃችሁ።'),
  ('f5f9f809-ade2-5807-a594-12ef0d532bc8', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 23, 23, 'እነርሱን ግን በመከራ መለሳቸው። “እግዚአብሔር ብቻውን መራቸው፤ ከእነርሱም ጋር ሌላ አምላክ አልነበረም” ብሏልና። ጠላቶቻቸውን ግን አንድ ጊዜ በባሕር ቀበራቸው፤ ከእነርሱም የሚሸሸውን አላስቀረም።'),
  ('be9fcac1-4fe7-5757-a51f-461e31ad3704', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 24, 24, 'እስራኤልንም በባሕሩ መካከል በእግር አሻገራቸው። ከግብፃውያንም የተነሣ ያገኛቸው ክፋት ምንም የለም። ወደ ደብረ ሲናም አደረሳቸው፤ በዚያም አርባ ዘመን መናውን መገባቸው።'),
  ('4bf7fecf-e18d-55ec-a072-fda6ddbe3283', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 25, 25, 'የእስራኤል ልጆች እግዚአብሔርን ሁልጊዜ ያሳዝኑታልና ይህን ያህል መልካምን አድርጎላቸው እግዚአብሔርን ማምለክን ቸል አሉ።'),
  ('08b49ecc-1819-5617-ae9c-515ee0293cba', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 26, 26, 'ከልጅነታቸውም ጀምሮ እስኪያረጁ ድረስ ክፋትን በልቡናቸው አኖሩ። የእግዚአብሔር አንደበት በአበው የትውልድ መጽሐፍ እንደዚህ ብሎ ተናግሯልና፤ “የአዳም ልጆች ልቡናቸው ዐመድ ነው፤ ሥራቸውም ሁሉ ወደ ቅሚያና ወደ ክፋት መሮጥ ነው፤ ከእነርሱም በግፍ የሰውን ገንዘብ ከመሰብሰብ፥ በሐሰትም ከመማል፥ ባልንጀራውንም ከመግደል፥ ከመቀማትና ከመስረቅ በቀር የቀናች ሥራን የሚወዳት የለም።'),
  ('500617f1-6234-58ab-a6c5-bf91cf2ac6b9', 'e9126649-cdfb-5cd6-ab12-8b20285524d1', '3bf514d4-0da8-521a-a0f0-8a328820ec42', 27, 27, 'ሁሉም በሕይወት ዘመናቸው ወደዚህ ክፋት ይሄዳሉ፤” የእግዚአብሔርን ትእዛዝ ያፈረሱ የእስራኤል ልጆችም ከመጀመሪያ እስከ መጨረሻ ድረስ እግዚአብሔርን ፈጽመው አሳዘኑት።'),
  ('de71609a-8bf9-5bb8-afdc-186a2169d21c', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 1, 1, 'እግዚአብሔርም የቀደሙ ወገኖችን ስለ ቃየን ልጆች ኀጢአት በጥፋት ውኃ በቀጣቸው ጊዜ ምድርን በማየ አይኅ አጠመቃት፤ ከቃየን ልጆች ኀጢአትም ሁሉ አነጻት።'),
  ('9a6bdc79-e9e7-5815-a1e8-09eb7cd71f54', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 2, 2, '“ሰውን ስለ ፈጠርሁት አዘንሁ” ብሏልና በደለኞችን ሁሉ አጠፋ። ከስምንት ሰዎችም በቀር አላስቀረም፤ ሁሉንም አጠፋ። ከዚህም በኋላ እነርሱን አባዛቸው፤ ምድርንም መሏት፤ የአባታቸው የአዳምንም ርስት ተካፈሉ።'),
  ('35f90359-47ad-589b-a775-961b44d565d6', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 3, 3, 'ኖኅ ግን እግዚአብሔር ምድርን ዳግመኛ በጥፋት ውኃ እንዳያጠፋት ከእግዚአብሔር ጋር ቃል ኪዳን አደረገ፤ የኖኅም ልጆች የሞተውንና የበከተውን እንዳይበሉ፥ ከፈጠራቸው ከእግዚአብሔርም በቀር ሌሎች አማልክትን እንዳያመልኩ፥ እርሱም አምላካቸው ይሆናቸው ዘንድ፥ በከንቱም አንድ ጊዜ እንዳያጠፋቸው፥ የሳተኑንና የበልጉንም ዝናም እንዳይከለክላቸው፥ ለከብቶችና ለሰዎችም በየጊዜው ምግባቸውን ይሰጣቸው ዘንድ፥ ሣሩንና የእህሉን ፍሬ፥ ተክሉንም ይሰጣቸው ዘንድ፥ እነርሱም እግዚአብሔር በሚወደው ሁሉ ሥራቸውን ያሣምሩ ዘንድ ቃል ኪዳን አደረጉ።'),
  ('4ca3490f-08fd-50b7-ac03-596da7569ae8', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 4, 4, 'ይኸንም ሥርዐት ከሰጣቸው በኋላ የእስራኤል ልጆች በክፋታቸው እግዚአብሔርን አሳዘኑት። የፈጣሪያቸውን የእግዚአብሔርን ሕግ እንዳላፈረሱ እንዳባቶቻቸው እንደ አብርሃምና እንደ ይስሐቅ፥ እንደ ያዕቆብም አልሔዱም።'),
  ('cb2c3eb6-dc92-567b-a7c6-5050d74fecf4', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 5, 5, 'ከታናናሾቹም ጀምረው እስከ ታላላቆቹ ድረስ የእግዚአብሔርን ሕጉን ያልጠበቁ እነዚያ የእስራኤል ልጆች በሥራቸው ጠማሞች ነበሩ።'),
  ('e56ad870-3bbb-5a4c-a489-18af54fa5576', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 6, 6, 'ካህናቶቻቸውም፥ አለቆቻቸውም፥ ጸሓፊዎቻቸውም ቢሆኑ ሁሉም የእግዚአብሔርን ሕግ ያፈርሳሉ።'),
  ('13979eb6-b6a3-58c7-a917-17f72fe9a764', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 7, 7, 'ሙሴም በሕጉ መጽሐፍ እንዲህ ብሎ ባዘዛቸው በችግዚአብሔር ሕግና ሥርዐት አይጸኑም። “በፍጹም ልብህና በፍጹም ነፍስህ ፈጣሪህ እግዚአብሔርን ውደደው፤'),
  ('be1d7cc7-90b6-512f-ae76-28730c43f164', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 8, 8, 'ባልንጀራህን እንደ ራስህ ውደድ፤ ሌሎች አማልክትን አታምልክ፤ ወደ ጐልማሳ ሚስትም አትሂድ፤ ነፍስ አትግደል፤ አትስረቅም።'),
  ('de268517-f481-59c8-abb5-8da5a7be7652', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 9, 9, 'በሐሰትም አትመስክር፤ የባልንጀራህንም ገንዘብ፥ ወንድምህ የገዛውንም ሁሉ አህያውንም ቢሆን፥ በሬውንም ቢሆን አትመኝ።”'),
  ('615c8abb-9339-5061-af3a-0045abcc2e4f', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 10, 10, 'ነገር ግን ይኸን ሁሉ ካዘዛቸው በኋላ ክፉዎች የሆኑ የእስራኤል ልጆች ወደ ኀጢአትና ወደ ክዳት፥ ወደ በደልና ወደ ቅሚያ፥ ወደ ጐልማሳ ሚስትና ወደ መስረቅም፥ ወደ ሐሰትና ጣዖቶችን ወደ ማምለክ ይመለሳሉ።'),
  ('c7b7727e-e547-5f4b-af9e-3e24adfc17e8', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 11, 11, 'የእስራኤል ልጆች ወደ ሣር የሚሠማራ የላምን ጣዖት በመሥራት በኮሬብ እግዚአብሔርን አሳዘኑት፤ “እነሆ፥ ከግብፅ ያወጡን አማልክቶቻችን እነዚህ ናቸው” ብለው ሰገዱ።'),
  ('5183099c-167e-536e-a322-82fe1107d876', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 12, 12, 'በእጃቸውም ሥራ ደስ አላቸው፤ በሉ፥ ጠጡ፤ ጠገቡም፤ ሊዘፍኑም ተነሡ።'),
  ('682590a5-bd2d-537d-a407-115ba87fdcf9', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 13, 13, 'ስለዚህ እግዚአብሔር “ከግብፅ ሀገር ከባርነት ቤት ያወጣሃቸው ወገኖችህ በደሉ፥ ሳቱም፤ የላም ምስልም ሠርተው ለጣዖቱ ሰገዱ” ብሎታልና ሙሴ ተቈጥቶ ከሲና ተራራ ወረደ።'),
  ('2055c80c-8959-56b1-ab22-3074260cf02c', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 14, 14, 'ሙሴም ወገኖቹን እየተቈጣቸው ከባለሟሉ ከኢያሱ ጋራ ወረደ፤ ኢያሱም በሰማ ጊዜ “እነሆ፥ በእስራኤል ሰፈር ያርበኞችን ድምፅ እሰማለሁ” አለ።'),
  ('84d6cf1b-1297-59fe-a9ce-6b11d1126c62', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 15, 15, 'ሙሴም ኢያሱን እንዲህ አለው “ያልፈላ የወይን ጠጅ ድምፅ እንጂ ያርበኛስ ድምፅ አይደለም።” ወርዶም ምስላቸውን ሰበረው፤ እንደ ትቢያም እስኪሆን ድረስ ፈጽሞ አደቀቀው፤ የእስራኤልም ልጆች በተራራው አጠገብ በሚጠጡት ውኃ ውስጥ ጨመረው።'),
  ('8d6116ab-ea85-509c-a020-5139afb358ad', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 16, 16, 'ከዚህ በኋላ በእግዚአብሔር ፊት ክፉ ስለ አደረጉ እርስ በርሳቸው ይጋደሉ ዘንድ ሌዋውያንን አዘዛቸው።'),
  ('8b187d9b-53d8-5995-a36f-819797f2b7c3', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 17, 17, 'ራሳቸውን ከመግደል፥ ዘመዶቻቸውንና አባቶቻቸውንም ከመግደል እግዚአብሔርን መገዳደር እንደሚበልጥ ዐውቀው እንዳዘዛቸው አደረጉ።'),
  ('c4d07e97-6dd0-5cc9-a391-a4d5cb25ad57', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 18, 18, 'ስለዚህም ሙሴ እንዲህ አላቸው፥ “የመገባችሁንና የተከባከባችሁን፥ ከአገዛዝም ቤት የአወጣችሁን፥ ለእነርሱና ከእነርሱ በኋላ ለልጆቻቸው ይሰጣቸው ዘንድ ላባቶቻችሁ የማለላቸው ርስትንም ያወረሳችሁ እግዚአብሔርን ስላሳዘናችሁት በእጃችሁ እግዚአብሔርን ደስ አሰኛችሁት።”'),
  ('1a431cbb-4c30-56b6-a542-5e294e2ec0dd', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 19, 19, 'ከዚያም ወደ ኀጢአትና ወደ ክፉ ነገር ይሄዳሉና እግዚአብሔርን ማሳዘንን አልተዉም።'),
  ('6a7ff471-be13-575d-a0a1-e650bf2e8a2a', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 20, 20, 'ከሕፃንነታቸው ጀምረው እስከ ጐልማሳነታቸውና እስከ እርጅናቸው ድረስ በምድር ላይ ያለውን፥ በሰማይም ለሚወዱት ያዘጋጀውን ይሰጣቸው ዘንድ በበጎ ሥራቸው እግዚአብሔርን ደስ እንዳሰኙት እንዳባቶቻቸው እንደ አብርሃምና እንደ ይስሐቅ እንደ ያዕቆብም አይደሉም፤ በዚህም ወተትና ማር የምታፈስሰውን ምድረ ርስትን፥ በወዲያውም ዓለም ለጻድቃን የተዘጋጀች የደስታ ገነትን፥ ዐይን ያላየውን፥ ጆሮም ያልሰማውን፥ በሰው ልቡናም ያልታሰበውን፥ እግዚአብሔርን በሕይወታቸው ደስ ላሰኙት ለሚወዱት ለአብርሃምና ለይስሐቅ ለያዕቆብም እግዚአብሔር ያዘጋጀውን ይሰጣቸው ዘንድ፤'),
  ('23566343-4166-5a7a-a889-24bd83afd770', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 21, 21, 'ከሓድያንና ክፉዎች በልቡናቸው ፈቃድ የሚኖሩ የእነርሱ ልጆች ግን የመገባቸውንና የተከባከባቸውን፥ ከሕፃንነታቸውም ጀምሮ የጠበቃቸውን የእግዚአብሔርን ቃል አልሰሙም።'),
  ('c30ee482-7368-50c5-ace5-51a65b315ac0', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 22, 22, 'ከግብፅ ምድር ያወጣቸውንና ከጡብ ሥራ፥ ከመራራ አገዛዝም ያዳናቸውን እግዚአብሔርን አላሰቡትም።'),
  ('34dfd5be-1f41-5da3-ac2a-ab1d25af78dd', 'f790acef-7b25-5340-a1a1-b648fb3bb252', '4fc99cc6-5432-5fd1-a90e-ea07b46a05e5', 23, 23, 'እነርሱ ግን እጅግ አሳዘኑት፤ እርሱም በዙሪያቸው ያሉ አሕዛብን ያስነሣባቸው ነበር፤ እነርሱም በጠላትነት እየተነሡ እንደ ወደዱ ያስገብሯቸው ነበር።'),
  ('c3da9e6e-60ac-5647-aeee-877477365373', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 1, 1, 'ያንጊዜም የምድያም ሰዎች በጠላትነት ተነሡባቸው፤ እስራኤልንም ይወጓቸው ዘንድ ሠራዊቶቻቸውን አስነሡባቸው፤ የንጉሣቸውም ስሙ አክራንድዮስ ይባላል፤ የሶርያንና የኪልቅያን፥ የደማስቆንም ብዙ ሠራዊት በጧት ሰበሰበ።'),
  ('be8bcae3-0307-53cf-a6c3-a561f972b1e7', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 2, 2, 'በዮርዳኖስም ማዶ ሰፈረ፤ እንዲህም ብሎ ወደ እስራኤል መልእክተኞችን ላከ፥ “ግብር ገብሩልኝ፤ ያለዚያ ግን እቀጣችሁ ዘንድ፥ ከብቶቻችሁንም እማርክ ዘንድ፥ ንብረታችሁንም ሁሉ እወስድ ዘንድ፥ ልጆቻችሁንም እማርክ ዘንድ መጣሁ።'),
  ('abb24e14-3ff2-5a4a-aaf1-fe12992dfdab', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 3, 3, 'ወደማታውቁትም ሀገር ማርኬ እወስዳችኋለሁ፤ በዚያም ውኃ ቀጂዎችንና እንጨት ለቃሚዎችን አደርጋችኋለሁ።'),
  ('461e08c6-9d21-54a7-a85b-dbc827fba73b', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 4, 4, 'እኛ የእግዚአብሔር ወገኖች ነን፤ የሚችለንም የለም እያላችሁ አትመኩ፤ አጠፋችሁ ዘንድ፥ ገንዘባችሁንም እዘርፍ ዘንድ እግዚአብሔር የላከኝ አይደለሁምን? የእናንተ የሆነውንም ሁሉ እሰበስብ ዘንድ ላከኝ።'),
  ('5b1aa3e0-f4a8-5a03-a738-8c2678cbefa9', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 5, 5, 'እኔ የቀጣኋቸውን ሌሎች ወገኖች በውኑ ልዩ ጣዖቶቻቸው ያዳኗቸው ማዳን አለን? ገንዘባቸውንና ጥሪታቸውን ማረክሁ፤ እነርሱንም ገደልሁ፥ ልጆቻቸውንም ማረክሁ።'),
  ('52eaedd9-6cf4-52c5-a6b3-658557365254', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 6, 6, 'እንደዚሁም አንደ አዘዝኋችሁ ግብር ካላገባችሁልኝ እናንተንም እንደ እነርሱ አደርጋችኋለሁ።” ከብቶቻቸውንና ገንዘባቸውንም ይዘርፍ፥ ሚስቶቻቸውንና ልጆቻቸውንም ይማርክ ዘንድ ዮርዳኖስን ተሻገረ።'),
  ('bdb7c3fd-15e0-5a4b-a984-8fb4865fe81b', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 7, 7, 'ከዚህም በኋላ የእስራኤል ልጆች ወደ እግዚአብሔር መራራ ልቅሶን አለቀሱ፤ ፈጽመውም ጮኹ፤ ነገር ግን የሚረዳቸው አጡ።'),
  ('763b36fa-231a-575a-a254-97f216bf3ded', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 8, 8, 'ስለዚህም ለሦስቱ ወንድማማቾች እግዚአብሔር ጽናትን ሰጣቸው፤ ስማቸውም እንደዚህ ነው፤ መብክዩስ፥ መቃቢስና ይሁዳ ናቸው። መልካቸው ያማረ፥ በኀይላቸውም ሁሉ አርበኞች ነበሩ።'),
  ('1cadc686-dcb5-5d44-ae6a-28874f0518a0', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 9, 9, 'የእስራኤልም ልጆች ፈጽመው ሲያለቅሱ በሰሙ ጊዜ ከእስራኤል ልጆች ሁሉ ጩኸት የተነሣ ልቡናቸውን አሳዘናቸው፤ ባልቴቶችና የሙት ልጆች፥ ካህናቶቻቸውና መሳፍንቶቻቸው፥ የእስራኤል ወገን ሁሉ፥ ሴቶችና ወንዶች ልጆችም ሁሉ በራሳቸው ላይ ዐመድ ነስንሰው ያለቅሱ ነበር፤ መኳንንቶቻቸውም ማቅ ለብሰው ነበር።'),
  ('a3b9d6e6-e025-5c86-abe4-4470941d837f', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 10, 10, 'መልከ መልካምና ደመ ግቡ የሆኑ እነዚያ ወንድማማቾች ግን ሔደው ያድኗቸው ዘንድ ተስማሙ፤ “ሔደን ስለ እነዚህ ሰዎች ሰውነታችንን ለሞት እንስጥ” ብለው ተማከሩ።'),
  ('091ae7a7-8cf8-5fe1-abb2-ebd4e80af30f', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 11, 11, 'አይዞህ! አይዞህ! ተባብለው፥ በወገባቸው ሰይፋቸውን ታጥቀው፥ በእጃቸውም ጦራቸውን ይዘው ሔዱ፤ አርበኛውንም ይዋጉት ዘንድ ተዘጋጅተው ሔዱ።'),
  ('5cf8a26a-a66c-517d-a0ed-34e8710da754', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 12, 12, 'በማዕድም ተቀምጦ ሳለ ደረሱ፤ መብክዩስም አርበኛውን ወጋው፤ ያላመጠውን ሳይውጠው በአንዲት አመታት አንገቱን ቈረጠው፤ ይሁዳና መቃብዩስም በንጉሡ ግራና ቀኝ የነበሩትን በሰይፍ መትዋቸው።'),
  ('c6a19df0-89fa-5b5d-ad77-cfeccc66eafe', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 13, 13, 'ንጉሣቸውም በወደቀ ጊዜ ሁሉም ሸሹ፤ ጦሮቻቸውም በባልንጀሮቻቸው ልብ ገቡ፤ ቀስቶቻቸውም ተሰባበሩ፤ እነርሱም ድል ተነሡ።'),
  ('050c3548-dce2-5283-ab3f-359a79b36743', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 14, 14, 'መልከ መልካምና ደመ ግቡ የሆኑ እነዚያ ወንድማማቾች ግን ዳኑ፤ ያገኛቸውም ምንም ክፉ ነገር የለም፤ እግዚአብሔርም መቅሠፍቱን ወደ እነርሱ መልሶታልና እነዚያ ክፉዎች እርስ በርሳቸው ተላለቁ።'),
  ('c9282c62-494e-59aa-ae52-513ba004e6a7', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 15, 15, 'ድል ተነሡ፤ ሞቱም፤ ዮርዳኖስንም እስኪሻገሩ ድረስ ገንዘባቸውን ሁሉ ጣሉ፤ የእነርሱ የሆነውም ሁሉ ቀረ፤ የእስራኤልም ልጆች እነዚያ እንደ ሸሹና ወደ ሰፈራቸው እንደ ሄዱ ባዩ ጊዜ የዘረፉትን ገንዘብ ለራሳቸው ወሰዱ።'),
  ('69e3e42a-86da-56ae-a18d-103318a952ca', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 16, 16, 'እግዚአብሔርም በመብክዩስና በወንድሞቹ እጅ የእስራኤልን ልጆች እንዲህ አዳናቸው።'),
  ('0efd2e60-d540-54e3-abaa-d5b468995d26', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 17, 17, 'የእስራኤልም ልጆች እግዚአብሔርን ደስ እያሰኙት ጥቂት ወራት ኖሩ።'),
  ('4cae85f3-b9f6-544b-af3a-46642931ee6f', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 18, 18, 'ከዚያ በኋላ ግን ዳግመኛ ወደ ክፋታቸው ተመለሱ፤ የእስራኤልም ልጆች እግዚአብሔርን በሚገባ ማምለክን ቸል አሉ።'),
  ('893196ed-8d21-5d95-aefb-14b720994802', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 19, 19, 'እርሱ ግን ዳግመኛ በማያውቋቸው፥ የእርሻቸውን አዝመራ በሚሰበስቡና የወይናቸውን ተክል በሚያጠፉ፥ መንጋቸውንም በሚዘርፉና ከብቶቻቸውን በፊታቸው አርደው በማያበሏቸው፥'),
  ('36837150-cddd-5cc0-a4f3-295d3eab796f', '476b249f-a738-5891-a129-3aac8fd18d6c', '98e61fe9-245e-5860-ad86-aa871f09feaf', 20, 20, 'ሚስቶቻቸውን፥ ወንዶች ልጆቻቸውንና ሴቶች ልጆቻቸውን በሚማርኩ ወገኖች አሳዘናቸው። ሁልጊዜም እግዚአብሔርን የሚያሳዝኑት ስለ ሆነ እነርሱ ሕጉን ያፈረሱ ወገኖች ናቸውና ልጆቻቸውን በፊታቸው ራስ ራሳቸውን ይቀጠቅጧቸዋል፤ ሊያድኗቸውም አይችሉም።'),
  ('6418feff-4076-5d56-a98f-24c31d2f5aff', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 1, 1, 'የጢሮስና የሲዶና ሕዝብ በባሕሩ ዳርቻና በዮርዳኖስ ወንዝ ማዶ ፥ በገለዓድና በካራን፥ በከናኔዎንና በኢያቡሴዎን፥ በጌርጌሴዎንና በኤዶም የሚኖሩ፥ የአማሌቅም ሕዝብ፥'),
  ('2e0dd729-8589-5525-a575-379de4433d5d', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 2, 2, 'አሕዛብም ሁሉ በየሀገራቸውና በየነገዳቸው፥ በየሥርዐታቸውና በየአውራጃዎቻቸው፥ በየሀገራቸውም ቋንቋ፥ ሁሉም እግዚአብሔር እንደ ወሰናቸው ይኖራሉ።'),
  ('57a852f3-892f-50b5-a03f-a3e5977cd484', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 3, 3, 'ከእነርሱም ሥራቸው ያማረና እግዚአብሔርን የሚያውቁት አሉ።'),
  ('53b170a9-30de-5bf3-a3ae-a897adcd1633', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 4, 4, 'ከእነርሱም ሥራቸው ክፉ የሆነ፥ የፈጠራቸው እግዚአብሔርንም የማያውቁት አሉ፤ እንደ ሥራቸውም በሶርያው ንጉሥ በአሜኔሴር እጅ ገዛቸው፤'),
  ('00a78ccc-6fae-5c7d-a268-6d875fe4282e', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 5, 5, 'የደማስቆን ገንዘብ ይወስዳልና፥ በግብፁ ንጉሥ ፊትም የሰማርያን ምርኮ ይካፈላልና።'),
  ('f47a5efb-5cbb-5769-af67-f7c8ed0669da', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 6, 6, 'የገለዓድ ተራሮችና የጌላቡሄ ሸለቆዎች፥ ሰማርያና በይሁዳ ምድር ያለ ጳንጦስም ሁሉ፥ በዐረብ በሜድና በጳርቴ፥ በሴላውግያና በቀጶዶቅያ ተራሮች የሚኖሩ፥'),
  ('d2e3c979-10f8-5aa6-ae9c-e305e3e999af', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 7, 7, 'በአውራጃቸውም የሚኖሩ፥ እግዚአብሔርንም የማያውቁና ትእዛዙን የማይጠብቁ አንገተ ደንዳና ሕዝብ ናቸው።'),
  ('033c338f-ba1a-5bdd-ab8a-49f3b228fa30', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 8, 8, 'እርሱም እንደ ሥራቸው ክፋትና እንደ እጃቸው ሥራ ይከፍላቸዋል።'),
  ('f7b452a8-a85d-5b52-acc5-f55c2a51be3e', 'd4b61dc2-d03a-5ab0-a49e-479a1cf0282d', 'ced26a55-4583-5bb2-a13c-2790aa3384cc', 9, 9, 'የቂሳርያ አውራጃ፥ የገለዓድና የአማሌቅ ሕዝብ፥ ጽድቅን የተመላች፥ በውስጧም የእስራኤል ቅዱስ፥ በኪሩቤል ሠረገላ ላይ የሚቀመጥ፥ እጅግ የብዙ ብዙ የሆኑ መላእክት በፊቱ የሚቆሙ የሠራዊት ጌታ የሚመሰገንባት የእግዚአብሔርን ከተማ ያጠፏት ዘንድ ተባብረዋልና።'),
  ('67545b55-3a84-57b4-abb7-bddafdc46897', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 1, 1, 'የኤዶምያስና የአማሌቅ ሠራዊት የሰማይና የምድር አገዛዝ በእጁ ያለ እግዚአብሔርን አያመልኩትም፤ እነርሱ በእውነት የማይሄዱ ወንጀለኞች ናቸውና ቤተ መቅደሱን መርገጥ አይፈሩም።'),
  ('49b0b26f-1e14-591d-aa56-616582269785', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 2, 2, 'ከዝሙትና ደም ከማፍሰስ አባላ የተመታውንና ሞቶ ያደረውን፥ የሚመስለውንም ሁሉ ከመብላት በቀር በፊታቸው እግዚአብሔርን መፍራት የለም፤ እነዚሁም የተናቁና የረከሱ ናቸው።'),
  ('7d3203a9-c4e9-54e3-a431-b07158179f56', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 3, 3, 'ሃይማኖትና ምግባር የላቸውም፤ በጎ ሥራን የጠሉ ናቸውና፤ እግዚአብሔርንም አያውቁትም፤ ከክፋትና ከመቀማት፥ ከረከሰ ሥራና ከሁከት ሁሉ በቀር፥ አባታቸው ሰብልያኖስ እንዳስተማራቸው ከዘፈንና ከጨዋታ በቀር የሰላምን መንገድ አያውቋትምና።'),
  ('1a1535bd-9ab5-5cef-a69f-5c9e14f3c223', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 4, 4, 'እርሱ ከአጋንንቱ ጋር ገዝትዋቸዋልና፥ ለእየራሱ የሆነ የክፉን ሥራ ሁሉ፥ ክፋትንና ቅሚያን፥ የሌላውን ገንዘብ በዐመፅ መንጠቅንና ስርቆትን፥ ሞቶ ያደረውንና አባላ የተመታውን መብላትንና ዝሙትን ያስተምራቸዋል።'),
  ('d2707ab1-4b23-5af7-a94b-345a71e9508f', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 5, 5, 'ይህንም የሚመስለውን ሁሉ፥ ወደ ጐልማሳ ሚስት መሔድንና፥ ደም ማፍሰስን፥ ለጣዖት የተሠዋውንና ሙቶ ያደረውን መብላትን፥ የሰው ነፍስንም በዐመፅ መግደልን፥ መጠቃቀስንና ምቀኝነትን፥ ስስትንና እግዚአብሔር የማይወድደውን ክፉ ሥራን ሁሉ ያስተምራቸዋል፤ ይህንም ትምህርት ዓለሙን ሁሉ ከያዘ ከእግዚአብሔር መንገድ ያርቃቸው ዘንድ ጠላታቸው ሰብልያኖስ ያመጣላቸዋል።'),
  ('8350c73a-be0f-55ec-a308-9634cde4b322', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 6, 6, 'የእግዚአብሔር መንገድ ግን ትሕትናና የዋህነት፥ ባልንጀራንም መውደድና ወንድምን አለማበሳጨት፥ ከሰው ሁሉ ጋርም መፋቀርና ሰላም ነው።'),
  ('e5be603f-7af6-5aa2-ac12-06dea4d9a523', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 7, 7, 'ለሰው ፊት የምታዳሉ፥ ቀማኞችንና ዐመፀኞችን፥ ነጣቂዎችንና ወደ ጐልማሳ ሚስት ሒያጆችን፥ በባልንጀራቸውም ላይ ግፍንና ክፉ ሥራ ሠሪዎችን፥ በዐመፅም ባልንጀራቸውን ይበድሉ ዘንድ የሚሸነግሉ ሰዎችን አትሁኑ።'),
  ('51e8e67b-1103-5387-afd5-04533ab4bfba', '66f493fc-ef6a-54db-a3cf-45d07ff224ae', 'ab3e4ec7-35da-515f-ab3e-5a7f76a43cfd', 8, 8, 'ይጠቃቀሳሉ፤ ራሳቸውንም ይነቀንቃሉ፤ ለክፋትም ይተነኰላሉ፤ ሰዎችንም ወደ ዘለዓለም ፍርድ ያወርዷቸው ዘንድ ለማሳት ያሟርታሉ።'),
  ('eba32f06-68f1-56c1-a9fe-035af2ce536e', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 1, 1, 'ወደ እግዚአብሔር እንደምትሄድ አስብ፤ ሁሉም በእጁ አለ፤ አንተ በሠራኸውም ሥራ ይፈርድብህ ዘንድ በፊቱ ትቆማለህ።'),
  ('085f2037-2c1f-5098-ac84-9873abdb72d5', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 2, 2, 'ቀድሞም እኮ ክፉዎችና ትዕቢተኞች የሆኑ፥ ከእነርሱም የሚበልጥና የሚበረታ የሌለ፥ የረዓይት ልጆች እንደዚሁ ነበሩ፤ ኀይላቸውንና ቁመታቸውን፥ የክንዳቸውንም ብርታት ስለ አዩ እግዚአብሔርን በፊታቸው አላደረጉትም፤ እርሱም ካለመኖር ያመጣቸው ፈጣሪያቸው እንደ ሆነ አላወቁትም።'),
  ('9b03f635-aaa8-5f6f-ac76-1d8c277ddc66', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 3, 3, 'አባቶቻቸውም መላእክት ሳሉ ከመላእክት ጋራ በሰማያት ያመሰግኑ ነበር። ፈቃዳቸውም ባሳታቸው ጊዜ ወደ ዘለዓለም የፍርድ ቅጣት ወረዱ።'),
  ('ea58c721-2cc3-50ed-ae70-5eb81a5b7473', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 4, 4, 'ከሰው ልጆችም ሚስቶችን አገቡ፤ ስለ ልቡናቸው ትዕቢት ያስታቸው ዘንድ፥ ሕጉንና ትእዛዙንም ይጠብቁ እንደ ሆነ ይፈትናቸው ዘንድ እግዚአብሔር የሰው ሥጋን ፈጥሮላቸዋልና።'),
  ('1740ce57-311a-564d-a99f-4bcda4bd93e4', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 5, 5, 'እነርሱ ግን ትእዛዙን አልጠበቁም፤ እርሱም ከአባታቸው ከዲያብሎስ ጋራ ወደ ገሃነመ እሳት አወረዳቸው፤ እግዚአብሔርም እንደ ሰው የበደሉ መላእክትን ተቈጥትዋቸዋልና በእነርሱ ምክንያት የሰው ዘመኑ አነሰ።'),
  ('b51ee90d-10cf-5226-a661-925041b991e8', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 6, 6, 'የአዳምንም ልጆች ከእነርሱ ጋራ ወሰዷቸው፤ በእነርሱም ቅጣት ወደ ሲዖል አወረዷቸው።'),
  ('5d4d0d79-1661-50db-ad03-99d6978dcee3', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 7, 7, 'መላእክት በቃየል ልጆች ስለ ሳቱ የሰው ዘመኑ ተቀንሶአልና፤ ጥንቱን የሰው ዘመኑ ዘጠኝ መቶ ሲሆን ወደ መቶ ሃያ ዘመን ተመለሱ።'),
  ('92bb6003-0ac6-558d-acfc-83fe8d166243', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 8, 8, 'እግዚአብሔርም እንዲህ አለ፥ “እነርሱ ሥጋውያንና ደማውያን ናቸውና መንፈሴ በእነርሱ ላይ አይኖርም።”'),
  ('95cc5caf-a454-5b2d-a803-997aeb3ed3c7', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 9, 9, 'ስለዚህም ዘመናችን ተቀነሰ፤ ዳግመኛም ስለ በደላችንና ስለ ኀጢአታችን ዘመናችን ከቀደሙ አባቶቻችን አንሶአልና ሕፃናት ሳሉ የሚሞቱ አሉ።'),
  ('bfb5a6fb-9d63-5d4b-ad40-95ff9e2ce509', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 10, 10, 'የአባቶቻችን ዘመን ግን ትእዛዙን ስለ ጠበቁ፥ እግዚአብሔርንም ስለ አላሳዘኑት በዝቶ ነበር።'),
  ('c06005ac-200b-50aa-a971-23203b416a76', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 11, 11, 'ያስተምሯቸውም ዘንድ ሴቶች ልጆቻቸውን ገሠጹ፤ የእግዚአብሔርንም ትእዛዝ እንዳይተላለፉ ወንዶች ልጆቻቸውን ገሠጹ።'),
  ('ce6f86f3-f118-5cf6-a228-1ca93d0279f4', '72f21873-f982-5dd2-aba2-d2ef34d978ba', '4c773b04-f6be-5db1-a005-bb06725470fe', 12, 12, 'ስለዚህም ከወንዶችና ከሴቶች ልጆቻቸው ጋራ የእግዚአብሔርን ትእዛዝ ስላላፈረሱ በእውነት ዘመናቸው በዝቶ ነበር።'),
  ('924aa14e-57ff-5345-a091-7ee6784344cb', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 1, 1, 'የቃየን ልጆችም በበዙ ጊዜ በገናንና ከበሮን፥ መሰንቆንና ሳንቲን፥ ጨዋታንና ዘፈንን ሁሉ አደረጉ።'),
  ('db123fa4-30ec-5414-a1e8-6288352ec75f', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 2, 2, 'ዳግመኛም መልከ መልካም ነበረችና ስለ እርሷ ብሎ ከገደለው ከጻድቁ ከአቤል ሚስት መልከ መልካሞችና ደመግቡዎች ሴቶች ልጆች ለቃየን ተወለዱለት፤ ወንድሙንም ከገደለው በኋላ እርሷን አገባት፤ ያችም የእርሱ ነበረች።'),
  ('2054fbaf-17b3-5f28-aac8-f28177e93000', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 3, 3, 'እነርሱንም ይዞ ከአባቱ ተለይቶ በምዕራብ በኩል ወደ ቄፋዝ ሸለቆዎች ሔደ፤ የዚያች የመልከ መልካምዋ ልጆችም እንደ እናታቸው መልከ መልካሞች ነበሩ።'),
  ('661891c7-4c7a-51ce-a63f-c3bec6fd60ee', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 4, 4, 'ስለዚህም መላእክት ወደ ቃየን ልጆች ወረዱ፤ አንዲት ሰዓትም አልቈዩም፥ የመረጧቸውንም ለራሳቸው ሚስቶች አደረጉ።'),
  ('81440703-a2ff-5426-a06c-6baa7541e58f', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 5, 5, 'ስለዚህም ስለ ስሕተታቸው ከእነርሱ ጋራ በአንድነት ወደ ስሕተት ወስደውናልና እግዚአብሔር እኛንም፥ እነርሱንም ተቈጣን።'),
  ('00a0ea2a-ba00-5c91-a134-1100f36f9574', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 6, 6, 'ዲያብሎስም “እንደ ፈጣሪያችሁ እንደ እግዚአብሔር አማልክት ትሆናላችሁ” ብሎ ሸንግሎ አባታችን አዳምንና እናታችንን ሔዋንን ወደ እርሱ ስሕተት ወሰዳቸው።'),
  ('4f191bc3-015c-52a3-a5a9-30c869f907f9', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 7, 7, 'እነርሱ ግን በድንቍርናቸው እውነት መስሏቸው፥ ለቅዱስ ስሙ ይሰግዱና ያመሰግኑ ዘንድ ካለመኖር ወደ መኖር ያመጣቸውን የፈጣሪያቸውን ትእዛዝ አፈረሱ።'),
  ('67506ef2-5a8c-595d-ae67-7591c7e7ca77', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 8, 8, 'የእግዚአብሔርን ሀብት ለራሳቸው ያደረጉ እነዚያን ግን እርሱ ጌታቸው አዋረዳቸው፤ ያን ትዕቢተኛም አዋረደው።'),
  ('d8cae4f6-908e-55eb-a7b5-0e9f144d001a', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 9, 9, 'ዳዊት፥ “በኀጢአተኛ ትዕቢት ድሃው ይቃጠላል” ብሎ እንደ ተናገረ አባታችን አዳም በዲያብሎስ ትዕቢት በፈጣሪው በእግዚአብሔር ዘንድ በእውነተኛ ፍርድ ተፈርዶበታልና።'),
  ('aa636951-94fd-5ff9-a1ca-5315fe9b16a4', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 10, 10, 'እንዲሁም በቃየን ልጆች የሳቱ መላእክት ወደ ስሕተታቸው ወሰዱን። ስለዚህም እግዚአብሔር የሰጠን ዘመናችን ከአባቶቻችን ዘመን አነሰ።'),
  ('8ea47fc8-7ed6-58ec-ad89-a945b17a1241', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 11, 11, 'እነርሱ ግን በጎ ሥራ ሠርተው ነበር፤ ክፉም አይቀርባቸውም ነበር፤ ልቡናቸውን በእግዚአብሔር አጽንተው ነበርና፥ ካስተማሯቸው ከእግዚአብሔር ትእዛዝ ፈቀቅ እንዳይሉም ወንዶችና ሴቶች ልጆቻቸውን ያስተምሩ ነበርና።'),
  ('80bc8ee3-28de-58f6-ae35-3057b0a4a31b', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 12, 12, 'እነርሱ ግን በጎ ሥራ ቢሠሩ ለልጆቻቸው ካልነገሩና ካላስተማሯቸው የሚጠቅማቸው አልነበረም።'),
  ('efd9a8d9-790f-5653-a9fd-02172b177358', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 13, 13, 'ዳዊት እንደ ተናገረ፥ “ከልጆቻቸው ለሌላ ትውልድ አልሰወሩም፤ የእግዚአብሔርንም ክብር፥ ያደረገውን ኀይሉንና ተአምራቱን አስተማሩ፤ እነርሱ እንደ አስታወሱ ለልጆቻቸው ያስተምሩ ዘንድ፥ ያስተውሉና ያደርጉም ዘንድ፥ የእግዚአብሔርንም ፍርድ አደራ ይሏቸው ዘንድ፥ በሥነ ምግባራቸው እግዚአብሔርን ደስ እንዳሰኙት እንደ አባቶቻቸውም ትእዛዙን ይጠብቁ ዘንድ ነገሩ።'),
  ('bd8f3fbe-67f3-5c6d-a6dc-f5d9814e496b', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 14, 14, 'በሕፃንነታቸው እግዚአብሔርን መፍራትንና ፍርዱን እነርሱ ከአባቶቻቸው እንደ ተማሩ፥ አባቶቻቸው አደራ ያስጠበቋቸው ትእዛዙን አልተዉም።'),
  ('13ca5bae-a77e-5b92-ab06-ff6001a9ba8b', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 15, 15, 'ልጆቻቸውም ጠባያቸውን ያሳምሩ ዘንድ፥ ለፈጣሪያቸውም ክብርን ይሰጡ ዘንድ ከአባቶቻቸው ተማሩ፤ ሕጉን ጠብቀዋልና፥ እርሱንም ወደውታልና።'),
  ('60d4ab0d-b3d5-53a2-a67a-1b76dba7546c', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 16, 16, 'እርሱም ጸሎታቸውን ይሰማቸዋል፤ ልመናቸውንም ቸል አይልም፤ እርሱ ግን ይቅር ባይ ነው።'),
  ('cb7acf9d-3680-524a-aae2-03b106c9ab39', 'c8b6269e-b0b1-5fe0-aec9-43e63e576d69', '9489a65c-5493-52ef-a64b-c44f1ae30b2c', 17, 17, 'ቁጣውንም መመለስ ያበዛል፤ በመቅሠፍቱም ሁሉ አያጠፋም ነበር።”'),
  ('692fab34-c071-59bb-a40c-7734d2696bc4', '7f898196-298a-55c4-abe8-215ec8a4fcb4', 'ba9d400d-97e9-5c3b-a940-e45172adf0af', 1, 1, 'ወንድሞቻችን፥ አስቡ፤ እግዚአብሔር በጎ ሥራን የሚሠሩ ሰዎች ጽድቃቸውን እንደሚጠብቅ ቀድሞ የነገሩአችሁን አትርሱ።'),
  ('953332c7-8395-5e21-ade1-d631d71a3276', '7f898196-298a-55c4-abe8-215ec8a4fcb4', 'ba9d400d-97e9-5c3b-a940-e45172adf0af', 2, 2, 'በምድርም ላይ ፍሬያቸውን ያበዛል፤ ስም አጠራራቸውም ለበጎ ነገር እስከ ዘለዓለም ይኖራል፤ ዘራቸውም በምድር ላይ እህልን አይቸገርም።'),
  ('9a2bd11b-5b5b-568c-a890-5e32522dd0d4', '7f898196-298a-55c4-abe8-215ec8a4fcb4', 'ba9d400d-97e9-5c3b-a940-e45172adf0af', 3, 3, 'ስለ እነርሱ ይከራከርላቸዋልና፥ በጠላታቸውም እጅ አይጥላቸውምና ከባላጋራዎቻቸውና ከሚጠሏቸው ከጠላቶቻቸው ሁሉ እጅ ያድናቸዋል።'),
  ('e3ecf141-c821-540e-a7f5-8e9d5213ec71', '7f898196-298a-55c4-abe8-215ec8a4fcb4', 'ba9d400d-97e9-5c3b-a940-e45172adf0af', 4, 4, 'ስሙንም ለሚወድዱ በመከራቸው ጊዜ ረዳት ይሆናቸዋል፤ ይጠብቃቸዋልም፤ ኀጢአታቸውንም ሁሉ ይቅር ይላቸዋል።'),
  ('9e0c8691-f92d-5984-a215-2ef14983d3b4', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 1, 1, 'ዳዊት በእግዚአብሔር ተአመነ፤ በእርሱም አምኗልና መጠጊያ ሆነው፤ ከንጉሡ ከሳዖልም እጅ አዳነው።'),
  ('ba7c4454-1fcc-5e03-a20b-c7218020efa4', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 2, 2, 'ልጁ አቤሴሎምም በተነሣበት ጊዜ፥ ኢሎፍላውያንም በተነሡበት ጊዜ፥ አማሌቃውያንና ኤዶማውያን፥ ቀርኒዎናውያንም በተነሡበት ጊዜ በእርሱ አምኗልና፥ ሕጉንም ጠብቋልና ከተቃወሙት ጠላቶቹ ሁሉ እግዚአብሔር ዳዊትን አዳነው።'),
  ('6ca477a4-c4a2-58a2-a32b-d052aae6b711', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 3, 3, 'ያላመኑበትን ክፉ የሆኑ ነገሥታትን ግን እግዚአብሔር አላዳናቸውም፤ ድል መንሣት ከእግዚአብሔር ነውና በጠላቶቻቸው እጅ ድል ተነሡ እንጂ።'),
  ('87910cd1-95f2-5126-a08a-ef4e8ae84fa8', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 4, 4, 'ሕዝቅያስም በእግዚአብሔር አመነ፤ ከትዕቢተኛው ከአሶራዊውም እጅ አዳነው።'),
  ('57f7ed14-fdd6-5130-a3ec-7fa32cefd7e3', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 5, 5, 'ልጁ ምናሴ ግን እምነቱን በእግዚአብሔር አላደረገምና በጠላቱ እጅ ድል ተነሣ፤ ምናሴን ድል የነሡት እነዚያ ጠላቶቹም እንደ እርሱ አልሆኑም፤ መታመኑን በእግዚአብሔር አላደረገምና፥ ፈጽሞ ያከበረውና ያገነነው እግዚአብሔርንም አልፈራውምና አስረው ወደ ሀገራቸው ወሰዱት እንጂ፤'),
  ('cc97b6cf-f2db-5d69-a244-ff301ca90203', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 6, 6, 'ዘመኑ ይበዛ ዘንድ፥ ጠላቱንም ይከራከርለት ዘንድ በኋላና በፊትም ኀይልንና ጽንዕን ይሆነው ዘንድ በፈጣሪው በእግዚአብሔር ዘንድ መንገዱን አላሣመረምና ከሰጠው ሀብት ከለከለው።'),
  ('2509da0d-c905-57de-a010-05b0dfe54e08', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 7, 7, 'በብዙ ሠራዊትና በፈረሶች፥ በቀስትና በጋሻም ከመታመን በእግዚአብሔር መታመን ይሻላልና።'),
  ('c5f9cbfb-a958-5375-a83b-3a663ae18fda', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 8, 8, 'በእርሱም የታመነ ሰው በሕይወት ይኖራል፤ ይከብራል፤ ፈጽሞም ከፍ ከፍ ይላል።'),
  ('00d0aeaf-cba9-5bee-aac6-629fdee86f91', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 9, 9, 'እግዚአብሔር ለፊት አያዳላምና በእግዚአብሔር ያላመኑና፥ በገንዘባቸው ብዛት ያመኑ ሰዎች ግን ከሰጣቸው ጸጋና ክብር የወጡ ይሆናሉ።'),
  ('afe8afd3-b6ef-5e2e-ae3b-dc684e445176', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 10, 10, 'ያመኑበትን ግን ይጠብቃቸዋል፤ ዐላዋቂ የሚሉትን ሰዎች ግን ዐላዋቂዎች ያደርጋቸዋል፤ እግዚአብሔርንም ለመከተል፥ ሕጉንም ለመጠበቅ ልቡናቸውን አላስጨከኑምና በመከራቸው ጊዜና ጠላቶቻቸው በተቃወሙአቸው ጊዜ ፈጥኖ አይረዳቸውም።'),
  ('91300a7a-28c0-5fa0-a6bf-6fad5b2d7652', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 11, 11, 'እግዚአብሔርን በመከተል ትእዛዙንና ሕጉን ለመጠበቅ ለጨከነ ግን በመከራው ጊዜ መጠጊያ ይሆነዋል።'),
  ('42c64710-fe2c-51bd-a1ad-f5e46760e6f0', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 12, 12, 'ጠላቱን በመግደልና የጠላቱን ከብት በመማረክ፥ የጠላቱን ሀገር ሰውም በመማረክ፥ የዘመናት ዝናምን በማዝነም፥ በቡቃያውም ፍሬ፥ ክምርንም በማግባት፥ በተክሉ ቦታው ፍሬም፥'),
  ('3030dae7-d857-5689-a68b-e890c86e97bd', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 13, 13, 'በሳተኑና በበልጉም ፍሬ፥ ሣሩንና ልምላሜውን በመስጠት፥ ከእጁ በታች ያሉ ወገኖቹም ደስ ይላቸው ዘንድ የተለያዩ ፍሬዎችን በመስጠት ደስ ያሰኘዋል።'),
  ('e3d1f6a7-1319-57cd-ae60-71c266b02e23', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 14, 14, 'የሌላውን ድካም ይበሉ ዘንድ፥ ከጠላታቸውም በዘረፉት ገንዘብ ይጠግቡ ዘንድ፥ እንስሳትን፥ በጎችንና ላሞችንም ይዘርፉ ዘንድ፥ የሌላውንም ማዕድ ይበሉና ይለብሱ ዘንድ፥ የጠላቶቻቸውንም ልጆች ምርኮ ይወስዱ ዘንድ ደስ ያሰኘዋል።'),
  ('a711dde0-0f7e-5de0-a217-fa0cf2ba52f3', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 15, 15, 'እግዚአብሔርም ይህን ሁሉ ለሚወድደው ያደርግለታል፤ የሚጠላውን ግን ለጠላቱ ብዝበዛ ያደርገዋል።'),
  ('9a5e3e06-05d8-594f-ac42-658bca559cb1', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 16, 16, 'እጁንና እግሩን ያስረዋል፤ በጠላቱም እጅ ይጥለዋል፤ ለጠላቶቹም መዘባበቻ ያደርገዋል፤ የእግዚአብሔርንም ሕግ ያፈረሰ፥ ደም አፍሳሽ ሆኗልና በቤቱ ዘር ደስ አያሰኘውም።'),
  ('1206380c-f07c-5e35-a110-62e52e70f8f0', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 17, 17, 'በፍርድም ጊዜ አይጸናም፤ ለክፉ አድራጊዎችም ክፉን በሚከፍልበት ጊዜ ክፋትን ለሚሠሩ የሥራቸውን ፍሬ ይከፍላቸዋል።'),
  ('c6ebae33-3011-5c34-ac00-ee9eb3a492b7', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 18, 18, 'በጎ ለሚያደርጉ ግን በጎውን ይከፍላቸውና ሰው በእጁ ይጠብቃቸው ዘንድ ከእግዚአብሔር ታዘዘ።'),
  ('b66acbea-aa5f-52c0-a63b-ff962475e244', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 19, 19, 'እርሱም ትእዛዙን ይጠብቅ ዘንድ ታዘዘ፤ ፈቃዱንም ያደርግ፥ የፈጠረውንም እግዚአብሔርን ያመሰግን ዘንድ፥ በፍጥረቱ ሁሉ ላይ አገልጋይ ነውና፥ ከሥጋዊ ፍጥረት ሁሉ ከሰው ብቻ በቀር የፈጣሪውን ትእዛዝ የተላለፈ የለም።'),
  ('6938a980-683e-52a1-a69d-1c585811b7b2', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 20, 20, 'ሁሉም ያውቁታል፤ እግዚአብሔርም በየሥርዐታቸው የሚኖሩትን ሁሉ እንዳዘዛቸው በትእዛዙና በሕጉ ይጠበቃሉ።'),
  ('f6be407c-c6b7-5a42-a03d-035d566042cd', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 21, 21, 'ሰው ግን በአራዊትና በእንስሳ፥ በአዕዋፍም፥ በፍጥረቱም ሁሉ በአነገሠው በእግዚአብሔር ላይ ይደፋፈራል።'),
  ('3660b520-3308-5126-aaaf-46aae84a0d70', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 22, 22, 'በባሕር ያለውን፥ በየብስ ያለውንም ሁሉ ቢሆን የፈጠረውን ፍጥረት ሁሉ እግዚአብሔር ለአባታችን ለአዳም ሰጠው፤ የወደደውን ያደርግ ዘንድ፥ በምድርም እንደ እህል ይበላቸው ዘንድ፥ ይገዛቸውና ያሠራቸውም ዘንድ፥ አራዊትም ቢሆኑ፥ እንስሳትም ቢሆኑ ለሰው ይታዘዙ ዘንድ እግዚአብሔር ሰጣቸው፤ የነገሡ ሰዎችም ክብርን ለሰጣቸው ለእግዚአብሔር ይታዘዙ ዘንድ፥ ያደሉለትና ይታዘዙለት ዘንድ በፍጥረቱ ሁሉ ላይ ሾማቸው።'),
  ('b80eae53-bf07-5e22-ac61-09a61ea8ab32', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 23, 23, 'ከሕጉ ቢወጡ ግን እርሱ ከሰጣቸው ሀብት ይለያቸዋል፤ ሰማይንና ምድርን የሚገዛ ነውና ፈቃዱን ለሚያደርግ ይሰጠዋል።'),
  ('f25c4f3d-7846-565a-a101-7b11c5a1f8f0', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 24, 24, 'የወደደውን ይሾመዋል፤ የወደደውንም ይሽረዋል፤ ይገድላል፤ ያድናልም፤ ይገርፋል፤ ይቅርም ይላል።'),
  ('48e2f469-c95d-5bf9-a05b-f95c8adf5c16', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 25, 25, 'እንደ እርሱ ያለ ሌላ የለም፤ ለፈጠረው ፍጥረት ሁሉ እርሱ ጌታ ነውና የሚነቅፈው የለም፤ በላይ በሰማይ፥ በታችም በምድር ከእርሱ በቀር ሌላ አምላክ የለም።'),
  ('bb6f3275-b2d2-5f8b-a288-f367559a8213', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 26, 26, 'ይሾማል፤ ይሽራልም፤ ይገድላል፤ ያድናልም፤ ይገርፋል፤ ይቅር ይላልም፤ ያደኸያል፤ ያበለጽጋልም።'),
  ('26bb29ab-16b5-5abf-ad80-53e5e92b7cea', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 27, 27, 'የሚለምኑትን ልመናቸውን ይቀበላል፤ በንጹሕ ልቡና ፈቃዱን የሚያደርጉትንም እርሱ ጸሎታቸውን ይሰማቸዋል፤ በለመኑትም ሁሉ ፈቃዳቸውን ያደርግላቸዋል።'),
  ('b931fcd4-d642-5277-aabe-ce06785210b0', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 28, 28, 'ታላቁንና ታናሹንም እንዲታዘዙላቸው ያደርጋል፤ በተራሮችና በኮረብቶች፥ በዋሻዎችና በጫካዎች፥ በምድር ጕድጓድም፥ በባሕርና በየብስም ውስጥ ያለው ሁሉ የእነርሱ ነው።'),
  ('e5155461-18bd-5a88-ad50-f3999237a85a', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 29, 29, 'የአምላካቸውንም ፈቃድ ለሚያደርጉ፥ ሁሉ የእነርሱ ነው፤ ከበረከቱም አያሳጣቸውም፤ የምስጋናቸውንም ዋጋ ይሰጣቸዋል።'),
  ('e5b4231e-8c34-5afb-a1a7-1dfb0a9bd24e', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 30, 30, 'በሰማይም ለአባቶቻቸው ለአብርሃምና ለይስሐቅ፥ ለያዕቆብም፥ ከሕጉና ከትእዛዙ ላልወጡ ለዳዊትና ለሕዝቅያስ፥ ለሳሙኤልም ያዘጋጀውን ክብር ይሰጣቸዋል፤'),
  ('c17ffded-6173-508e-a0be-cae2478e7f6f', 'e73e9c24-1c64-5d7a-a591-831f1dd549b9', '28b30eb2-c31e-5ccd-aec2-9e2ece8e1a04', 31, 31, 'ከጥንት ጀምሮ ላገለገሉት ለአባቶቻቸው ለአብርሃምና ለይስሐቅ ለያዕቆብም የማለላቸውን ርስት ይሰጣቸው ዘንድ፥ በመንግሥቱም ደስ ይላቸው ዘንድ።'),
  ('4adb910c-10af-53cc-a60b-ef62504a4128', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 1, 1, 'በጎ ሥራን የሚሠሩትን ሰዎች ስም እስኪ አስብ፤ ሥራቸውንም አትዘንጋ።'),
  ('821dafac-2b70-56fb-ae89-a12ec6bcba60', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 2, 2, 'የእግዚአብሔርን ፈቃድ ላደረጉ ደጋግ ነገሥታትና መኳንንት ባዘጋጃት የብርሃን ማደሪያ ከእነርሱ ጋር ደስ ይልህ ዘንድ ስምህ እንደ ስማቸው እንዲሆን ቅና።'),
  ('13b3bd94-c92a-50f4-aa4c-d4ce3c8a5687', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 3, 3, 'ዳግመኛም እንደሚፈረድባቸው፥ ከሞቱም በኋላ በሰው ዘንድ እንደሚያሟቸው የክፉዎች ነገሥታትንና መኳንንትን ስም ዕወቅ፤ ተረዳም።'),
  ('8d85f7e4-f305-5a46-ae05-547e318c5bff', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 4, 4, 'እያዩና እየሰሙ መንገዳቸውን ለእግዚአብሔር አላሣመሩምና የእግዚአብሔርን ፈቃድ ከአደረጉ ከዝንጉዎችና ከከሓድያን ጋር ይፈረድባቸዋል።'),
  ('cbbb8b5c-bea9-5754-ac64-e5c7237fc567', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 5, 5, 'አንተም ቸርና የዋህ፥ ቅንም ሁን እንጂ እግዚአብሔር በተቈጣቸው በዝንጉዎች ጎዳና አትሒድ።'),
  ('184fa53d-0ff3-527c-a9ca-e32dd915d626', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 6, 6, 'በእውነትም ፍረድ፤ ባልቴቲቱንና የሙት ልጅን አጽድቅ፤ ከሚቀሟቸው ከኀጢአተኞች ሰዎች እጅ አድን።'),
  ('2b3e6e9b-2790-50b9-a73a-f2427355c16a', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 7, 7, 'ከሚቀማው እጅ ታድነው ዘንድ ለሙቱ ልጅ እንደ አባቱ ቁምለት፤ ንስሓ ያልገቡ ኃጥኣንም በሚቀመጡበት የእሳት ባሕር እንዳትደነግጥ የሙት ልጅ እንባ በፊትህ በፈሰሰ ጊዜ ደንግጥ።'),
  ('231f7a74-f968-5204-a53d-19a1bea3e024', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 8, 8, 'እግርህንም ወደ ሰላም ጎዳና አቅና፤ የእግዚአብሔር ዐይኖች ወደ ጻድቃኑ፥ ጆሮዎቹም ወደ ልመናቸው ናትና ሰላምን ፈልጋት፤ ተከተላትም።'),
  ('d777028e-339e-511a-afc0-1932418e270d', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 9, 9, 'የእግዚአብሔር ፊቱ ግን መታሰቢያቸውን ከምድር ያጠፋ ዘንድ ክፉ ሥራን ወደሚሠሩ ነው፤ በተራራና በቅጥር የሚጠጋ ወንድንም አያስቀርም።'),
  ('3e54c062-8cd9-53f7-a3a4-f2403a7da325', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 10, 10, 'ቃሌን የማይጠብቁትንም እስካጠፋቸው ድረስ ፊቴን አልመልስም። የሚጠሉኝንና ቃሌን የማይጠብቁትን የምበቀል እኔ እግዚአብሔር ቀናተኛ ነኝና።'),
  ('45038844-efa4-552a-a30b-7b18ff271e9f', '155a2e63-47a8-5035-ac1d-aa62ecf02e24', '353ee322-ebfc-5019-ae01-d3b2957942c3', 11, 11, 'የሚያከብሩኝንና ቃሌን የሚጠብቁትንም አከብራቸዋለሁ።'),
  ('a1b3b1aa-b6ef-5cbb-ae13-935b23b20205', '9424485e-5599-5cab-a247-5a37155be5df', '75328435-7ff2-550c-afdf-43b04f30f7f3', 1, 1, 'ወንድሙ የሚወድደው መስሎት በየዋህነት የተከተለውን ወንድሙን በገደለው በቃየል መንገድ አትሒድ።'),
  ('408a5a97-c696-5e18-a82d-068b5a70ff9f', '9424485e-5599-5cab-a247-5a37155be5df', '75328435-7ff2-550c-afdf-43b04f30f7f3', 2, 2, 'እርሱም በሴት ቀንቶ ወንድሙን ገደለው፤ በደልንና ቅናትን፥ ክዳትንም በባልንጀራቸው ላይ የሚያደርጉ ሰዎች እንደ እርሱ ናቸው።'),
  ('7c382222-b84b-5037-a10f-435d80f8b974', '9424485e-5599-5cab-a247-5a37155be5df', '75328435-7ff2-550c-afdf-43b04f30f7f3', 3, 3, 'በቃየል ጐዳና ሔዱ፤ በየዋሁ በአቤል መንገድም አይደለም፤ አቤል እንደ በግ የዋህ ነውና፥ ደሙም በንጹሕ ልቡና ለእግዚአብሔር እንደ ሠዉት እንደ ንጹሕ በግ ደም ነውና። በየዋሁ በአቤል መንገድ የሚሄዱ ግን እግዚአብሔርን ይወድዱታል።'),
  ('62220afe-2b9b-5a14-ab7d-fd7061629853', '9424485e-5599-5cab-a247-5a37155be5df', '75328435-7ff2-550c-afdf-43b04f30f7f3', 4, 4, 'እንደ አቤል የዋሆች ሆነዋልና እግዚአብሔርም በየዋህነት የሚሄደውን ሁሉ እንደ ጻድቁና እንደ የዋሁ አቤል ይወድደዋል።'),
  ('a2eef27b-5951-550a-a53a-dde0f00095b0', '9424485e-5599-5cab-a247-5a37155be5df', '75328435-7ff2-550c-afdf-43b04f30f7f3', 5, 5, 'ክፉዎችን ግን እግዚአብሔር ቸል ይላቸዋል፤ ፍርዳቸውም በአንገታቸው ላይ ይጠብቃቸዋል፤ በትከሻቸውም ላይ የተጻፈ ነው። በፍርድ ጊዜም በመላእክትና በሰዎች፥ በፍጥረቱም ሁሉ ፊት ያነቧታል።'),
  ('2aed16c7-013b-5393-a7af-3728348951a0', '9424485e-5599-5cab-a247-5a37155be5df', '75328435-7ff2-550c-afdf-43b04f30f7f3', 6, 6, 'የዚያን ጊዜም የእግዚአብሔርን ፈቃድ ያላደረጉ ከሓዲዎችና ዐመፀኞች ያፍራሉ።'),
  ('36d9f0fd-de4d-51f0-afa6-0ddf0039e8d0', '9424485e-5599-5cab-a247-5a37155be5df', '75328435-7ff2-550c-afdf-43b04f30f7f3', 7, 7, '“እስከ ዘለዓለሙ ድረስ መውጫ በሌለባት በገሃነመ እሳት ጨምሩዋቸው” የሚል አስደንጋጭ ቃል ይሰጣቸዋል።'),
  ('0d717e4f-1ec3-52e7-a54f-8f873278de09', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 1, 1, 'ጌዴዎን እግዚአብሔርን በታመነው ጊዜ በጥቂት ሠራዊት እልፍና የብዙ ብዙ የሆኑ፥ እንደ አንበጣም ቍጥር የሌላቸው ያልተገረዙ የአሕዛብን ሠራዊት ድል ነሣ።'),
  ('4d81cf48-a8c9-5ac4-aa60-daa38faa3ddc', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 2, 2, 'ነገሥታትና መኳንንት ሆይ! ያለ እኔ ሌላ አምላክ የለምና ሌሎች አማልክትን አትመኑ።'),
  ('b38f095b-f1dc-5ead-a92c-12f8633d2f2f', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 3, 3, 'ከእናታችሁ ማኅፀን ያወጣኋችሁ፥ ያሳደግኋችሁም፥ የመገብኋችሁም፥ ያለበስኋችሁም እኔ አምላካችሁ እግዚአብሔር ነኝና ለምን ታመካኛላችሁ? ያለ እኔስ ሌላ አምላክን ለምን ታመልካላችሁ።'),
  ('b32f98d6-aab8-5ab2-add7-3479c4b036f0', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 4, 4, 'ይኸን ሁሉ አደረግሁላችሁ፤ ምንስ ሰጣችሁኝ? እኔስ ከእናንተ ምን እሻለሁ? የነፍሳችሁን መዳን ነው እንጂ፥ በሕጌና በሥርዐቴ፥ በትእዛዜም ትሔዱ ዘንድ፥ እኔም የነፍሳችሁን ድኅነት እሰጣችሁ ዘንድ ነው እንጂ፤'),
  ('36de0cac-25ce-5b9f-aa6c-b4b8efb65640', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 5, 5, 'ሁሉን የሚገዛ እግዚአብሔር እንዲህ አለ፥ “ከጣዖትና ከጥንቆላ፥ ከሟርትም ራሳችሁን አድኑ።”'),
  ('b296689c-3e45-5b54-ad8d-704ec0249771', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 6, 6, 'በእነዚህ ይህን በሚያደርጉና በሚሰሟቸውም ላይ፥ ፈቃዳቸውን በሚያደርጉና ወዳጅም በሚሆኗቸው ላይ፥ በትእዛዛቸውም በሚሔዱ ላይ የእግዚአብሔር መቅሠፍት ይመጣባቸዋል።'),
  ('04858076-5778-592e-ac0b-14a068332baf', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 7, 7, 'የማያውቋችሁና የማይራሩላችሁ ሕዝብ ይነሡባችኋልና፥ የፈጠራችሁ የእግዚአብሔርንም ፈቃድ ካላደረጋችሁ ከነቢዩ ከሳሙኤል ጀምሮ ነቢያት እንደ ተናገሩ፥ ዳግመኛም ሕዝቅኤልና ሄኖክ እንደ ተናገሩ፥ አሳፍም እንደ ተናገረ የድካማችሁን ፍሬ ይበላሉ።'),
  ('02b76c4f-5ab7-57ae-a8f7-cc893281fee5', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 8, 8, 'እንዲህም አለ፥ “ክፉ ሰዎች ልብሳቸውን ለውጠው ይመጣሉ፤ ከመብላትና ከመጠጣት፥ በብርና በወርቅም ከማጌጥ፥ እግዚአብሔርም የማይወድደውን ሥራ ሁሉ ከመሥራት በቀር ሌላ ሕግ የላቸውም።'),
  ('2e1d11a4-9661-5d7e-ade0-8547c0821d48', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 9, 9, 'እነርሱ ግን ወደ መብልና መጠጥ ለመሄድ የተዘጋጁ ናቸው፤ ከዕንቅልፋቸውም ከነቁ በኋላ ከጧት ጀምሮ እስከ ማታ ወደ ክፉ ሥራ ይሮጣሉ። በመንገዳቸው ጕስቍልናና ጥፋት እንጂ ለእግራቸው የሰላም ጎዳና የለውም።'),
  ('71fcbd6e-86ed-5c4c-a520-f41dd17ec50e', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 10, 10, 'የሰላም መንገድንም አያውቋትም፤ በዐይኖቻቸውም ፊት እግዚአብሔርን መፍራት የለም፤ ሃይማኖትና ምግባር የሌላቸው ጠማሞችና ክፉዎች ናቸው፤ ስስታሞች፥ በላተኞችና ጠጪዎች፥ ሰካራሞችና በደላቸውም ያለ ሕግ ነው። ወደ መዳራትና ደም ወደ ማፍሰስ ወደ ስርቆትና ወደ መክዳትም፥ በግፍም የሌላውን ገንዘብ ወደ መቀማት የሚሄዱ ናቸው።'),
  ('04167aaf-87e4-5098-a9fb-68b39719fec4', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 11, 11, 'ያለ ፍርድና ያለ ሕግም የሚወቅሱ ናቸው፤ የፈጠራቸው እግዚአብሔርንም አይፈሩትምና በፊታቸው ሐፍረት የለም።'),
  ('6e451615-479c-5478-adba-416e246b6442', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 12, 12, 'የሚያዩትን የሰውን ፊት አያፍሩም፤ የሽበታምና የሽማግሌ ፊትን አያፍሩም፤ የዓለምንም ገንዘብ በሰሙ ጊዜ በዐይናቸው ሳያዩት የራሳቸው ገንዘብ ያደርጉታል፤ በዐይናቸው ፊት እግዚአብሔርን መፍራት የለምና በዐይናቸው በአዩት ጊዜ ባፋቸው የበሉት ይመስላቸዋል።'),
  ('aacbae57-a8c7-5dd3-a8c9-2de2b40f9b86', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 13, 13, 'መኳንንቶቻቸውም ያደራ ገንዘብ ይበላሉ፤ እነርሱም ከዳተኞች ናቸውና፥ በአንደበታቸውም እውነት የለምና ጧት የተናገሩትን ማታ አይደግሙትም።'),
  ('d09fab4f-4005-55b0-a13b-2d5e683b8273', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 14, 14, 'የድሆችንና የጦም አዳሪዎችን ጩኸት ቸል ይላሉና፥ ስደተኞችንም ከሚቀሟቸው እጅ አያድኗቸውምና የሚያውኩ ንጉሦቻቸው ለክፋት ይፋጠናሉ።'),
  ('ef649b5d-789e-5faf-a946-288c68bf2321', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 15, 15, 'ስለዚህም የተበደለውንና ስደተኛውን ያድኗቸው እንጂ ነገሥታቱ ፍርድን የሚነፍጉ አይሁኑ።”'),
  ('23940565-2d28-50ed-af84-3fff2d29c08e', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 16, 16, 'እነርሱ ግን ግብር የሚያስገብሩ ደምንም የሚጠጡ ወንጀለኞች ናቸው፤ መንገዳቸውም ክፉ ነውና እንቦሳዪቱን ከእናትዋ ጋር፥ ወፍንም ከጫጩቶችዋ ጋር ሲበሉ አይራሩም፤ ያዩትንና የሰሙትንም ሁሉ ለየራሳቸው ያደርጋሉ።'),
  ('58d3f128-089c-5ed3-ab18-6189819095a7', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 17, 17, 'እነርሱ ለራሳቸው ይሰበስቡ ዘንድ ይወድዳሉ እንጂ ለሕመምተኞችና ለድሆች አይራሩም፤ በዐመፅም የሌላውን ገንዘብ ይቀማሉ፤ በቤታቸው ያደልቡ ዘንድ፥ በእርሱም ደስ ይላቸው ዘንድ ያገኙትን ሁሉ ይሰበስባሉ።'),
  ('e66cbf8a-1822-58ae-a2cd-ea56d3ef1806', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 18, 18, 'ከጕድጓዱ እንደ ወጣ፥ ፍለጋውም እንደማይገኝ፥ ወደ ቤቱም እንደማይመለስ አሸን ፈጥነው ይጠፋሉና፥ በሕይወታቸው ሳሉ በጎ ሥራን ስላልሠሩ እግዚአብሔር በቍጣው በያዛቸው ጊዜ ለነፍሳቸው ወዮላት።'),
  ('bf3b2bc3-7abd-5af9-a7d8-384aae0684e6', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 19, 19, 'እግዚአብሔር ቸል ባላቸው ጊዜ በአንድ ወገን እንደ አሉ አንድ ጊዜ ይጠፋሉ፤ እግዚአብሔርም ወደ ንስሓ ይመለሱ እንደ ሆነ ይታገሣቸዋል እንጂ ለማጥፋት አይቸኩልምና በጊዜው ይጠፋሉ።'),
  ('269c3ea2-4c61-597a-acbc-caeba229275e', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 20, 20, 'ወደ ንስሓ ባይመለሱ ግን ከእነርሱ አስቀድሞ እንደ ነበሩ፥ የእግዚአብሔርን ትእዛዝ በሚገባ እንዳልጠበቁ ከእነርሱ በፊት እንደ ነበሩት ቀደምት ያጠፋቸዋል።'),
  ('fa321480-1da4-53d8-a74c-5981fa234ab2', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 21, 21, 'የሰው ሥጋ የሚበሉና የሰው ደም የሚጠጡ ናቸው፤ ወደ ኀጢኣት ለመሔድ ግፍን ይታጠቃሉና በፊታቸው ሁልጊዜ እግዚአብሔርን መፍራት የለም፤ ከመኝታቸው ከተነሡ በኋላ ዐመፅ ለመሥራት አያርፉም።'),
  ('fa206c1d-39dc-5075-abeb-301995e0bb4e', '1bf1909c-2285-5e5a-acd1-a50a9387dffd', 'c680e090-e89a-52d8-a2f6-d0d02992ffd0', 22, 22, 'በምድርም ላይ የብዙ ሰዎችን ሕይወት ያጠፉ ዘንድ፥ ሥራቸው መብላትና መጠጣት፥ ወደ ክፋትና ወደ ጥፋትም መሮጥ ነው።'),
  ('11ebd3dc-b4b7-5de9-a49f-7c25e6f2698c', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 1, 1, 'መንገዳቸው ጠማማ ነውና፥ ሁሉም የሚሄዱት በሚያስተው በሰይጣን መንገድ ነውና ሁሉን የሚገዛ እግዚአብሔር “በቍጣዬ በያዝኋት ጊዜ ለሰውነታቸው ወዮላት” ይላል።'),
  ('d645bdaf-ce62-582a-a5b2-8d16ff1961e5', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 2, 2, 'የእግዚአብሔርን መንገድ ግን አያውቁም፤ ወደ ኋላቸውም መልሰውታል፤ ሕጌንም ቸል ብለዋል።'),
  ('2d28dac7-3194-5519-a4ce-f5457930edc7', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 3, 3, 'እኔም ኋላ በፍጻሜ ዘመን እንደ ሥራቸው ክፋት እከፍላቸዋለሁ። በፍርድ ቀንም የሥራቸው ክፋት በእኔ ዘንድ እንደ ተጻፈ እበቀላቸዋለሁ፤ የምገድል፥ የማድንም፥ የምገርፍ፥ ይቅር የምልም እኔ እግዚአብሔር ነኝና ከእጄ አያመልጡም።'),
  ('a4bc5774-bed1-51e4-a97b-d6fcbfeaaa40', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 4, 4, 'እኔ እግዚአብሔር ከአድማስ እስከ አድማስ ምሉ ነኝና፥ ፍጥረቱም ሁሉ በእጄ ነውና ከምድር በታችና ከሰማይ በላይ፥ በባሕርና በውኃዎችም ጥልቅ ከእጄ የሚያመልጥ የለም።'),
  ('ea990c85-60b4-5b8f-a037-0bfa724b6efd', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 5, 5, 'በምድር በታች እባብን፥ በባሕርም ውስጥ ዓሣን፥ በአየርም ያሉ ወፎችን፥ በምድረ በዳም የሜዳ አህያውን አዝዛለሁ። ከአድማስ ጀምሮ እስከ አድማስ ድረስ የእኔ ነውና።'),
  ('1c228205-d13c-533b-a1b6-b7bee8fe46a7', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 6, 6, 'በፊቴ ድንቅ ሥራንና ታምራትን የማደርግ እኔ ነኝና በላይ በሰማይ፥ በታችም በምድር ከእጄ የሚያመልጥ የለም፤ ወዴት ትሔዳለህ? ምንስ ትሠራለህ? የሚለኝም የለም።'),
  ('faad2115-3ee7-5559-a0ff-737a72917a25', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 7, 7, 'እኔም በመላእክት አለቆችና ሠራዊት ላይ አዝዛለሁ፤ የሚጠራው ስም ሁሉ የእኔ ነው፤ የሰማይ ወፎችም ሁሉ፥ የዱር አራዊትና እንስሳትም ሁሉ የእኔ ናቸው።'),
  ('e024f8bd-f57d-505e-a220-396874293348', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 8, 8, 'የአዜብ ነፋስ የመስዕም ሐሩር ይነሣል፤ የኤርትራ ባሕርም በኋላ ዘመን ወደ እርሷ ከሚመጣው ግርማ የተነሣ ትደረፃለች።'),
  ('1b69dcf4-6d68-59da-a9df-830500ee16cb', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 9, 9, 'እርሱ ሕያዋንንና ሙታንን ከኖባና ከሳባ፥ ከኢትዮጵያና ከሕንደኬ፥ ከአውራጃዎቻቸውና ከወሰናቸው ሁሉ ጋር ይገዛልና።'),
  ('13eee548-75a0-5fd9-a62b-de04b9e6e69f', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 10, 10, 'በእጁ ባለው በትርም በየዋህነት ሁሉን ይጠብቃል፤ ብትሩም ከበትሮች ሁሉ ይበልጣልና በጎቹን በበትሩ ይጠብቃል።'),
  ('e9339741-7f30-5979-a13a-0f666b875dac', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 11, 11, 'ቀንዱም ከቀንዶች ሁሉ ይበልጣል። መንግሥቱም ከመንግሥት ሁሉ ከፍ ይላል። ሥልጣኑም ዓለሙን ሁሉ የሚገዛ ነው፤ ሁሉንም የሚችል ነው፤ የሚሳነውም የለም።'),
  ('1ba7fd56-4dc2-52f8-a097-a8beb932d876', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 12, 12, 'በላይ ደመናዎችን ያዝዛል፤ በታች ለእንስሳት ሣርን ያበቅላል፥ በዝርዝሩም ላይ ፍሬን ይሰጣል።'),
  ('ffa31ca0-df80-57e1-afbd-7b3029beac07', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 13, 13, 'እንደ ወደደ ለሁሉ በየወገኑ ይመግባል፤ በየፍሬውም፥ በየምግቡም የፈጠረውን ሁሉ ይመግባል፤ በምድር በታችም ለገብረ ጕንዳን፥ ለኵብኩባ፥ ከምድር በላይም ለአውሬዎችና ለእንስሳት ይመግባቸዋል፤ ለሚጸልይም ጸሎቱን ይሰጠዋል፤ የባልቴቶችንና የሙት ልጆችን ልመና ቸል አይልም።'),
  ('bc2daba3-d8b3-587c-a889-56d52c077505', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 14, 14, 'ይልቁንም በየጊዜው ወደ እርሱ የሚለምኑ የንጹሓንን ጸሎት ይቀበላል። የክፉ ሰዎች ወንጀላቸው እንደ ጥቅል ነፋስ፥ የበደለኞችም ጉባኤያቸው እንደ ጉም ሽንት ነውና።'),
  ('2a8160e2-d6be-59fa-ab28-5ea528767c42', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 15, 15, 'ደስታቸውም እንደምትበር ወፍ ነውና፥ የብርና የወርቅ የሚሆን የመልካቸውም ደም ግባት በምድር ጠፊ ነውና ለዝንጉዎች መመርመሪያቸው ነው እንጂ ወርቃቸው አይጠቅማቸውም፤ ልብሳቸውንም ብል ይበላዋል።'),
  ('a4c5d33a-df68-59e4-adb7-144e11894abf', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 16, 16, 'የእህሉና የስንዴው ድልብም በትልና በነቀዝ ይበላል፤ ሁሉም ትናንትና እንዳለፈችው ቀን ያልፋል፤ ከአፍ የወጣ ቃልም እንደማይመለስ የኃጥአን ብዕላቸው እንደዚሁ ነው፤ የአማረ አኗኗራቸውም እንደሚያልፍ ጥላ ነው፤ የኃጥኣንም ብዕላቸው በእግዚአብሔር ፊት እንደ ተውሶ ልብስ ነው።'),
  ('432b1f80-5ac3-55fa-ab73-945fb95739ee', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 17, 17, 'ጻድቃን ግን ቢበለጽጉ እግዚአብሔር ቸል አይላቸውም፤ ለድሃ እየራሩ፥ የሙት ልጆችንና የችግረኞችን ፍርድ እያዳመጡ፥ ከልብሳቸውም ለተራቆቱት እያለበሱ፥ እግዚአብሔር ከሰጣቸው ከቤታቸው ጥሪት ቸል ሳይሉ ለስደተኛውና ለጦም አዳሪው ይሰጡ ዘንድ በልጽገዋልና።'),
  ('6881b69f-ac38-5fbc-a241-3e992a1e0c64', '2e026591-197b-5ad4-adfb-669ef6938c48', 'bf5df40d-fd73-5213-af61-571b117472b2', 18, 18, 'የመሃይምናንንም ፍርድ አያደሉም፤ የምንደኛውንም ደመወዝ አያሳድሩም፤ የእግዚአብሔር ነገር አፉ ሁለት እንደ ሆነ ሰይፍ እውነትና ክቡር ነውና በወራቶቻቸው ቍጥር፥ በሚዛናቸውም ልክ ዐመፅን አያደርጉም።'),
  ('919013a2-68ba-53ba-a0f2-f3689dfe4212', '0ac55b91-002b-57e3-af49-cea7b9c1b229', '769dff44-991b-53a5-a1ad-ba8140407411', 1, 1, 'ድሆች ግን ዳግመኛ በመኝታቸው ያስባሉ፤ ባለጠጎች ካልተቀበሏቸውም ልምላሜ እንደሌለው እንደ ደረቅ እንጨት ይሆናሉ፤ ርጥበትም ከሌለ ሥር አይለመልምም፤ ሥርም ከሌለ ቅጠሉ አይለመልምም።')
